@api.post("/admin/practice/members")
async def create_practice_member(
    payload: PracticeMemberCreate,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    require_practice_permission(user, "practice_members.manage")
    email = str(payload.email).lower().strip()
    if await get_user_by_email(session, email):
        raise HTTPException(status_code=400, detail="A user with this email already exists")
    if len(payload.password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    role = clean_member_role(payload.role)
    permissions = sorted(PRACTICE_PERMISSION_CATALOG) if role == "practice_admin" else clean_permissions(payload.permissions)
    doc = {
        "id": new_id(),
        "email": email,
        "password_hash": hash_password(payload.password),
        "role": role,
        "practice_id": str(user["practice_id"]),
        "permissions_json": json.dumps({"permissions": permissions}),
        "first_name": payload.first_name.strip(),
        "last_name": payload.last_name.strip(),
        "job_title": clean_optional_text(payload.job_title),
        "status": "active",
        "created_at": utc_now_iso(),
    }
    await session.execute(insert(users).values(**doc))
    await session.commit()
    return {"ok": True, "member": serialize_user(doc)}


@api.put("/admin/practice/members/{member_id}")
async def update_practice_member(
    member_id: str,
    payload: PracticeMemberUpdate,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    require_practice_permission(user, "practice_members.manage")
    member = await one(
        session,
        select(users).where(
            users.c.id == member_id,
            users.c.practice_id == str(user["practice_id"]),
            users.c.role.in_(list(PRACTICE_ROLES)),
        ),
    )
    if not member:
        raise HTTPException(status_code=404, detail="Practice member not found")
    values = payload.model_dump(exclude_unset=True)
    if "role" in values and values["role"] is not None:
        values["role"] = clean_member_role(values["role"])
    next_role = values.get("role", member.get("role"))
    if "permissions" in values:
        permissions = sorted(PRACTICE_PERMISSION_CATALOG) if next_role == "practice_admin" else clean_permissions(values.pop("permissions"))
        values["permissions_json"] = json.dumps({"permissions": permissions})
    elif next_role == "practice_admin":
        values["permissions_json"] = json.dumps({"permissions": sorted(PRACTICE_PERMISSION_CATALOG)})
    if "status" in values:
        values["status"] = str(values["status"] or "").lower()
        if values["status"] not in {"active", "inactive"}:
            raise HTTPException(status_code=400, detail="Invalid member status")
    removes_admin = member.get("role") in {"admin", "practice_admin"} and (
        next_role not in {"admin", "practice_admin"} or values.get("status", member.get("status")) == "inactive"
    )
    if removes_admin:
        active_admins = await count_rows(
            session,
            users,
            users.c.practice_id == str(user["practice_id"]),
            users.c.role.in_(["admin", "practice_admin"]),
            users.c.status == "active",
        )
        if active_admins <= 1:
            raise HTTPException(status_code=400, detail="A practice must retain at least one active practice administrator")
    if "new_password" in values:
        new_password = str(values.pop("new_password") or "")
        if new_password:
            if len(new_password) < 8:
                raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
            values["password_hash"] = hash_password(new_password)
    for key in ("first_name", "last_name", "job_title"):
        if key in values:
            values[key] = clean_optional_text(values[key])
    await session.execute(update(users).where(users.c.id == member_id).values(**values))
    await session.commit()
    return {"ok": True, "member": serialize_user({**member, **values})}


# ---------- Admin: Clients ----------
@api.get("/admin/clients")
async def list_clients(
    q: Optional[str] = None,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    require_practice_permission(user, "clients.manage")
    stmt = select(users).where(
        users.c.role == "client",
        users.c.practice_id == user["practice_id"],
    )
    if q:
        like = f"%{q}%"
        stmt = stmt.where(
            or_(
                users.c.first_name.ilike(like),
                users.c.last_name.ilike(like),
                users.c.business_name.ilike(like),
                users.c.email.ilike(like),
            )
        )
    docs = await many(session, stmt.order_by(users.c.business_name.asc()))
    result = []
    for d in docs:
        s = serialize_user(d)
        s["purchase_outstanding"] = await count_rows(
            session,
            outstanding_items,
            outstanding_items.c.client_id == str(d["id"]),
            outstanding_items.c.type == "purchase",
        )
        s["sales_outstanding"] = await count_rows(
            session,
            outstanding_items,
            outstanding_items.c.client_id == str(d["id"]),
            outstanding_items.c.type == "sales",
        )
        result.append(s)
    return result


@api.post("/admin/clients")
async def create_client(
    payload: ClientCreate,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    email = payload.email.lower().strip()
    require_practice_permission(user, "clients.manage")
    if await get_user_by_email(session, email):
        raise HTTPException(status_code=400, detail="A user with this email already exists")
    if len(payload.password) < 6:
        raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
    accounting_destination = clean_accounting_destination(payload.accounting_destination, payload.native_accounting_enabled)
    native_accounting_enabled = accounting_destination == "native"
    doc = {
        "id": new_id(),
        "email": email,
        "password_hash": hash_password(payload.password),
        "role": "client",
        "practice_id": user["practice_id"],
        "first_name": payload.first_name.strip(),
        "last_name": payload.last_name.strip(),
        "business_name": payload.business_name.strip(),
        "autoentry_email": payload.autoentry_email.lower().strip(),
        "sales_autoentry_email": payload.sales_autoentry_email.lower().strip() if payload.sales_autoentry_email else None,
        "is_vat_client": bool(payload.is_vat_client),
        "ai_analysis_enabled": bool(payload.ai_analysis_enabled),
        "accounting_destination": accounting_destination,
        "native_accounting_enabled": native_accounting_enabled,
        "native_accounting_created_at": utc_now_iso() if native_accounting_enabled else None,
        "status": payload.status or "active",
        "created_at": utc_now_iso(),
    }
    for field in CLIENT_PRACTICE_FIELDS:
        doc[field] = clean_optional_text(getattr(payload, field, None))
    await session.execute(insert(users).values(**doc))
    if doc["native_accounting_enabled"]:
        await ensure_native_accounting_client(session, doc["id"])
    await session.commit()
    return serialize_user(doc)


@api.get("/admin/clients/{client_id}")
async def get_client(
    client_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    d = await one(session, select(users).where(users.c.id == client_id, users.c.role == "client"))
    if not d:
        raise HTTPException(status_code=404, detail="Client not found")
    return serialize_user(d)


@api.put("/admin/clients/{client_id}")
async def update_client(
    client_id: str,
    payload: ClientUpdate,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    values = {
        k: v
        for k, v in payload.model_dump(exclude_unset=True).items()
        if v is not None or k == "sales_autoentry_email"
    }
    if "email" in values:
        values["email"] = values["email"].lower().strip()
        other = await one(
            session,
            select(users).where(users.c.email == values["email"], users.c.id != client_id),
        )
        if other:
            raise HTTPException(status_code=400, detail="Email already in use")
    if "autoentry_email" in values:
        values["autoentry_email"] = values["autoentry_email"].lower().strip()
    if "sales_autoentry_email" in values:
        values["sales_autoentry_email"] = values["sales_autoentry_email"].lower().strip() if values["sales_autoentry_email"] else None
    if "accounting_destination" in values or "native_accounting_enabled" in values:
        current = await get_user_by_id(session, client_id)
        destination_input = values.get("accounting_destination")
        native_enabled_input = bool(values.get("native_accounting_enabled", (current or {}).get("native_accounting_enabled", False)))
        values["accounting_destination"] = clean_accounting_destination(destination_input if destination_input is not None else (current or {}).get("accounting_destination"), native_enabled_input)
        values["native_accounting_enabled"] = values["accounting_destination"] == "native"
        if values["native_accounting_enabled"] and "native_accounting_created_at" not in values:
            if current and not current.get("native_accounting_created_at"):
                values["native_accounting_created_at"] = utc_now_iso()
    for field in CLIENT_PRACTICE_FIELDS:
        if field in values:
            values[field] = clean_optional_text(values[field])
    if values:
        result = await session.execute(
            update(users).where(users.c.id == client_id, users.c.role == "client").values(**values)
        )
        if result.rowcount == 0:
            await session.rollback()
            raise HTTPException(status_code=404, detail="Client not found")
        if values.get("native_accounting_enabled"):
            await ensure_native_accounting_client(session, client_id)
        await session.commit()
    d = await get_user_by_id(session, client_id)
    if not d:
        raise HTTPException(status_code=404, detail="Client not found")
    return serialize_user(d)


@api.delete("/admin/clients/{client_id}")
async def delete_client(
    client_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    result = await session.execute(delete(users).where(users.c.id == client_id, users.c.role == "client"))
    if result.rowcount == 0:
        await session.rollback()
        raise HTTPException(status_code=404, detail="Client not found")
    await session.execute(delete(outstanding_items).where(outstanding_items.c.client_id == client_id))
    await session.execute(delete(submissions).where(submissions.c.client_id == client_id))
    await session.commit()
    return {"ok": True}


# ---------- Admin: Native Accountancy Software ----------
def serialize_native_account(row: dict) -> dict:
    row = dict(row)
    account_type = str(row.get("account_type") or "").strip()
    category = str(row.get("category") or "").strip() or infer_account_category(account_type)
    statement_section = str(row.get("statement_section") or account_statement_section(row))
    system_role = str(row.get("system_role") or account_system_role(row, bool(row.get("module_required"))))
    control = system_role in TRUE_CONTROL_ROLES
    row["category"] = category
    row["purpose"] = str(row.get("purpose") or "").strip() or infer_account_purpose(row)
    row["statement_section"] = statement_section
    row["statement_type"] = statement_section
    row["system_role"] = system_role
    row["is_control_account"] = control
    row["control_account"] = control
    row["banking_enabled"] = account_banking_enabled(row)
    row["show_in_banking"] = row["banking_enabled"]
    row["show_in_banking_page"] = row["banking_enabled"]
    row["current_balance"] = row.get("current_balance") or "0.00"
    row["opening_balance"] = money_str(money(row.get("opening_balance")))
    row["description"] = row.get("description") or ""
    row["module"] = str(row.get("module") or "CORE").strip().upper()
    row["default_active"] = str(row.get("default_active") or ("Active" if row.get("active", True) else "Inactive")).strip().title()
    row["account_class"] = str(row.get("account_class") or category).strip()
    row["account_subtype"] = str(row.get("account_subtype") or account_type).strip()
    row["statement"] = trial_balance_account_statement(row)
    row["control_account_type"] = str(row.get("control_account_type") or ("Bank" if row["banking_enabled"] else "None")).strip()
    row["allow_manual_posting"] = not control if row.get("allow_manual_posting") is None else bool(row.get("allow_manual_posting"))
    row["system_account"] = bool(row.get("system_account"))
    row["filing_status"] = trial_balance_filing_status(row)
    row["reporting_category_id"] = row.get("reporting_category_id")
    row["internal_reporting_category"] = str(row.get("internal_reporting_category") or "").strip()
    row["statutory_presentation"] = str(row.get("statutory_presentation") or "").strip()
    row["cash_flow_category"] = str(row.get("cash_flow_category") or "").strip()
    row["default_tax_treatment"] = str(row.get("default_tax_treatment") or "").strip()
    row["vat_behaviour"] = str(row.get("vat_behaviour") or "").strip()
    row["cis_role"] = str(row.get("cis_role") or "").strip()
    row["requires_dimension"] = str(row.get("requires_dimension") or "").strip()
    row["current_noncurrent_rule"] = str(row.get("current_noncurrent_rule") or "").strip()
    row["suggested_taxonomy_concept"] = str(row.get("suggested_taxonomy_concept") or "").strip()
    row["implementation_note"] = str(row.get("implementation_note") or "").strip()
    postings_count = int(row.get("postings_count") or row.get("transaction_count") or row.get("posted_transactions") or 0)
    row["postings_count"] = postings_count
    row["transaction_count"] = postings_count
    row["posted_transactions"] = postings_count
    row["module_required"] = bool(row.get("module_required"))
    row["system_account"] = bool(row.get("system_account"))
    row["protected"] = bool(row.get("protected")) or (statement_section == "balance_sheet" and system_role != "none")
    row["mandatory"] = row["protected"]
    row["can_delete"] = bool(row.get("can_delete"))
    row["delete_block_reason"] = str(row.get("delete_block_reason") or "")
    return row


DEFAULT_NATIVE_ACCOUNT_BY_CODE = {str(account["code"]): account for account in DEFAULT_NATIVE_ACCOUNTS}
