async def ensure_ap_settings(session: AsyncSession, client_id: str) -> dict:
    existing = await one(session, select(accounting_ap_settings).where(accounting_ap_settings.c.client_id == client_id))
    if existing:
        return existing
    accounting_defaults = await ensure_accounting_settings(session, client_id)
    row = default_ap_settings(client_id, accounting_defaults)
    await session.execute(insert(accounting_ap_settings).values(**row))
    await session.flush()
    return row


def parse_date_or_today(value: Any) -> date:
    raw = str(value or "").strip()
    if raw:
        try:
            return datetime.fromisoformat(raw[:10]).date()
        except Exception:
            pass
    return datetime.now(timezone.utc).date()


def parse_ap_document_date(value: Any, field_label: str) -> date:
    raw = str(value or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail=f"{field_label} is required.")
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%d %b %Y", "%d %B %Y"):
        try:
            return datetime.strptime(raw[:32], fmt).date()
        except ValueError:
            continue
    try:
        return datetime.fromisoformat(raw[:10]).date()
    except Exception:
        raise HTTPException(status_code=400, detail=f"{field_label} must be a valid date.")


def nominal_account_code_value(value: Any, default_account: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return str(default_account or "5000").strip()[:32]
    if " - " in raw:
        raw = raw.split(" - ", 1)[0].strip()
    else:
        match = re.match(r"^([A-Za-z0-9_.-]+)\s+", raw)
        if match:
            raw = match.group(1)
    return raw[:32]


def vat_code_value(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    if " - " in raw:
        raw = raw.split(" - ", 1)[0].strip()
    # Older native screens stored labels such as "20% S (20%)". Keep accepting
    # those values, but persist only the canonical native code.
    match = re.match(r"^(.*?)\s+\(\s*\d+(?:\.\d+)?%\s*\)$", raw)
    if match:
        raw = match.group(1).strip()
    return raw[:255]


def first_present(mapping: dict, *keys: str) -> Any:
    for key in keys:
        value = mapping.get(key)
        if value not in (None, ""):
            return value
    return None


def submitted_item_attachment_url(filename: Any) -> str:
    name = Path(str(filename or "")).name
    return f"/api/admin/uploads/{name}" if name else ""


def upload_path_candidates(filename: Any) -> list[Path]:
    raw = str(filename or "").strip().replace("\\", "/")
    if not raw:
        return []
    trimmed = raw.lstrip("/")
    if not trimmed or ":" in trimmed:
        return []
    candidates: list[Path] = []
    parts = [part for part in trimmed.split("/") if part and part != "."]
    if parts and ".." not in parts:
        candidates.append(UPLOAD_DIR.joinpath(*parts))
    basename = Path(trimmed).name
    if basename and basename != trimmed:
        candidates.append(UPLOAD_DIR / basename)
    unique: list[Path] = []
    seen = set()
    for candidate in candidates:
        key = str(candidate)
        if key not in seen:
            unique.append(candidate)
            seen.add(key)
    return unique


def resolve_upload_path(filename: Any) -> Optional[Path]:
    for candidate in upload_path_candidates(filename):
        if candidate.exists() and candidate.is_file():
            return candidate
    return None


def ap_invoice_attachment_url(client_id: Any, invoice: dict) -> str:
    invoice_id = str(invoice.get("id") or "").strip()
    has_source = bool(str(invoice.get("source_submission_id") or "").strip())
    has_attachment = bool(str(invoice.get("attachment_path") or "").strip())
    if client_id and invoice_id and (has_source or has_attachment):
        return f"/api/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}/attachment"
    return ""


async def ap_invoice_attachment_file(session: AsyncSession, client_id: str, invoice: dict) -> tuple[Path, str]:
    filename = str(invoice.get("attachment_path") or "").strip()
    original_filename = str(invoice.get("original_filename") or "").strip()
    submission_id = str(invoice.get("source_submission_id") or "").strip()
    if submission_id:
        submission = await one(session, select(submissions).where(submissions.c.id == submission_id, submissions.c.client_id == client_id))
        if submission:
            filename = str(submission.get("image_filename") or filename or "").strip()
            original_filename = str(submission.get("original_filename") or original_filename or filename).strip()
    path = resolve_upload_path(filename)
    if not filename:
        raise HTTPException(status_code=404, detail="AP invoice source document not found")
    if not path:
        raise HTTPException(status_code=404, detail="AP invoice source document file not found")
    return path, Path(original_filename or Path(str(filename)).name).name


