def subledger_attachment_url(client_id: Any, row: dict, module: str) -> str:
    record_id = str(row.get("id") or "").strip()
    if not client_id or not record_id or not str(row.get("attachment_path") or "").strip():
        return ""
    route = "ap/payments" if module == "ap" else "ar/receipts"
    return f"/api/admin/accounting/clients/{client_id}/{route}/{record_id}/attachment"


def subledger_attachment_file(row: dict, label: str) -> tuple[Path, str]:
    filename = str(row.get("attachment_path") or "").strip()
    path = resolve_upload_path(filename)
    if not filename:
        raise HTTPException(status_code=404, detail=f"{label} supporting document not found")
    if not path:
        raise HTTPException(status_code=404, detail=f"{label} supporting document file not found")
    original = Path(str(row.get("original_filename") or path.name)).name
    return path, original


async def invoice_source_document_reference(session: AsyncSession, client_id: str, invoice: dict, attachment_url: str, label: str) -> dict:
    filename = str(invoice.get("attachment_path") or "").strip()
    original_filename = str(invoice.get("original_filename") or "").strip()
    submission_id = str(invoice.get("source_submission_id") or "").strip()
    if submission_id:
        submission = await one(session, select(submissions).where(submissions.c.id == submission_id, submissions.c.client_id == client_id))
        if submission:
            filename = str(submission.get("image_filename") or filename or "").strip()
            original_filename = str(submission.get("original_filename") or original_filename or filename).strip()
    has_reference = bool(submission_id or filename)
    available = bool(resolve_upload_path(filename)) if filename else False
    status = "available" if available else ("missing" if has_reference else "none")
    message = ""
    if status == "missing":
        message = f"{label} source document file not found"
    return {
        "source_submission_id": submission_id,
        "attachment_path": filename,
        "original_filename": Path(original_filename or Path(str(filename)).name).name if (original_filename or filename) else "",
        "attachment_url": attachment_url if has_reference else "",
        "document_url": attachment_url if has_reference else "",
        "available": available,
        "missing": status == "missing",
        "status": status,
        "message": message,
    }


def ap_line_values(raw_line: dict, default_account: str = "5000") -> dict:
    quantity = money(first_present(raw_line, "quantity", "units"), "1.00")
    unit_price = money(first_present(raw_line, "unit_price", "price", "rate"))
    discount = money(first_present(raw_line, "discount_amount", "discount"))
    explicit_net = first_present(raw_line, "net_amount", "net", "subtotal")
    net_amount = money(explicit_net) if explicit_net not in (None, "") else (quantity * unit_price - discount).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    vat_amount = money(first_present(raw_line, "vat_amount", "vat", "tax_amount", "tax"))
    explicit_gross = first_present(raw_line, "gross_amount", "gross", "total", "amount")
    gross_amount = money(explicit_gross) if explicit_gross not in (None, "") else net_amount + vat_amount
    nominal_source = first_present(
        raw_line,
        "nominal_account_code",
        "purchase_nominal_account_code",
        "purchase_nominal",
        "purchase_account_code",
        "account_code",
        "category_code",
        "nominal_code",
        "nominal",
        "category",
        "account",
    )
    vat_source = first_present(raw_line, "vat_code", "tax_code", "tax_rate_code")
    return {
        "description": str(raw_line.get("description") or "").strip(),
        "nominal_account_code": nominal_account_code_value(nominal_source, default_account or "5000"),
        "location_id": str(raw_line.get("location_id") or "").strip() or None,
        "dimension_id": str(raw_line.get("dimension_id") or "").strip() or None,
        "quantity": money_str(quantity),
        "unit_price": money_str(unit_price),
        "discount_amount": money_str(discount),
        "vat_code": vat_code_value(vat_source),
        "net_amount": money_str(net_amount),
        "vat_amount": money_str(vat_amount),
        "gross_amount": money_str(gross_amount),
    }


def submission_lines_with_single_line_header_fallback(
    header: dict,
    raw_lines: list[dict],
    default_account: str,
) -> list[dict]:
    """Fill a skeletal single submitted-item line from its reviewed header.

    Submitted Items stores explicit line values, but older/native publishes can
    contain a single description-only line while the reviewed net/VAT/gross,
    nominal and VAT code remain on the header.  Applying the fallback only when
    there is one line avoids copying header totals across genuine multi-line
    documents.
    """
    lines = [dict(line) for line in raw_lines if isinstance(line, dict)]
    if len(lines) != 1:
        return lines
    line = lines[0]
    net_value = first_present(header, "net_amount", "net")
    vat_value = first_present(header, "vat_amount", "vat")
    gross_value = first_present(header, "gross_amount", "gross", "total")
    skeletal_amounts = (
        money(first_present(line, "net_amount", "net", "subtotal")) == Decimal("0.00")
        and money(first_present(line, "gross_amount", "gross", "total", "amount")) == Decimal("0.00")
        and money(gross_value) != Decimal("0.00")
    )
    nominal_value = first_present(
        header,
        "nominal_account_code",
        "purchase_nominal_account_code",
        "purchase_account_code",
        "sales_nominal_code",
        "sales_nominal",
        "sales_account_code",
        "account_code",
        "category_code",
        "category",
    ) or default_account
    if skeletal_amounts or first_present(line, "nominal_account_code", "purchase_nominal_account_code", "purchase_account_code", "sales_nominal_code", "sales_account_code", "account_code", "category_code", "category") in (None, ""):
        line["nominal_account_code"] = nominal_value
    if skeletal_amounts or first_present(line, "vat_code", "tax_code", "tax_rate_code") in (None, ""):
        line["vat_code"] = first_present(header, "vat_code", "tax_code", "tax_rate_code")
    if skeletal_amounts or first_present(line, "net_amount", "net", "subtotal") in (None, ""):
        line["net_amount"] = net_value
    if skeletal_amounts or first_present(line, "vat_amount", "vat", "tax_amount", "tax") in (None, ""):
        line["vat_amount"] = vat_value
    if skeletal_amounts or first_present(line, "gross_amount", "gross", "total", "amount") in (None, ""):
        line["gross_amount"] = gross_value
    if skeletal_amounts or first_present(line, "unit_price", "price", "rate") in (None, ""):
        line["unit_price"] = net_value
    if not str(line.get("description") or "").strip():
        line["description"] = header.get("description") or ""
    return [line]


def ap_totals(lines: list[dict]) -> dict:
    net = sum((money(line.get("net_amount")) for line in lines), Decimal("0.00"))
    vat = sum((money(line.get("vat_amount")) for line in lines), Decimal("0.00"))
    gross = sum((money(line.get("gross_amount")) for line in lines), Decimal("0.00"))
    if gross == Decimal("0.00") and (net or vat):
        gross = net + vat
    return {"net_amount": money_str(net), "vat_amount": money_str(vat), "gross_amount": money_str(gross)}


def serialize_ap_settings(row: dict) -> dict:
    return dict(row)


def serialize_native_contact(row: dict) -> dict:
    row = dict(row)
    row["raw_json"] = parse_json_object(row.get("raw_json")) or {}
    return row


def serialize_ap_supplier(
    profile: dict,
    contact: Optional[dict] = None,
    balance: Decimal = Decimal("0.00"),
    on_account_credit: Decimal = Decimal("0.00"),
) -> dict:
    row = dict(profile)
    contact = contact or {}
    row["name"] = contact.get("name") or profile.get("trading_name") or profile.get("supplier_code") or "Supplier"
    row["email"] = contact.get("email") or ""
    row["external_id"] = contact.get("external_id") or ""
    row["account_code"] = contact.get("account_code") or ""
    row["supplier_id"] = row.get("id")
    row["supplier_name"] = row["name"]
    row["code"] = row.get("supplier_code") or row["account_code"] or ""
    row["active"] = bool(contact.get("active", True)) and str(row.get("status") or "active").lower() == "active"
    row["is_system_supplier"] = bool(row.get("is_system_supplier"))
    row["isSystemSupplier"] = row["is_system_supplier"]
    row["supplier_category"] = str(row.get("supplier_category") or "Trade")
    row["supplierCategory"] = row["supplier_category"]
    system_definition = SYSTEM_AP_SUPPLIER_BY_CATEGORY.get(row["supplier_category"]) if row["is_system_supplier"] else None
    row["system_icon"] = (system_definition or {}).get("icon", "")
    row["system_authority_label"] = (system_definition or {}).get("authority_label", "")
    row["system_usage"] = list((system_definition or {}).get("used_by", []))
    row["system_purpose"] = list((system_definition or {}).get("purpose", []))
    row["protected_fields"] = [
        "name", "supplier_code", "supplier_category", "status", "trading_name", "email", "phone",
        "website", "default_currency", "addresses", "contacts", "payment_terms", "tax",
    ] if row["is_system_supplier"] else []
    net_balance = balance - on_account_credit
    row["outstanding_balance"] = money_str(balance)
    row["on_account_balance"] = money_str(on_account_credit)
    row["payment_on_account_balance"] = money_str(on_account_credit)
    row["net_balance"] = money_str(net_balance)
    row["current_balance"] = money_str(net_balance)
    row["balance"] = money_str(net_balance)
    return row


