def period_contains_date(period: dict, value: str) -> bool:
    entry_date = str(value or "")[:10]
    return bool(entry_date and str(period.get("period_start") or "") <= entry_date <= str(period.get("period_end") or ""))


def financial_year_contains_date(year: dict, value: str) -> bool:
    entry_date = str(value or "")[:10]
    return bool(entry_date and str(year.get("start_date") or "") <= entry_date <= str(year.get("end_date") or ""))


def account_balance_direction(account: dict, balance: Decimal) -> tuple[Decimal, Decimal]:
    if balance >= Decimal("0.00"):
        return balance, Decimal("0.00")
    return Decimal("0.00"), -balance


TRIAL_BALANCE_DATE_MODES = {"movement", "as_at", "financial_year"}
LEGACY_BLOCKED_ACCOUNT_CODES = {"1190", "2190", "2201", "4030", "4090", "6250", "6290", "9999"}


def trial_balance_account_statement(account: dict) -> str:
    configured = str(account.get("statement") or account.get("accounts_statement") or "").strip()
    if configured:
        return configured
    category = str(account.get("category") or "").strip().lower()
    if category in {"income", "other income", "expense", "other expense"}:
        return "P&L"
    if category == "memorandum":
        return "Memorandum"
    return "Balance Sheet"


def trial_balance_filing_status(account: dict) -> str:
    configured = str(account.get("filing_status") or "").strip().title()
    code = str(account.get("code") or "").strip()
    if code in LEGACY_BLOCKED_ACCOUNT_CODES and configured in {"", "Ready"}:
        return "Blocked"
    if configured in {"Ready", "Review", "Blocked", "Inactive"}:
        return configured
    return "Ready"


def trial_balance_rows_from_balances(
    accounts: list[dict],
    balances_by_account_id: dict[str, Decimal],
    balances_by_code: Optional[dict[str, Decimal]] = None,
    line_counts_by_account_id: Optional[dict[str, int]] = None,
    line_counts_by_code: Optional[dict[str, int]] = None,
    *,
    search: str = "",
    include_zero: bool = False,
) -> list[dict]:
    balances_by_code = balances_by_code or {}
    line_counts_by_account_id = line_counts_by_account_id or {}
    line_counts_by_code = line_counts_by_code or {}
    needle = str(search or "").strip().lower()
    rows = []
    for account in accounts:
        account_id = str(account.get("id") or "")
        code = str(account.get("code") or "")
        name = str(account.get("name") or "")
        if needle and needle not in f"{code} {name} {account.get('account_type') or ''} {account.get('category') or ''}".lower():
            continue
        has_legacy_code_balance = code in balances_by_code
        balance = (
            balances_by_account_id.get(account_id, Decimal("0.00"))
            + balances_by_code.get(code, Decimal("0.00"))
        )
        if not include_zero and balance == Decimal("0.00"):
            continue
        debit, credit = account_balance_direction(account, balance)
        statement = trial_balance_account_statement(account)
        filing_status = trial_balance_filing_status(account)
        normal_balance = str(account.get("normal_balance") or "").strip().title()
        anomalies = []
        if normal_balance == "Debit" and balance < Decimal("0.00"):
            anomalies.append("opposite_to_normal_balance")
        elif normal_balance == "Credit" and balance > Decimal("0.00"):
            anomalies.append("opposite_to_normal_balance")
        if has_legacy_code_balance:
            anomalies.append("legacy_code_grouping")
        reporting_category_id = account.get("reporting_category_id")
        rows.append({
            "account_id": account.get("id"),
            "code": code,
            "name": name,
            "active": bool(account.get("active", True)),
            "type": account.get("account_type"),
            "category": account.get("category"),
            "module": str(account.get("module") or "CORE"),
            "account_class": account.get("account_class") or account.get("category"),
            "account_subtype": account.get("account_subtype") or account.get("account_type"),
            "statement": statement,
            "normal_balance": normal_balance,
            "control_account_type": account.get("control_account_type") or "None",
            "allow_manual_posting": not bool(account.get("is_control_account") or account.get("control_account")) if account.get("allow_manual_posting") is None else bool(account.get("allow_manual_posting")),
            "system_account": bool(account.get("system_account")),
            "raw_balance": money_str(balance),
            "balance": money_str(balance),
            "debit": money_str(debit),
            "credit": money_str(credit),
            "reporting_category_id": reporting_category_id,
            "reporting_category_name": account.get("internal_reporting_category"),
            "statutory_presentation": account.get("statutory_presentation"),
            "cash_flow_category": account.get("cash_flow_category"),
            "default_tax_treatment": account.get("default_tax_treatment"),
            "vat_behaviour": account.get("vat_behaviour"),
            "cis_role": account.get("cis_role"),
            "requires_dimension": account.get("requires_dimension"),
            "current_noncurrent_rule": account.get("current_noncurrent_rule"),
            "filing_status": filing_status,
            "mapping_status": "mapped" if reporting_category_id else "unmapped",
            "suggested_taxonomy_concept": account.get("suggested_taxonomy_concept"),
            "anomalies": anomalies,
            "journal_line_count": line_counts_by_account_id.get(account_id, 0) + line_counts_by_code.get(code, 0),
        })
    return rows


def trial_balance_summary(
    rows: list[dict],
    *,
    date_mode: str,
    date_from: str,
    date_to: str,
    materiality: Decimal = Decimal("0.00"),
    filters: Optional[dict] = None,
) -> dict:
    debit_total = sum((money(row.get("debit")) for row in rows), Decimal("0.00"))
    credit_total = sum((money(row.get("credit")) for row in rows), Decimal("0.00"))
    difference = debit_total - credit_total
    material_rows = [row for row in rows if abs(money(row.get("raw_balance"))) > materiality]
    blocked = [row for row in material_rows if row.get("filing_status") == "Blocked"]
    review = [row for row in material_rows if row.get("filing_status") == "Review"]
    unmapped = [
        row for row in material_rows
        if row.get("statement") != "Memorandum" and not row.get("reporting_category_id")
    ]
    memorandum = [row for row in rows if row.get("statement") == "Memorandum"]
    abnormal = [row for row in rows if "opposite_to_normal_balance" in (row.get("anomalies") or [])]
    return {
        "debit_total": money_str(debit_total),
        "credit_total": money_str(credit_total),
        "difference": money_str(abs(difference)),
        "balanced": difference == Decimal("0.00"),
        "account_count": len(rows),
        "date_mode": date_mode,
        "date_from": date_from or None,
        "date_to": date_to or None,
        "materiality": money_str(materiality),
        "blocked_account_count": len(blocked),
        "blocked_balance": money_str(sum((abs(money(row.get("raw_balance"))) for row in blocked), Decimal("0.00"))),
        "review_account_count": len(review),
        "unmapped_account_count": len(unmapped),
        "memorandum_account_count": len(memorandum),
        "abnormal_balance_count": len(abnormal),
        "filing_ready": not blocked and not review and not unmapped and difference == Decimal("0.00"),
        "readiness_only": True,
        "filters": filters or {},
    }


async def canonical_trial_balance(
    session: AsyncSession,
    client_id: str,
    *,
    date_from: str = "",
    date_to: str = "",
    date_mode: str = "as_at",
    account_code: str = "",
    location_id: str = "",
    dimension_id: str = "",
    search: str = "",
    include_zero: bool = False,
    materiality: Any = "0.00",
    accounts: Optional[list[dict]] = None,
) -> dict:
    mode = str(date_mode or "as_at").strip().lower()
    if mode not in TRIAL_BALANCE_DATE_MODES:
        raise HTTPException(status_code=400, detail="Trial Balance mode must be movement, as_at, or financial_year.")
    start, end = str(date_from or "").strip(), str(date_to or "").strip()
    joined = accounting_journal_lines.join(
        accounting_journal_entries,
        accounting_journal_lines.c.entry_id == accounting_journal_entries.c.id,
    )
    conditions = [
        accounting_journal_lines.c.client_id == client_id,
        accounting_journal_entries.c.client_id == client_id,
        accounting_journal_entries.c.status == "posted",
    ]
    if mode != "as_at" and start:
        conditions.append(accounting_journal_entries.c.entry_date >= start)
    if end:
        conditions.append(accounting_journal_entries.c.entry_date <= end)
    if account_code:
        conditions.append(accounting_journal_lines.c.account_code == account_code.strip())
    if location_id:
        conditions.append(accounting_journal_lines.c.location_id == location_id.strip())
    if dimension_id:
        conditions.append(accounting_journal_lines.c.dimension_id == dimension_id.strip())
    debit_amount = cast(func.coalesce(accounting_journal_lines.c.debit, "0"), Numeric(20, 2))
    credit_amount = cast(func.coalesce(accounting_journal_lines.c.credit, "0"), Numeric(20, 2))
    grouped = await many(
        session,
        select(
            accounting_journal_lines.c.account_id,
            accounting_journal_lines.c.account_code,
            func.sum(debit_amount - credit_amount).label("balance"),
            func.count(accounting_journal_lines.c.id).label("journal_line_count"),
        )
        .select_from(joined)
        .where(*conditions)
        .group_by(accounting_journal_lines.c.account_id, accounting_journal_lines.c.account_code),
    )
    balances_by_account_id: dict[str, Decimal] = {}
    balances_by_code: dict[str, Decimal] = {}
    counts_by_account_id: dict[str, int] = {}
    counts_by_code: dict[str, int] = {}
    for result in grouped:
        account_id = str(result.get("account_id") or "")
        code = str(result.get("account_code") or "")
        balance = money(result.get("balance"))
        count = int(result.get("journal_line_count") or 0)
        if account_id:
            balances_by_account_id[account_id] = balances_by_account_id.get(account_id, Decimal("0.00")) + balance
            counts_by_account_id[account_id] = counts_by_account_id.get(account_id, 0) + count
        else:
            balances_by_code[code] = balances_by_code.get(code, Decimal("0.00")) + balance
            counts_by_code[code] = counts_by_code.get(code, 0) + count
    if accounts is None:
        accounts = await many(
            session,
            select(accounting_accounts)
            .where(accounting_accounts.c.client_id == client_id)
            .order_by(accounting_accounts.c.code.asc()),
        )
    rows = trial_balance_rows_from_balances(
        accounts,
        balances_by_account_id,
        balances_by_code,
        counts_by_account_id,
        counts_by_code,
        search=search,
        include_zero=include_zero,
    )
    safe_materiality = abs(money(materiality))
    filters = {
        "account_code": account_code or None,
        "location_id": location_id or None,
        "dimension_id": dimension_id or None,
        "search": search or None,
        "include_zero": include_zero,
    }
    return {
        "trial_balance": rows,
        "summary": trial_balance_summary(
            rows,
            date_mode=mode,
            date_from="" if mode == "as_at" else start,
            date_to=end,
            materiality=safe_materiality,
            filters=filters,
        ),
    }


async def account_balances_for_financial_year(session: AsyncSession, client_id: str, year: dict) -> dict[str, Decimal]:
    result = await canonical_trial_balance(
        session,
        client_id,
        date_from=str(year.get("start_date") or ""),
        date_to=str(year.get("end_date") or ""),
        date_mode="financial_year",
    )
    return {
        str(row.get("code") or ""): money(row.get("raw_balance"))
        for row in result["trial_balance"]
    }


async def year_end_trial_balance_result(session: AsyncSession, client_id: str, year: dict, accounts: list[dict]) -> dict:
    return await canonical_trial_balance(
        session,
        client_id,
        date_from=str(year.get("start_date") or ""),
        date_to=str(year.get("end_date") or ""),
        date_mode="financial_year",
        accounts=accounts,
    )


async def year_end_trial_balance(session: AsyncSession, client_id: str, year: dict, accounts: list[dict]) -> list[dict]:
    result = await year_end_trial_balance_result(session, client_id, year, accounts)
    return result["trial_balance"]


def year_end_profit_and_loss(accounts: list[dict], balances: dict[str, Decimal]) -> dict:
    income = Decimal("0.00")
    expense = Decimal("0.00")
    rows = []
    for account in accounts:
        code = str(account.get("code") or "")
        balance = balances.get(code, Decimal("0.00"))
        category = str(account.get("category") or "")
        if category == "Income":
            amount = -balance
            income += amount
        elif category == "Expense":
            amount = balance
            expense += amount
        else:
            continue
        if amount != Decimal("0.00"):
            rows.append({"code": code, "name": account.get("name"), "category": category, "amount": money_str(amount)})
    return {"income": money_str(income), "expenses": money_str(expense), "profit": money_str(income - expense), "rows": rows}


async def build_opening_balance_preview(session: AsyncSession, client_id: str, source_year: dict, target_year: Optional[dict], accounts: list[dict]) -> list[dict]:
    if not target_year:
        return []
    balances = await native_account_balances(session, client_id)
    rows = []
    for account in accounts:
        category = str(account.get("category") or "")
        if category not in {"Asset", "Liability", "Equity"}:
            continue
        balance = balances.get(str(account.get("code") or ""), Decimal("0.00"))
        if balance == Decimal("0.00"):
            continue
        debit, credit = account_balance_direction(account, balance)
        rows.append({
            "account_code": account.get("code"),
            "account_name": account.get("name"),
            "category": category,
            "debit": money_str(debit),
            "credit": money_str(credit),
            "source_financial_year_id": source_year.get("id"),
            "financial_year_id": target_year.get("id"),
            "status": "preview",
        })
    return rows


async def year_end_workspace(session: AsyncSession, client_id: str, accounts: list[dict], periods: list[dict], financial_years: list[dict]) -> dict:
    settings_row = await ensure_year_end_settings(session, client_id)
    today = datetime.now(timezone.utc).date().isoformat()
    ordered_years = sorted(financial_years, key=lambda row: str(row.get("start_date") or ""), reverse=True)
    current_year = next((year for year in ordered_years if str(year.get("start_date") or "") <= today <= str(year.get("end_date") or "")), None) or (ordered_years[0] if ordered_years else None)
    last_closed = next((year for year in ordered_years if str(year.get("status") or "") == "closed"), None)
    period_counts = await accounting_period_transaction_counts(session, client_id)
    period_rows = []
    for period in periods:
        item = serialize_period(period)
        item["transactions_posted"] = period_counts.get(str(period.get("id")), 0)
        period_rows.append(item)
    draft_journals = await many(session, select(accounting_journal_entries).where(accounting_journal_entries.c.client_id == client_id, accounting_journal_entries.c.status == "draft"))
    unreconciled_bank = await count_rows(session, accounting_bank_transactions, accounting_bank_transactions.c.client_id == client_id, accounting_bank_transactions.c.status != "reconciled", accounting_bank_transactions.c.ignored == False)  # noqa: E712
    open_vat_periods = await count_rows(session, accounting_vat_periods, accounting_vat_periods.c.client_id == client_id, accounting_vat_periods.c.status == "open")
    trial_balance_result = await year_end_trial_balance_result(session, client_id, current_year, accounts) if current_year else {"trial_balance": [], "summary": {}}
    trial_balance = trial_balance_result["trial_balance"]
    balances = await account_balances_for_financial_year(session, client_id, current_year) if current_year else {}
    profit_loss = year_end_profit_and_loss(accounts, balances)
    next_year = None
    if current_year:
        next_year = next((year for year in financial_years if str(year.get("start_date") or "") > str(current_year.get("end_date") or "")), None)
    opening_preview = await build_opening_balance_preview(session, client_id, current_year, next_year, accounts) if current_year else []
    opening_rows = await many(session, select(accounting_opening_balances).where(accounting_opening_balances.c.client_id == client_id).order_by(accounting_opening_balances.c.created_at.desc()))
    events = await many(session, select(accounting_year_end_events).where(accounting_year_end_events.c.client_id == client_id).order_by(accounting_year_end_events.c.created_at.desc()).limit(100))
    closing_journals = await many(
        session,
        select(accounting_journal_entries).where(
            accounting_journal_entries.c.client_id == client_id,
            accounting_journal_entries.c.source_type.in_(["year_end_close", "year_end_adjustment", "opening_balance"]),
        ).order_by(accounting_journal_entries.c.entry_date.desc(), accounting_journal_entries.c.created_at.desc()),
    )
    validation_errors = []
    warnings = []
    if draft_journals:
        validation_errors.append(f"{len(draft_journals)} draft journal(s) must be posted or voided before year end close.")
    if unreconciled_bank:
        validation_errors.append(f"{unreconciled_bank} bank transaction(s) are still unreconciled.")
    if open_vat_periods:
        warnings.append(f"{open_vat_periods} VAT period(s) are still open. This is a warning, not a blocker.")
    blocked_accounts = int(trial_balance_result["summary"].get("blocked_account_count") or 0)
    unmapped_accounts = int(trial_balance_result["summary"].get("unmapped_account_count") or 0)
    if blocked_accounts:
        warnings.append(f"{blocked_accounts} Trial Balance account(s) have a material Blocked balance and must be resolved before accounts production.")
    if unmapped_accounts:
        warnings.append(f"{unmapped_accounts} material Trial Balance account(s) do not yet have an internal reporting category.")
    outstanding_tasks = len(validation_errors) + len(warnings)
    return {
        "settings": serialize_year_end_settings(settings_row),
        "dashboard": {
            "current_financial_year": current_year.get("name") if current_year else "-",
            "open_periods": len([p for p in period_rows if p.get("status") == "open"]),
            "locked_periods": len([p for p in period_rows if p.get("status") == "locked"]),
            "closed_years": len([y for y in financial_years if y.get("status") == "closed"]),
            "outstanding_tasks": outstanding_tasks,
            "last_year_closed": last_closed.get("name") if last_closed else "-",
        },
        "current_year": serialize_financial_year(current_year) if current_year else None,
        "next_year": serialize_financial_year(next_year) if next_year else None,
        "financial_years": [serialize_financial_year(y) for y in financial_years],
        "periods": period_rows,
        "checklist": {
            "errors": validation_errors,
            "warnings": warnings,
            "items": [
                {"label": "No draft transactions remain", "complete": not draft_journals, "count": len(draft_journals)},
                {"label": "Bank reconciliations complete", "complete": unreconciled_bank == 0, "count": unreconciled_bank},
                {"label": "VAT periods reviewed", "complete": open_vat_periods == 0, "count": open_vat_periods, "warning_only": True},
                {"label": "Trial Balance reviewed", "complete": bool(trial_balance) or not current_year},
                {"label": "Profit and Loss reviewed", "complete": True},
            ],
        },
        "trial_balance": trial_balance,
        "trial_balance_summary": trial_balance_result["summary"],
        "profit_and_loss": profit_loss,
        "opening_balance_preview": opening_preview,
        "opening_balances": [serialize_opening_balance(row) for row in opening_rows],
        "closing_journals": closing_journals,
        "retained_earnings": {
            "account_code": settings_row.get("retained_earnings_account") or "3200",
            "current_year_profit": profit_loss.get("profit"),
            "automatic_transfer": True,
        },
        "lock_history": [serialize_year_end_event(e) for e in events],
        "reports": {
            "year_end_checklist": [
                {"item": row["label"], "status": "Complete" if row.get("complete") else "Open", "count": row.get("count", 0)}
                for row in [
                    {"label": "Draft transactions", "complete": not draft_journals, "count": len(draft_journals)},
                    {"label": "Unreconciled bank transactions", "complete": unreconciled_bank == 0, "count": unreconciled_bank},
                    {"label": "Open VAT periods", "complete": open_vat_periods == 0, "count": open_vat_periods},
                ]
            ],
            "closing_journal_report": closing_journals,
            "opening_balance_report": opening_preview,
            "period_lock_report": [serialize_year_end_event(e) for e in events if "period" in str(e.get("event_type") or "")],
            "financial_year_summary": [serialize_financial_year(y) for y in financial_years],
        },
        "ai_alerts": [
            {"module": "Year End", "type": "Validation", "detail": item, "target_tab": "Financial Year Close"}
            for item in validation_errors + warnings
        ],
    }


def annual_accounts_statement_rows(
    statement: dict,
    section_order: list[tuple[str, str]],
    comparative_statement: Optional[dict] = None,
) -> list[dict]:
    comparative_statement = comparative_statement or {}
    rows = []
    for key, label in section_order:
        value = statement.get(key)
        if value is not None:
            rows.append({"key": key, "label": label, "amount": value, "comparative": comparative_statement.get(key)})
    return rows


def annual_accounts_preview_from_trial_balance(
    current_rows: list[dict],
    comparative_rows: Optional[list[dict]] = None,
) -> dict:
    comparative_rows = comparative_rows or []

    def aggregate(rows: list[dict]) -> tuple[dict[str, Decimal], dict[str, Decimal]]:
        pnl: dict[str, Decimal] = {}
        balance_sheet: dict[str, Decimal] = {}
        for row in rows:
            if str(row.get("statement") or "") == "memorandum":
                continue
            label = str(
                row.get("statutory_presentation")
                or row.get("reporting_category_name")
                or row.get("name")
                or "Unmapped"
            ).strip()
            raw = money(row.get("raw_balance"))
            account_class = str(row.get("account_class") or row.get("category") or "").strip().lower()
            statement = str(row.get("statement") or "").strip().lower()
            if statement == "profit_and_loss":
                amount = -raw if account_class in {"income", "other income"} else raw
                pnl[label] = pnl.get(label, Decimal("0.00")) + amount
            elif statement == "balance_sheet":
                amount = raw if account_class == "asset" else -raw
                balance_sheet[label] = balance_sheet.get(label, Decimal("0.00")) + amount
        return pnl, balance_sheet

    current_pnl, current_bs = aggregate(current_rows)
    comparative_pnl, comparative_bs = aggregate(comparative_rows)

    def rows(current: dict[str, Decimal], comparative: dict[str, Decimal]) -> list[dict]:
        labels = list(current)
        labels.extend(label for label in comparative if label not in current)
        return [
            {
                "key": hashlib.sha1(label.encode("utf-8")).hexdigest()[:12],
                "label": label,
                "amount": money_str(current.get(label, Decimal("0.00"))),
                "comparative": money_str(comparative.get(label, Decimal("0.00"))),
            }
            for label in labels
        ]

    return {
        "profit_and_loss_rows": rows(current_pnl, comparative_pnl),
        "balance_sheet_rows": rows(current_bs, comparative_bs),
    }


def annual_accounts_json(value: Any, fallback: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    try:
        return json.loads(value) if value else fallback
    except (TypeError, ValueError, json.JSONDecodeError):
        return fallback


