def annual_accounts_configuration_issues(
    accounts_standard: str,
    accounts_format: str,
    company_trading_status: str,
) -> list[str]:
    issues = []
    if accounts_standard not in ANNUAL_ACCOUNTS_STANDARD_FORMATS:
        issues.append("Choose a supported accounting standard.")
    if accounts_format not in {"micro", "small_full", "full", "dormant"}:
        issues.append("Choose a supported accounts format.")
    if company_trading_status not in ANNUAL_ACCOUNTS_TRADING_STATUSES:
        issues.append("Choose a supported company trading status.")
    if issues:
        return issues
    if company_trading_status == "dormant":
        if accounts_format != "dormant":
            issues.append("A dormant company must use the dormant accounts format.")
        if accounts_standard not in ANNUAL_ACCOUNTS_DORMANT_STANDARDS:
            issues.append("The supported dormant-accounts workflow uses a UK GAAP standard, not UK-adopted IFRS.")
        return issues
    if accounts_format == "dormant":
        issues.append("The dormant accounts format can only be used when the company trading status is dormant.")
        return issues
    allowed_formats = ANNUAL_ACCOUNTS_STANDARD_FORMATS[accounts_standard]
    if accounts_format not in allowed_formats:
        readable_standard = {
            "FRS_105": "FRS 105",
            "FRS_102_1A": "FRS 102 Section 1A",
            "FRS_102": "FRS 102",
            "IFRS": "UK-adopted IFRS",
        }[accounts_standard]
        readable_formats = ", ".join(sorted(allowed_formats))
        issues.append(f"{readable_standard} is not compatible with the selected accounts format; use {readable_formats}.")
    return issues


