def serialize_annual_accounts_pack(row: dict) -> dict:
    item = dict(row)
    item["details"] = annual_accounts_json(item.pop("details_json", None), {})
    item["contents"] = annual_accounts_json(item.pop("contents_json", None), {})
    return item


def annual_accounts_pack_validation(
    pack: dict,
    client: dict,
    trial_balance_summary: dict,
    statement_metrics: Optional[dict] = None,
) -> list[dict]:
    issues = []
    statement_metrics = statement_metrics or {}
    details = pack.get("details") if isinstance(pack.get("details"), dict) else annual_accounts_json(pack.get("details_json"), {})
    def issue(code: str, message: str, severity: str = "blocker"):
        issues.append({"code": code, "message": message, "severity": severity})

    is_company = native_year_end_filing_profile(client.get("client_type")).get("workflow") == "corporation_tax"
    if is_company and not str(client.get("company_number") or "").strip():
        issue("company_number_missing", "Companies House company number is required.")
    if not pack.get("period_from") or not pack.get("period_to"):
        issue("period_missing", "The statutory accounts period is required.")
    if is_company and not pack.get("accounts_standard"):
        issue("accounts_standard_missing", "Select the accounting standard.")
    if is_company and not pack.get("accounts_format"):
        issue("accounts_format_missing", "Select the accounts format and eligibility basis.")
    for configuration_issue in (annual_accounts_configuration_issues(
        str(pack.get("accounts_standard") or ""),
        str(pack.get("accounts_format") or ""),
        str(pack.get("company_trading_status") or "trading"),
    ) if is_company else []):
        issue("accounts_configuration_conflict", configuration_issue)
    if is_company and pack.get("accounts_format") in {"micro", "small_full"}:
        if details.get("employee_count") in {None, ""}:
            issue("employee_count_missing", "Average employee count is required to confirm the selected size regime.", "review")
        turnover = abs(money(statement_metrics.get("turnover")))
        balance_total = abs(money(statement_metrics.get("balance_sheet_total")))
        employee_count = int(details.get("employee_count") or 0)
        modern_thresholds = str(pack.get("period_from") or "") >= "2025-04-06"
        if pack.get("accounts_format") == "micro":
            limits = (Decimal("1000000"), Decimal("500000"), 10) if modern_thresholds else (Decimal("632000"), Decimal("316000"), 10)
        else:
            limits = (Decimal("15000000"), Decimal("7500000"), 50) if modern_thresholds else (Decimal("10200000"), Decimal("5100000"), 50)
        qualifying = sum([turnover <= limits[0], balance_total <= limits[1], employee_count <= limits[2]])
        if qualifying < 2:
            issue("accounts_format_ineligible", "The recorded turnover, balance-sheet total and employee count do not support the selected accounts regime.")
    if is_company and not pack.get("audit_exemption"):
        issue("audit_basis_missing", "Record the audit exemption or auditor-report basis before approval.", "review")
    elif pack.get("audit_exemption") not in ANNUAL_ACCOUNTS_AUDIT_BASES:
        issue("audit_basis_invalid", "Select a supported audit exemption or auditor-report basis.", "review")
    if not trial_balance_summary.get("balanced"):
        issue("trial_balance_unbalanced", "The canonical Trial Balance does not balance.")
    if int(trial_balance_summary.get("account_count") or 0) == 0 and pack.get("accounts_format") != "dormant":
        issue("trial_balance_empty", "The selected accounts period has no non-zero Trial Balance rows.")
    if int(trial_balance_summary.get("blocked_account_count") or 0):
        issue("blocked_nominals", "Material balances remain on filing-blocked nominal accounts.")
    if int(trial_balance_summary.get("review_account_count") or 0):
        issue("review_nominals", "Material balances remain on nominal accounts requiring review.")
    if int(trial_balance_summary.get("unmapped_account_count") or 0):
        issue("unmapped_nominals", "Material balances remain without a stable reporting-category mapping.")
    if is_company and not pack.get("director_signing_name"):
        issue("director_missing", "Select the director who will approve and sign the balance sheet.", "review")
    elif pack.get("director_signing_name") not in {row["name"] for row in annual_accounts_directors(client)}:
        issue("director_invalid", "The signing director must be selected from the directors recorded on the client account.", "review")
    if not pack.get("board_approval_date"):
        issue("approval_date_missing", "Enter the board approval date before final approval.", "review")
    elif str(pack.get("board_approval_date")) < str(pack.get("period_to") or ""):
        issue("approval_date_invalid", "The board approval date cannot be before the end of the accounts period.", "review")
    return issues


