def supplementary_sa_field_type(label: str) -> str:
    text_value = label.lower()
    if "put 'x'" in text_value or 'put "x"' in text_value or "put �x�" in text_value or ("put " in text_value and " in the box" in text_value):
        return "boolean"
    if "dd mm yyyy" in text_value or "date of" in text_value or "enter the date" in text_value:
        return "date"
    if any(term in text_value for term in ("amount", "income", "profit", "loss", "expenses", "tax paid", "tax taken", "relief claimed", "deductions", "allowance")):
        return "money"
    if text_value.startswith("number of") or "how many" in text_value:
        return "number"
    if "information in this space" in text_value or "give details" in text_value:
        return "textarea"
    return "text"


def supplementary_sa_form_schema(code: str, asset_name: str, saved: dict) -> list[dict]:
    cached = SA_SUPPLEMENTARY_SCHEMA_CACHE.get(asset_name)
    if cached is not None:
        return [
            {**field, "value": saved.get(field["key"], False if field["type"] == "boolean" else "")}
            for field in cached
        ]
    asset_path = ROOT_DIR / "assets" / asset_name
    if not asset_path.exists():
        return []
    text_value = "\n".join((page.extract_text() or "") for page in PdfReader(str(asset_path)).pages)
    text_value = re.sub(r"(?mi)^Boxes?\s+\d+(?:\s+to\s+\d+)?\s+(?:is|are)\s+not in use.*$", "", text_value)
    pattern = re.compile(
        r"(?ms)^(?P<box>\d+(?:\.\d+|[A-Z])?)\s+(?P<label>.*?)(?=^\d+(?:\.\d+|[A-Z])?\s+|^Boxes?\s+\d+.*?not in use|^SA\d+\s+2026\s+Page|\Z)"
    )
    fields = []
    seen = set()
    for match in pattern.finditer(text_value):
        box = match.group("box")
        if box in seen:
            continue
        label = re.sub(r"\s+", " ", match.group("label")).strip(" �\t\r\n")
        if not label:
            continue
        # Remove page headers which PDF text extraction can place after the final box.
        label = re.split(r"\bYour name\b|\bFor help filling in this form\b", label, maxsplit=1)[0].strip()
        if not label:
            continue
        seen.add(box)
        key = f"{code.lower()}_box_{box.replace('.', '_')}"
        field_type = supplementary_sa_field_type(label)
        rules = {"placeholder": "Enter the value required by this HMRC box"}
        if field_type == "money":
            rules = {"max_digits": 9, "decimal_places": 0, "placeholder": "Whole pounds only — up to 9 digits"}
        elif field_type == "date":
            rules = {"max_length": 10, "placeholder": "DD/MM/YYYY — 8 digits"}
        elif field_type == "number":
            rules = {"max_digits": 4, "placeholder": "Numbers only"}
        elif field_type in {"text", "textarea"}:
            rules = {"max_length": 255 if field_type == "text" else 4000, "placeholder": "Use the format requested in the HMRC box"}
        fields.append({
            "key": key,
            "box": box,
            "label": label,
            "type": field_type,
            "automatic": False,
            **rules,
        })
    SA_SUPPLEMENTARY_SCHEMA_CACHE[asset_name] = fields
    return [
        {**field, "value": saved.get(field["key"], False if field["type"] == "boolean" else "")}
        for field in fields
    ]


def sole_trader_self_assessment_form(client: dict, pack: Optional[dict], snapshot: dict) -> dict:
    pnl = snapshot.get("profit_and_loss") or {}
    details = (pack or {}).get("details") or {}
    saved = details.get("self_assessment_fields") if isinstance(details.get("self_assessment_fields"), dict) else {}
    turnover = abs(money(pnl.get("turnover")))
    expenses = abs(money(pnl.get("cost_of_sales"))) + abs(money(pnl.get("operating_expenses")))
    auto = {
        "utr": client.get("utr") or "",
        "full_name": client.get("business_name") or f"{client.get('first_name') or ''} {client.get('last_name') or ''}".strip(),
        "phone": client.get("phone") or "",
        "self_employment": True,
        "tax_calculation_summary": True,
        "self_employment_schedule": "SA103S" if turnover <= Decimal("90000") else "SA103F",
        "business_name": client.get("business_name") or "",
        "accounting_period_from": (pack or {}).get("period_from") or "",
        "accounting_period_to": (pack or {}).get("period_to") or "",
        "turnover": money_str(turnover),
        "allowable_expenses": money_str(expenses),
        "net_profit": money_str(turnover - expenses),
    }
    values = {**auto, **saved}
    supplementary_forms = [
        {
            "selection_key": selection_key,
            "code": code,
            "title": title,
            "selected": bool(values.get(selection_key)),
            "fields": supplementary_sa_form_schema(code, asset_name, saved),
        }
        for selection_key, code, title, asset_name in SA_SUPPLEMENTARY_FORM_ASSETS
    ]
    return {
        "form": "SA100 2026",
        "tax_year": "6 April 2025 to 5 April 2026",
        "supplementary_form": "SA103S/SA103F - eligibility review required",
        "sections": [
            {"id": section["id"], "title": section["title"], "fields": [
                {
                    "key": key,
                    "label": label,
                    "type": field_type,
                    "automatic": automatic,
                    "value": values.get(key, ""),
                    **SA100_FIELD_RULES.get(key, {}),
                    **({"max_digits": 9, "decimal_places": 0, "placeholder": "Whole pounds only — up to 9 digits"} if field_type == "money" else {}),
                    **({"placeholder": "DD/MM/YYYY — 8 digits"} if field_type == "date" else {}),
                    **({"options": [
                        {"value": "SA103S", "label": "SA103S — Self-employment (short)"},
                        {"value": "SA103F", "label": "SA103F — Self-employment (full)"},
                    ]} if key == "self_employment_schedule" else {}),
                }
                for key, label, field_type, automatic in section["fields"]
            ]}
            for section in SA100_SOLE_TRADER_SECTIONS
        ],
        "auto_values": auto,
        "supplementary_forms": supplementary_forms,
    }


def system_pdf_form_package(form_code: str) -> Optional[dict]:
    safe_code = re.sub(r"[^A-Za-z0-9.-]", "", str(form_code or "")).upper()
    if not safe_code:
        return None
    manifests = sorted(SYSTEM_FORM_DIR.glob("*.field-map.json"))
    for manifest_path in manifests:
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if str(manifest.get("form_code") or "").upper() != safe_code:
            continue
        pdf_name = str(manifest.get("pdf_filename") or manifest_path.name.replace(".field-map.json", ".pdf"))
        pdf_path = manifest_path.parent / Path(pdf_name).name
        if not pdf_path.exists():
            return {**manifest, "available": False, "error": "Prepared PDF is missing."}
        return {
            **manifest,
            "available": True,
            "_pdf_path": pdf_path,
            "_manifest_path": manifest_path,
        }
    return None


def self_assessment_system_form_values(form: dict) -> dict[str, Any]:
    values = {
        str(field.get("key")): field.get("value")
        for section in (form.get("sections") or [])
        for field in (section.get("fields") or [])
        if field.get("key")
    }
    for supplementary in form.get("supplementary_forms") or []:
        for field in supplementary.get("fields") or []:
            if field.get("key"):
                values[str(field["key"])] = field.get("value")
    return values


def self_assessment_system_form_status(form: Optional[dict]) -> list[dict]:
    if not form:
        return []
    codes = ["SA100-2026"]
    schedule = next((
        field.get("value")
        for section in (form.get("sections") or [])
        for field in (section.get("fields") or [])
        if field.get("key") == "self_employment_schedule"
    ), None)
    if schedule:
        codes.append(f"{schedule}-2026")
    codes.extend(
        f"{supplementary.get('code')}-2026"
        for supplementary in (form.get("supplementary_forms") or [])
        if supplementary.get("selected")
    )
    return [
        {
            "form_code": code,
            "available": bool((package := system_pdf_form_package(code)) and package.get("available")),
            "field_count": len((package or {}).get("fields") or []),
            "status": "System-fillable" if package and package.get("available") else "Needs PDF Editor preparation",
        }
        for code in dict.fromkeys(codes)
    ]


def fill_system_pdf_package(package: dict, values_by_key: dict[str, Any], read_only: bool = True) -> bytes:
    reader = PdfReader(str(package["_pdf_path"]))
    writer = PdfWriter()
    writer.clone_document_from_reader(reader)
    fields = writer.get_fields() or {}
    manifest_fields = package.get("fields") or []
    expected_names = {str(field.get("pdf_field_name") or "") for field in manifest_fields}
    missing = sorted(name for name in expected_names if name and name not in fields)
    if missing:
        raise ValueError(f"Prepared PDF fields are missing: {', '.join(missing[:20])}")
    pdf_values: dict[str, Any] = {}
    for field in manifest_fields:
        pdf_name = str(field.get("pdf_field_name") or "")
        system_key = str(field.get("system_key") or "")
        value = values_by_key.get(system_key)
        if field.get("type") == "boolean":
            pdf_values[pdf_name] = "/Yes" if bool(value) else "/Off"
        else:
            pdf_values[pdf_name] = "" if value is None else str(value)
    for page in writer.pages:
        for annotation_ref in page.get("/Annots", []) or []:
            annotation = annotation_ref.get_object()
            if annotation.get("/Subtype") != "/Widget":
                continue
            parent = annotation.get("/Parent")
            parent_object = parent.get_object() if parent else None
            field_name = str(annotation.get("/T") or (parent_object.get("/T") if parent_object else "") or "")
            if field_name not in expected_names:
                continue
            if read_only:
                target = parent_object or annotation
                target[NameObject("/Ff")] = NumberObject(int(target.get("/Ff") or 0) | 1)
    writer.update_page_form_field_values(None, pdf_values, auto_regenerate=False)
    output = io.BytesIO()
    writer.write(output)
    written = PdfReader(io.BytesIO(output.getvalue()))
    written_fields = written.get_fields() or {}
    stale = [
        name for name, expected in pdf_values.items()
        if str((written_fields.get(name) or {}).get("/V") or "") != str(expected)
    ]
    if stale:
        raise ValueError(f"Prepared PDF values did not persist: {', '.join(stale[:20])}")
    return output.getvalue()


async def year_end_accounts_workspace(session: AsyncSession, client: dict, current_user: Optional[dict] = None, selected_pack_id: Optional[str] = None) -> dict:
    compliance_status = year_end_specification_status()
    filing_profile = native_year_end_filing_profile(client.get("client_type"))
    is_company_workflow = filing_profile.get("workflow") == "corporation_tax"
    is_sole_trader_workflow = str(client.get("client_type") or "").lower().replace(" ", "_") in {"sole_trader", "cis_customer"}
    client_id = str(client.get("id") or "")
    years = await many(
        session,
        select(accounting_financial_years)
        .where(accounting_financial_years.c.client_id == client_id)
        .order_by(accounting_financial_years.c.end_date.desc()),
    )
    year = years[0] if years else None
    start = str(year.get("start_date") or "") if year else ""
    end = str(year.get("end_date") or "") if year else ""
    snapshot = await financial_report_snapshot(session, client_id, start, end) if year else {
        "profit_and_loss": {},
        "balance_sheet": {},
        "trial_balance": [],
        "trial_balance_summary": {},
    }
    tb_summary = snapshot.get("trial_balance_summary") or {}
    packs = await many(
        session,
        select(accounting_annual_accounts_packs)
        .where(accounting_annual_accounts_packs.c.client_id == client_id)
        .order_by(accounting_annual_accounts_packs.c.updated_at.desc()),
    )
    selected_pack = next((row for row in packs if str(row.get("id")) == str(selected_pack_id)), None) if selected_pack_id else None
    active_pack = serialize_annual_accounts_pack(selected_pack or packs[0]) if packs else None
    if active_pack:
        start = str(active_pack.get("period_from") or start)
        end = str(active_pack.get("period_to") or end)
        snapshot = await financial_report_snapshot(session, client_id, start, end)
        tb_summary = snapshot.get("trial_balance_summary") or {}
    posted_coverage = await one(
        session,
        select(
            func.count(accounting_journal_entries.c.id).label("total_posted"),
            func.min(accounting_journal_entries.c.entry_date).label("first_posted_date"),
            func.max(accounting_journal_entries.c.entry_date).label("last_posted_date"),
        ).where(
            accounting_journal_entries.c.client_id == client_id,
            accounting_journal_entries.c.status == "posted",
        ),
    ) or {}
    posted_in_period = 0
    if start and end:
        period_coverage = await one(
            session,
            select(func.count(accounting_journal_entries.c.id).label("posted_in_period")).where(
                accounting_journal_entries.c.client_id == client_id,
                accounting_journal_entries.c.status == "posted",
                accounting_journal_entries.c.entry_date >= start,
                accounting_journal_entries.c.entry_date <= end,
            ),
        ) or {}
        posted_in_period = int(period_coverage.get("posted_in_period") or 0)
    filings = await many(
        session,
        select(accounting_annual_accounts_filings)
        .where(accounting_annual_accounts_filings.c.client_id == client_id)
        .order_by(accounting_annual_accounts_filings.c.created_at.desc()),
    )
    outputs = await many(
        session,
        select(accounting_annual_accounts_outputs)
        .where(accounting_annual_accounts_outputs.c.client_id == client_id)
        .order_by(accounting_annual_accounts_outputs.c.created_at.desc()),
    )
    profile = await one(session, select(accounting_agent_filing_profiles).where(accounting_agent_filing_profiles.c.scope == "practice")) or {}

    blockers = []
    def block(code: str, message: str, destination: str = "both"):
        blockers.append({"code": code, "message": message, "severity": "blocker", "destination": destination})

    if not year and not active_pack:
        block("period_missing", "Create a financial year or enter an accounts period before preparing statutory accounts.")
    if is_company_workflow and not str(client.get("company_number") or "").strip():
        block("company_number_missing", "Companies House company number is required.")
    if not str(client.get("utr") or "").strip():
        block("utr_missing", "A 10-digit UTR is required for the HMRC return.", "hmrc")
    if not bool(tb_summary.get("balanced")):
        block("trial_balance_unbalanced", "The canonical Trial Balance must balance before accounts production.")
    if int(tb_summary.get("blocked_account_count") or 0):
        block("blocked_nominals", "Resolve all material Chart of Accounts balances marked Blocked.")
    if int(tb_summary.get("review_account_count") or 0):
        block("review_nominals", "Approve or resolve all material Chart of Accounts balances marked Review.")
    if int(tb_summary.get("unmapped_account_count") or 0):
        block("unmapped_nominals", "Map all material nominal balances to stable internal reporting categories.")
    if not active_pack:
        block("accounts_pack_missing", "Create a Year End Accounts pack for the required financial year.")
    else:
        if int(posted_coverage.get("total_posted") or 0) and not posted_in_period:
            block(
                "no_postings_in_accounts_period",
                f"No posted journals fall inside {start} to {end}. Posted data currently runs from "
                f"{posted_coverage.get('first_posted_date')} to {posted_coverage.get('last_posted_date')}. "
                "Correct the accounts period before refreshing the snapshot.",
            )
        for row in annual_accounts_pack_validation(active_pack, client, tb_summary, {
            "turnover": snapshot.get("profit_and_loss", {}).get("turnover"),
            "balance_sheet_total": snapshot.get("balance_sheet", {}).get("assets"),
        }):
            if row["code"] not in {item["code"] for item in blockers}:
                blockers.append({**row, "destination": "both"})
    taxonomy_selection = annual_accounts_taxonomy_selection(active_pack) if active_pack else {
        "accounts": {"selected_id": None, "hmrc_accepted": False, "period_valid": False},
        "computations": {"selected_id": None, "hmrc_accepted": False, "period_valid": False},
        "ready": False,
    }
    if is_company_workflow and not taxonomy_selection["ready"]:
        accounts_label = taxonomy_selection["accounts"].get("label") or "not selected"
        computations_label = taxonomy_selection["computations"].get("label") or "not selected"
        block(
            "taxonomy_package_missing",
            "Complete the taxonomy selection for this accounting period. "
            f"Accounts: {accounts_label}; computations: {computations_label}. "
            "Save both selections in Settings.",
        )
    block("document_validation_pending", "Generate and pass the applicable HMRC schema, calculation and destination validation.")
    if not profile.get("hmrc_connection_status") == "connected":
        block("hmrc_credentials", "Connect and test the HMRC Corporation Tax filing credentials.", "hmrc")
    if is_company_workflow and not profile.get("companies_house_connection_status") == "connected":
        block("companies_house_credentials", "Connect and test the Companies House presenter account.", "companies_house")

    hmrc_blockers = [row for row in blockers if row["destination"] in {"both", "hmrc"}]
    ch_blockers = [row for row in blockers if row["destination"] in {"both", "companies_house"}] if is_company_workflow else []
    trial_ready = bool(start and end) and bool(tb_summary.get("filing_ready")) and (
        posted_in_period > 0 or (active_pack and active_pack.get("accounts_format") == "dormant")
    )
    production_generation_allowed = filing_generation_allowed()
    ct600_workflow_enabled = is_company_workflow
    hmrc_ready = (ct600_workflow_enabled or is_sole_trader_workflow) and not hmrc_blockers and production_generation_allowed
    ch_ready = is_company_workflow and not ch_blockers and production_generation_allowed
    stored_contents = active_pack.get("contents") if active_pack else {}
    pnl = (stored_contents or {}).get("profit_and_loss") or snapshot.get("profit_and_loss") or {}
    balance_sheet = (stored_contents or {}).get("balance_sheet") or snapshot.get("balance_sheet") or {}
    comparative_pnl = (stored_contents or {}).get("comparative_profit_and_loss") or {}
    comparative_balance_sheet = (stored_contents or {}).get("comparative_balance_sheet") or {}
    preview_validation = [
        row for row in blockers
        if row["code"] in {"trial_balance_unbalanced", "blocked_nominals", "review_nominals", "unmapped_nominals"}
    ]
    ct600_sections = [
        {"section": "Company information and return period", "boxes": "1-90", "status": "Review"},
        {"section": "Supplementary pages", "boxes": "95-144 and 96", "status": "Rule selection required"},
        {"section": "Income, gains, deductions and reliefs", "boxes": "145-325", "status": "Computation required"},
        {"section": "Tax calculation and reconciliation", "boxes": "326-615", "status": "Computation required"},
        {"section": "Indicators, allowances and losses", "boxes": "616-855", "status": "Review"},
        {"section": "Repayments, bank details and declaration", "boxes": "856-985", "status": "Approval required"},
    ]
    self_assessment_form = sole_trader_self_assessment_form(client, active_pack, snapshot) if is_sole_trader_workflow else None
    pack_details = (active_pack or {}).get("details") or {}
    saved_ct600_fields = pack_details.get("ct600_fields") if isinstance(pack_details.get("ct600_fields"), dict) else {}
    ct600_auto_values = annual_accounts_ct600_auto_values(client, active_pack or {
        "period_from": start,
        "period_to": end,
    }, pnl)
    ct600_field_values = {**ct600_auto_values, **saved_ct600_fields}
    ct600_field_definitions = {
        box: {"label": label, "type": field_type}
        for section in CT600_FORM_SECTIONS
        for box, label, field_type in section["fields"]
    }
    ct600_form = {
        "id": "ct600",
        "label": "CT600 - Company Tax Return",
        "version": "CT600 (2026) Version 3",
        "sections": [
            {
                "id": f"official_page_{page_number}",
                "title": f"CT600 (2026) Version 3 - Page {page_number} of 12",
                "fields": [
                    {
                        "box": box,
                        "label": ct600_field_definitions.get(box, {}).get("label") or f"Official CT600 box {box}",
                        "type": ct600_field_definitions.get(box, {}).get("type") or "money",
                        "constraint": ct600_field_constraint(
                            box,
                            ct600_field_definitions.get(box, {}).get("type") or "money",
                        ),
                        "value": ct600_field_values.get(
                            box,
                            False if ct600_field_definitions.get(box, {}).get("type") == "boolean" else "",
                        ),
                        "source": "saved" if box in saved_ct600_fields else ("accounts" if box in ct600_auto_values else "manual"),
                    }
                    for box in page_boxes
                ],
            }
            for page_number, page_boxes in enumerate(CT600_OFFICIAL_PRINT_PAGES, start=1)
        ],
    }
    ct600_fields_by_box = {
        str(field["box"]): field
        for section in ct600_form["sections"]
        for field in section["fields"]
    }
    ct600_editor_sections = [
        {
            "id": section_id,
            "number": section_number,
            "title": title,
            "fields": [
                ct600_fields_by_box[box]
                for box in CT600_LIMITED_COMPANY_VISIBLE_BOXES
                if box in boxes and box in ct600_fields_by_box
            ],
        }
        for section_number, (section_id, title, boxes) in enumerate(CT600_EDITOR_SECTION_GROUPS, start=1)
    ]
    saved_ch_sections = pack_details.get("companies_house_sections") if isinstance(pack_details.get("companies_house_sections"), dict) else {}
    companies_house_section_options = [
        {"id": key, "label": label, "enabled": bool(saved_ch_sections.get(key, default)), "required": bool(default)}
        for key, label, default in COMPANIES_HOUSE_SECTION_OPTIONS
    ]
    saved_custom_sections = pack_details.get("companies_house_custom_sections")
    companies_house_custom_sections = [
        {
            "id": str(row.get("id") or ""),
            "title": str(row.get("title") or ""),
            "content": str(row.get("content") or ""),
            "enabled": bool(row.get("enabled", True)),
            "custom": True,
        }
        for row in (saved_custom_sections if isinstance(saved_custom_sections, list) else [])
        if isinstance(row, dict) and row.get("id") and row.get("title")
    ]
    hmrc_form_preview = {
        "title": "Company Tax Return",
        "form": "CT600 (2026) Version 3",
        "notice": "Draft submission preview - values requiring the Corporation Tax computation remain marked for review.",
        "sections": [
            {
                "title": "Company information",
                "rows": [
                    {"box": "1", "label": "Company name", "value": client.get("business_name") or ""},
                    {"box": "2", "label": "Company registration number", "value": client.get("company_number") or ""},
                    {"box": "3", "label": "Tax reference", "value": client.get("utr") or ""},
                    {"box": "30", "label": "Return period from", "value": start},
                    {"box": "35", "label": "Return period to", "value": end},
                ],
            },
            {
                "title": "Accounts and computations",
                "rows": [
                    {"box": "80", "label": "Accounts and computations attached for this period", "value": "Yes"},
                    {"box": "145", "label": "Total turnover from trade", "value": money_str(money(pnl.get("turnover")))},
                    {"box": "155", "label": "Trading profits", "value": money_str(money(pnl.get("profit_before_tax"))), "status": "Review against tax computation"},
                    {"box": "315", "label": "Profits chargeable to Corporation Tax", "value": "", "status": "Tax computation required"},
                    {"box": "600", "label": "Corporation Tax payable", "value": money_str(money(pnl.get("tax_on_profit"))), "status": "Review against tax computation"},
                ],
            },
            {
                "title": "Declaration",
                "rows": [
                    {"box": "975", "label": "Name of person making the return", "value": active_pack.get("director_signing_name") if active_pack else ""},
                    {"box": "980", "label": "Capacity", "value": "Director" if active_pack and active_pack.get("director_signing_name") else ""},
                    {"box": "985", "label": "Declaration date", "value": active_pack.get("board_approval_date") if active_pack else ""},
                ],
            },
        ],
    }
    comparative_end = str((active_pack or {}).get("comparative_period_to") or "")
    companies_house_preview = {
        "title": client.get("business_name") or "",
        "company_number": client.get("company_number") or "",
        "jurisdiction": "England and Wales",
        "period_from": start,
        "period_to": end,
        "current_year": end[:4] if end else "",
        "comparative_year": comparative_end[:4] if comparative_end else "",
        "period_label": f"Annual accounts for the year ended {end}" if end else "Annual accounts",
        "accounts_standard": active_pack.get("accounts_standard") if active_pack else None,
        "accounts_format": active_pack.get("accounts_format") if active_pack else None,
        "directors": [row["name"] for row in annual_accounts_directors(client)],
        "registered_office": client.get("registered_office_address"),
        "accountants": profile.get("practice_name") or "EPOS Accountancy",
        "employee_count": pack_details.get("employee_count"),
        "approval": {
            "director": active_pack.get("director_signing_name") if active_pack else None,
            "date": active_pack.get("board_approval_date") if active_pack else None,
            "audit_basis": ANNUAL_ACCOUNTS_AUDIT_BASES.get(active_pack.get("audit_exemption")) if active_pack else None,
        },
        "section_options": companies_house_section_options,
        "custom_sections": companies_house_custom_sections,
        "profit_and_loss_rows": annual_accounts_statement_rows(pnl, [
            ("turnover", "Turnover"),
            ("cost_of_sales", "Cost of sales"),
            ("gross_profit", "Gross profit"),
            ("operating_expenses", "Administrative expenses"),
            ("operating_profit", "Operating profit"),
            ("profit_before_tax", "Profit before tax"),
            ("tax_on_profit", "Tax on profit"),
            ("profit_after_tax", "Profit for the financial year"),
        ], comparative_pnl),
        "balance_sheet_rows": annual_accounts_statement_rows(balance_sheet, [
            ("assets", "Total assets"),
            ("liabilities", "Creditors and liabilities"),
            ("net_assets", "Net assets"),
            ("equity", "Capital and reserves"),
        ], comparative_balance_sheet),
        "detailed_profit_and_loss_rows": [
            {
                "label": f"{row.get('code') or ''} - {row.get('name') or ''}".strip(" -"),
                "amount": money_str(abs(money(row.get("raw_balance")))),
            }
            for row in (snapshot.get("trial_balance") or [])
            if row.get("statement") == "profit_and_loss" and money(row.get("raw_balance")) != Decimal("0.00")
        ],
        "notes": [
            {"number": "1", "title": "Statutory information", "body": f"{client.get('business_name') or ''} is a private company limited by shares, registered in England and Wales."},
            {"number": "2", "title": "Compliance with accounting standards", "body": f"These accounts are prepared under {(active_pack or {}).get('accounts_standard') or 'the selected accounting standard'}."},
            {"number": "3", "title": "Accounting policies", "body": "Accounting policies, estimates and judgements require preparer review before final issue."},
            {"number": "4", "title": "Tangible fixed assets", "body": "Cost, additions, accumulated depreciation and net book value are sourced from the fixed-asset and Trial Balance records."},
            {"number": "5", "title": "Debtors", "body": "Trade debtors and other receivables are presented from mapped current-asset accounts."},
            {"number": "6", "title": "Creditors: amounts falling due within one year", "body": "Trade creditors, taxation, social security, director loans and accruals are presented from mapped liability accounts."},
            {"number": "7", "title": "Share capital", "body": "Called-up and allotted share capital requires reconciliation to the client statutory records."},
            {"number": "8", "title": "Average number of employees", "body": f"The average number of employees during the year was {pack_details.get('employee_count') if pack_details.get('employee_count') is not None else 'not entered'}."},
        ],
    }
    return {
        "compliance": compliance_status,
        "filing_profile": filing_profile,
        "period": {
            "id": year.get("id") if year else None,
            "from": start or None,
            "to": end or None,
            "label": f"{start} to {end}" if start and end else None,
            "status": year.get("status") if year else None,
        },
        "active_pack": active_pack,
        "current_accountant": {
            "id": current_user.get("id"),
            "name": (
                f"{current_user.get('first_name') or ''} {current_user.get('last_name') or ''}".strip()
                or current_user.get("email")
            ),
            "email": current_user.get("email"),
        } if current_user else None,
        "directors": annual_accounts_directors(client),
        "audit_basis_options": [
            {"value": value, "label": label}
            for value, label in ANNUAL_ACCOUNTS_AUDIT_BASES.items()
        ],
        "taxonomy": {
            "selection": taxonomy_selection,
            "accounts_options": ANNUAL_ACCOUNTS_TAXONOMIES["accounts"],
            "computations_options": ANNUAL_ACCOUNTS_TAXONOMIES["computations"],
        },
        "posting_coverage": {
            "total_posted": int(posted_coverage.get("total_posted") or 0),
            "posted_in_period": posted_in_period,
            "first_posted_date": posted_coverage.get("first_posted_date"),
            "last_posted_date": posted_coverage.get("last_posted_date"),
        },
        "readiness": {
            "trial_balance": "Ready" if trial_ready else "Review",
            "hmrc": "Ready" if hmrc_ready else "Blocked",
            "companies_house": ("Ready" if ch_ready else "Blocked") if is_company_workflow else "Not applicable",
            "overall": "Ready" if hmrc_ready and (ch_ready or not is_company_workflow) else "Review",
        },
        "workflow": [
            {"step": "1. Freeze data snapshot", "purpose": "Immutable current and comparative Trial Balance", "status": "Available" if year else "Blocked"},
            {"step": "2. Map and prepare accounts", "purpose": "Trading statements, adjustments and detailed P&L", "status": "Review"},
            {"step": "3. Prepare tax return", "purpose": "CT600 and iXBRL" if is_company_workflow else "SA100, SA103 and tax calculation", "status": "Review"},
            {"step": "4. Approve return", "purpose": "Client and accountant review, declaration and approval", "status": "Required"},
            {"step": "5. Generate and validate", "purpose": "Destination-specific XML package and human-readable preview", "status": "Blocked"},
            {"step": "6. Submit and retain receipts", "purpose": "Gateway acknowledgement, acceptance or rejection", "status": "Blocked"},
        ],
        "blockers": blockers,
        "accounts_preview": {
            "profit_and_loss": {
                **pnl,
                "rows": (stored_contents or {}).get("profit_and_loss_rows") or annual_accounts_statement_rows(pnl, [
                    ("turnover", "Turnover"),
                    ("cost_of_sales", "Cost of sales"),
                    ("gross_profit", "Gross profit"),
                    ("operating_expenses", "Administrative and operating expenses"),
                    ("operating_profit", "Operating profit"),
                    ("profit_before_tax", "Profit before tax"),
                    ("tax_on_profit", "Tax on profit"),
                    ("profit_after_tax", "Profit for the financial year"),
                ], comparative_pnl),
            },
            "balance_sheet": {
                **balance_sheet,
                "rows": (stored_contents or {}).get("balance_sheet_rows") or annual_accounts_statement_rows(balance_sheet, [
                    ("assets", "Total assets"),
                    ("liabilities", "Creditors and liabilities"),
                    ("net_assets", "Net assets"),
                    ("equity", "Capital and reserves"),
                ], comparative_balance_sheet),
            },
            "validation": preview_validation,
        },
        "hmrc": {
            "destination": "HMRC Corporation Tax Online" if is_company_workflow else "HMRC Self Assessment Online",
            "client_type": client.get("client_type"),
            "workflow_enabled": ct600_workflow_enabled or is_sole_trader_workflow,
            "workflow_profile": "limited_company" if ct600_workflow_enabled else ("sole_trader" if is_sole_trader_workflow else None),
            "visible_boxes": CT600_LIMITED_COMPANY_VISIBLE_BOXES if ct600_workflow_enabled else [],
            "deferred_boxes": sorted(CT600_SUPPLEMENTARY_SELECTION_BOXES, key=lambda value: int(value)),
            "status": "Ready" if hmrc_ready else "Blocked",
            "submission_method": "CT600 XML envelope with iXBRL attachments" if is_company_workflow else "Self Assessment 2026 XML individual return",
            "components": [
                {"name": "CT600 return", "format": "HMRC CT600 XML", "status": "Draft model"},
                {"name": "Required supplementary pages", "format": "CT600A-P XML sections", "status": "Rule selection required"},
                {"name": "Statutory accounts", "format": "iXBRL 1.1", "status": "Not generated"},
                {"name": "Corporation Tax computations", "format": "iXBRL", "status": "Not generated"},
                {"name": "Elections and supporting documents", "format": "Permitted attachment", "status": "Review required"},
            ],
            "blockers": hmrc_blockers,
            "ct600_sections": ct600_sections,
            "forms": [
                {"id": "ct600", "label": "CT600", "status": "Available"},
            ] if ct600_workflow_enabled else [],
            "selected_form": "ct600",
            "ct600_form": ct600_form,
            "editor_sections": ct600_editor_sections,
            "auto_values": ct600_auto_values,
            "auto_boxes": sorted(CT600_AUTOMATIC_BOXES, key=lambda value: int(value)),
            "form_preview": hmrc_form_preview,
            "self_assessment_form": self_assessment_form,
            "self_assessment_pdf_forms": self_assessment_system_form_status(self_assessment_form),
        },
        "companies_house": {
            "destination": "Companies House",
            "status": ("Ready" if ch_ready else "Blocked") if is_company_workflow else "Not applicable",
            "applicable": is_company_workflow,
            "submission_method": "Software filing via Companies House XML gateway",
            "components": [
                {"name": "Statutory accounts copy", "format": "iXBRL", "status": "Not generated"},
                {"name": "Accounts type and exemptions", "format": "Submission metadata", "status": "Review required"},
                {"name": "Director approval and balance-sheet signature", "format": "Tagged facts and statements", "status": "Approval required"},
                {"name": "Presenter and company authentication", "format": "Gateway credentials", "status": profile.get("companies_house_connection_status") or "Not connected"},
            ],
            "blockers": ch_blockers,
            "accounts_preview": companies_house_preview,
            "section_options": companies_house_section_options,
            "custom_sections": companies_house_custom_sections,
        },
        "ixbrl": {
            "can_generate_preview": bool(
                active_pack
                and (active_pack.get("contents") or {}).get("snapshot_id")
                and taxonomy_selection["ready"]
            ),
            "can_generate_filing": production_generation_allowed,
            "outputs": [
                {
                    **dict(row),
                    "metadata": annual_accounts_json(row.get("metadata_json"), {}),
                    "validation": annual_accounts_json(row.get("validation_json"), {}),
                }
                for row in outputs
            ],
            "pipeline": [
                {"stage": "Taxonomy selection", "requirement": "FRC and CT computation taxonomy versions supported by HMRC for the accounting period", "status": "Ready" if taxonomy_selection["ready"] else "Not configured"},
                {"stage": "Fact generation", "requirement": "Contexts, units, signs, decimals, dimensions and provenance", "status": "Not implemented"},
                {"stage": "Document rendering", "requirement": "Human-readable XHTML accounts and computations", "status": "Not implemented"},
                {"stage": "Technical validation", "requirement": "XML, iXBRL, taxonomy, calculation and generic dimension rules", "status": "Not implemented"},
                {"stage": "Destination validation", "requirement": "HMRC Local Test Service and Companies House validation/test filing", "status": "Not connected"},
                {"stage": "Immutable approval", "requirement": "Hash, version, approver and generated artefact retention", "status": "Schema ready"},
            ],
        },
        "submissions": [dict(row) for row in filings],
        "packs": [serialize_annual_accounts_pack(row) for row in packs],
        "settings_requirements": [
            {"setting": "Accounts standard", "value": packs[0].get("accounts_standard") if packs else "FRS 102 Section 1A (default)", "status": "Review"},
            {"setting": "Accounts format", "value": packs[0].get("accounts_format") if packs else "Not selected", "status": "Required"},
            {"setting": "HMRC connection", "value": profile.get("hmrc_connection_status") or "Not connected", "status": "Required"},
            {"setting": "Companies House connection", "value": profile.get("companies_house_connection_status") or "Not connected", "status": "Required"},
            {
                "setting": "Accounts taxonomy",
                "value": taxonomy_selection["accounts"].get("label") or "Not selected",
                "status": "Ready" if taxonomy_selection["accounts"].get("hmrc_accepted") and taxonomy_selection["accounts"].get("period_valid") else "Required",
            },
            {
                "setting": "Computations taxonomy",
                "value": taxonomy_selection["computations"].get("label") or "Not selected",
                "status": "Ready" if taxonomy_selection["computations"].get("hmrc_accepted") and taxonomy_selection["computations"].get("period_valid") else "Required",
            },
        ],
    }


async def annual_accounts_pack_or_404(session: AsyncSession, client_id: str, pack_id: str) -> dict:
    row = await one(
        session,
        select(accounting_annual_accounts_packs).where(
            accounting_annual_accounts_packs.c.id == pack_id,
            accounting_annual_accounts_packs.c.client_id == client_id,
        ),
    )
    if not row:
        raise HTTPException(status_code=404, detail="Year End Accounts pack not found.")
    return dict(row)


async def create_annual_accounts_snapshot(
    session: AsyncSession,
    client: dict,
    pack: dict,
    user_id: Optional[str],
) -> dict:
    report = await financial_report_snapshot(
        session,
        str(client.get("id")),
        str(pack.get("period_from") or ""),
        str(pack.get("period_to") or ""),
    )
    comparative_report = {}
    if pack.get("comparative_period_from") and pack.get("comparative_period_to"):
        comparative_report = await financial_report_snapshot(
            session,
            str(client.get("id")),
            str(pack.get("comparative_period_from")),
            str(pack.get("comparative_period_to")),
        )
    tb_rows = report.get("trial_balance") or []
    comparative_tb_rows = comparative_report.get("trial_balance") or []
    tb_summary = report.get("trial_balance_summary") or {}
    validation = annual_accounts_pack_validation(pack, client, tb_summary, {
        "turnover": report.get("profit_and_loss", {}).get("turnover"),
        "balance_sheet_total": report.get("balance_sheet", {}).get("assets"),
    })
    previous = await one(
        session,
        select(func.max(accounting_annual_accounts_snapshots.c.version_number).label("version"))
        .where(accounting_annual_accounts_snapshots.c.pack_id == pack["id"]),
    ) or {}
    version = int(previous.get("version") or 0) + 1
    snapshot_payload = {
        "trial_balance": tb_rows,
        "trial_balance_summary": tb_summary,
        "comparative_trial_balance": comparative_tb_rows,
        "profit_and_loss": report.get("profit_and_loss") or {},
        "balance_sheet": report.get("balance_sheet") or {},
        "statement_of_changes_in_equity": report.get("statement_of_changes_in_equity") or {},
        "cash_flow": report.get("cash_flow") or {},
        "company": {
            "name": client.get("business_name"),
            "company_number": client.get("company_number"),
            "utr": client.get("utr"),
        },
        "pack": {
            "period_from": pack.get("period_from"),
            "period_to": pack.get("period_to"),
            "accounts_standard": pack.get("accounts_standard"),
            "accounts_format": pack.get("accounts_format"),
            "filing_output": pack.get("filing_output"),
        },
    }
    snapshot_hash = hashlib.sha256(
        json.dumps(snapshot_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    snapshot_id = new_id()
    now = utc_now_iso()
    await session.execute(insert(accounting_annual_accounts_snapshots).values(
        id=snapshot_id,
        client_id=client["id"],
        pack_id=pack["id"],
        version_number=version,
        current_trial_balance_json=json_compact(tb_rows),
        comparative_trial_balance_json=json_compact(comparative_tb_rows),
        statutory_mapping_json=json_compact([
            {
                "account_id": row.get("account_id"),
                "account_code": row.get("code"),
                "reporting_category_id": row.get("reporting_category_id"),
                "reporting_category_name": row.get("reporting_category_name"),
                "statutory_presentation": row.get("statutory_presentation"),
            }
            for row in tb_rows
        ]),
        company_details_json=json_compact(snapshot_payload["company"]),
        fixed_assets_json=json_compact({}),
        validation_json=json_compact({"issues": validation, "trial_balance_summary": tb_summary}),
        snapshot_hash=snapshot_hash,
        created_by=user_id,
        created_at=now,
    ))
    for row in tb_rows:
        await session.execute(insert(accounting_annual_accounts_trial_balance_lines).values(
            id=new_id(),
            client_id=client["id"],
            pack_id=pack["id"],
            snapshot_id=snapshot_id,
            period_kind="current",
            account_id=row.get("account_id"),
            account_code=str(row.get("code") or ""),
            account_name=row.get("name"),
            debit=str(row.get("debit") or "0.00"),
            credit=str(row.get("credit") or "0.00"),
            balance=str(row.get("raw_balance") or "0.00"),
            journal_line_count=int(row.get("journal_line_count") or 0),
            created_at=now,
        ))
        if row.get("mapping_status") == "unmapped" and money(row.get("raw_balance")) != Decimal("0.00"):
            await session.execute(insert(accounting_annual_accounts_mapping_exceptions).values(
                id=new_id(),
                client_id=client["id"],
                pack_id=pack["id"],
                snapshot_id=snapshot_id,
                account_id=row.get("account_id"),
                account_code=row.get("code"),
                reason="Material balance has no stable reporting-category mapping.",
                balance=str(row.get("raw_balance") or "0.00"),
                status="open",
                created_at=now,
            ))
    for row in comparative_tb_rows:
        await session.execute(insert(accounting_annual_accounts_trial_balance_lines).values(
            id=new_id(),
            client_id=client["id"],
            pack_id=pack["id"],
            snapshot_id=snapshot_id,
            period_kind="comparative",
            account_id=row.get("account_id"),
            account_code=str(row.get("code") or ""),
            account_name=row.get("name"),
            debit=str(row.get("debit") or "0.00"),
            credit=str(row.get("credit") or "0.00"),
            balance=str(row.get("raw_balance") or "0.00"),
            journal_line_count=int(row.get("journal_line_count") or 0),
            created_at=now,
        ))
    statutory_preview = annual_accounts_preview_from_trial_balance(tb_rows, comparative_tb_rows)
    contents = {
        "profit_and_loss": report.get("profit_and_loss") or {},
        "balance_sheet": report.get("balance_sheet") or {},
        "comparative_profit_and_loss": comparative_report.get("profit_and_loss") or {},
        "comparative_balance_sheet": comparative_report.get("balance_sheet") or {},
        **statutory_preview,
        "statement_of_changes_in_equity": report.get("statement_of_changes_in_equity") or {},
        "cash_flow": report.get("cash_flow") or {},
        "snapshot_id": snapshot_id,
        "snapshot_hash": snapshot_hash,
        "snapshot_version": version,
    }
    await session.execute(
        update(accounting_annual_accounts_packs)
        .where(accounting_annual_accounts_packs.c.id == pack["id"])
        .values(
            status="mapping_review",
            version_number=version,
            locked_snapshot=False,
            contents_json=json_compact(contents),
            updated_at=now,
        )
    )
    await add_accounting_audit(
        session,
        str(client["id"]),
        user_id,
        "annual_accounts_snapshot_created",
        "annual_accounts_pack",
        str(pack["id"]),
        {"snapshot_id": snapshot_id, "snapshot_hash": snapshot_hash, "version_number": version},
    )
    return {
        "id": snapshot_id,
        "pack_id": pack["id"],
        "version_number": version,
        "snapshot_hash": snapshot_hash,
        "validation": validation,
        "trial_balance_summary": tb_summary,
    }


async def native_accounting_reports(
    session: AsyncSession,
    client_id: str,
    accounts: Optional[list[dict]] = None,
    ap: Optional[dict] = None,
    ar: Optional[dict] = None,
    banking: Optional[dict] = None,
    vat: Optional[dict] = None,
) -> dict:
    accounts = accounts or await many(session, select(accounting_accounts).where(accounting_accounts.c.client_id == client_id))
    account_by_code = {str(account.get("code") or ""): account for account in accounts}
    contacts = await many(session, select(accounting_contacts).where(accounting_contacts.c.client_id == client_id))
    contact_by_id = {str(contact.get("id") or ""): contact for contact in contacts}
    journals = await many(session, select(accounting_journal_entries).where(accounting_journal_entries.c.client_id == client_id))
    journal_by_id = {str(journal.get("id") or ""): journal for journal in journals}
    lines = await many(session, select(accounting_journal_lines).where(accounting_journal_lines.c.client_id == client_id))
    ap = ap or await accounts_payable_workspace(session, client_id)
    ar = ar or await accounts_receivable_workspace(session, client_id)
    banking = banking or await banking_workspace(session, client_id, accounts)
    vat = vat or await vat_engine_workspace(session, client_id)

    balances: dict[str, Decimal] = {}
    movements: dict[str, Decimal] = {}
    account_activity: dict[str, list[dict]] = {}
    aged_receivables: dict[str, dict] = {}
    aged_payables: dict[str, dict] = {}
    today = datetime.now(timezone.utc).date()
    month_start = today.replace(day=1)

    def parse_entry_date(value: str) -> Optional[date]:
        try:
            return datetime.fromisoformat(str(value or "")[:10]).date()
        except Exception:
            return None

    def account_type_for(code: str) -> str:
        account = account_by_code.get(code) or {}
        return str(account.get("account_type") or account.get("category") or "").lower()

    def account_category_for(code: str) -> str:
        account = account_by_code.get(code) or {}
        return str(account.get("category") or account.get("account_type") or "").lower()

    def account_purpose_for(code: str) -> str:
        account = account_by_code.get(code) or {}
        return str(account.get("purpose") or "").lower()

    def signed_account_value(code: str, balance: Decimal) -> Decimal:
        kind = account_type_for(code)
        category = account_category_for(code)
        if kind in ("income", "sales") or category == "income":
            return -balance
        if kind in ("liability", "payable", "vat", "equity") or category in ("liability", "equity"):
            return -balance
        return balance

    def is_income(code: str) -> bool:
        return account_type_for(code) in ("income", "sales") or account_category_for(code) == "income"

    def is_expense(code: str) -> bool:
        return account_type_for(code) in ("expense", "purchases", "cost of sales", "overheads") or account_category_for(code) == "expense"

    def is_asset(code: str) -> bool:
        return account_type_for(code) in ("asset", "bank", "receivable") or account_category_for(code) == "asset"

    def is_liability(code: str) -> bool:
        return account_type_for(code) in ("liability", "payable", "vat", "tax", "payroll") or account_category_for(code) == "liability"

    def is_equity(code: str) -> bool:
        return account_type_for(code) == "equity" or account_category_for(code) == "equity"

    def report_row(account: dict, balance: Decimal) -> dict:
        code = str(account.get("code") or "")
        return {
            "account_id": account.get("id"),
            "code": code,
            "name": account.get("name"),
            "category": account.get("category"),
            "account_type": account.get("account_type"),
            "purpose": account.get("purpose"),
            "balance": money_str(signed_account_value(code, balance)),
            "raw_balance": money_str(balance),
            "activity": account_activity.get(code, []),
        }

    monthly: dict[str, dict[str, Decimal]] = {}
    for line in lines:
        code = str(line.get("account_code") or "")
        if not code:
            continue
        debit = money(line.get("debit"))
        credit = money(line.get("credit"))
        balances[code] = balances.get(code, Decimal("0.00")) + debit - credit
        journal = journal_by_id.get(str(line.get("entry_id") or "")) or {}
        entry_date = str(journal.get("entry_date") or "")[:10]
        entry_day = parse_entry_date(entry_date)
        if entry_day and entry_day >= month_start:
            movements[code] = movements.get(code, Decimal("0.00")) + debit - credit
        month_key = entry_date[:7] if entry_date else "undated"
        monthly.setdefault(month_key, {"income": Decimal("0.00"), "expenses": Decimal("0.00"), "profit": Decimal("0.00")})
        if is_income(code):
            monthly[month_key]["income"] += credit - debit
        elif is_expense(code):
            monthly[month_key]["expenses"] += debit - credit
        monthly[month_key]["profit"] = monthly[month_key]["income"] - monthly[month_key]["expenses"]
        account_activity.setdefault(code, []).append({
            "date": entry_date,
            "reference": journal.get("reference"),
            "description": line.get("description") or journal.get("description"),
            "source_type": journal.get("source_type"),
            "source_id": journal.get("source_id"),
            "debit": money_str(debit),
            "credit": money_str(credit),
        })
        if code not in ("1100", "2000"):
            continue
        contact_id = str(line.get("contact_id") or "")
        contact = contact_by_id.get(contact_id) or {}
        contact_name = contact.get("name") or line.get("contact_name") or "Unassigned"
        try:
            age_days = max(0, (today - datetime.fromisoformat(entry_date).date()).days)
        except Exception:
            age_days = 0
        bucket = "current" if age_days <= 30 else "days_31_60" if age_days <= 60 else "days_61_90" if age_days <= 90 else "days_90_plus"
        target = aged_receivables if code == "1100" else aged_payables
        movement = debit - credit if code == "1100" else credit - debit
        if not movement:
            continue
        key = contact_id or contact_name.lower()
        row = target.setdefault(key, {
            "contact_id": contact_id or None,
            "contact_name": contact_name,
            "current": Decimal("0.00"),
            "days_31_60": Decimal("0.00"),
            "days_61_90": Decimal("0.00"),
            "days_90_plus": Decimal("0.00"),
            "total": Decimal("0.00"),
        })
        row[bucket] += movement
        row["total"] += movement

    trial_balance = []
    income_total = Decimal("0.00")
    expense_total = Decimal("0.00")
    asset_total = Decimal("0.00")
    liability_total = Decimal("0.00")
    equity_total = Decimal("0.00")
    current_month_income = Decimal("0.00")
    current_month_expenses = Decimal("0.00")
    sections = {"income": [], "expenses": [], "assets": [], "liabilities": [], "equity": []}

    for account in sorted(accounts, key=lambda item: str(item.get("code") or "")):
        code = str(account.get("code") or "")
        balance = balances.get(code, Decimal("0.00"))
        movement = movements.get(code, Decimal("0.00"))
        account_type = str(account.get("account_type") or "").lower()
        row = report_row(account, balance)
        if is_income(code):
            income_total += -balance
            current_month_income += -movement
            sections["income"].append(row)
        elif is_expense(code):
            expense_total += balance
            current_month_expenses += movement
            sections["expenses"].append(row)
        elif is_asset(code):
            asset_total += balance
            sections["assets"].append(row)
        elif is_liability(code):
            liability_total += -balance
            sections["liabilities"].append(row)
        elif is_equity(code):
            equity_total += -balance
            sections["equity"].append(row)
        if balance:
            trial_balance.append({
                "account_id": account.get("id"),
                "code": code,
                "name": account.get("name"),
                "type": account_type,
                "category": account.get("category"),
                "purpose": account.get("purpose"),
                "debit": money_str(balance if balance > 0 else Decimal("0.00")),
                "credit": money_str(-balance if balance < 0 else Decimal("0.00")),
                "movement": money_str(movement),
                "activity": account_activity.get(code, []),
            })

    month_rows = []
    for key in sorted([k for k in monthly.keys() if k != "undated"])[-12:]:
        values = monthly[key]
        month_rows.append({
            "period": key,
            "income": money_str(values["income"]),
            "expenses": money_str(values["expenses"]),
            "profit": money_str(values["profit"]),
        })

    cash_at_bank = sum(
        (signed_account_value(code, balance) for code, balance in balances.items() if account_purpose_for(code) == "bank account" or account_type_for(code) == "bank"),
        Decimal("0.00"),
    )
    ar_total = sum((row["total"] for row in aged_receivables.values()), Decimal("0.00"))
    ap_total = sum((row["total"] for row in aged_payables.values()), Decimal("0.00"))
    vat_liability = money(vat.get("dashboard", {}).get("net_vat_due"))
    gross_profit = income_total - sum(
        (balances.get(str(account.get("code") or ""), Decimal("0.00")) for account in accounts if str(account.get("account_type") or "").lower() == "cost of sales"),
        Decimal("0.00"),
    )
    net_profit = income_total - expense_total
    recent_activity = []
    for journal in sorted(journals, key=lambda item: (str(item.get("entry_date") or ""), str(item.get("created_at") or "")), reverse=True)[:12]:
        recent_activity.append({
            "date": str(journal.get("entry_date") or "")[:10],
            "module": vat_source_module(str(journal.get("source_type") or "")),
            "record_type": str(journal.get("source_type") or "journal").replace("_", " ").title(),
            "reference": journal.get("reference"),
            "description": journal.get("description"),
            "amount": money_str(money(journal.get("total_debit"))),
        })

    vat_transactions = vat.get("transactions", [])
    vat_by_code: dict[str, dict] = {}
    for item in vat_transactions:
        key = str(item.get("vat_code") or "No VAT")
        row = vat_by_code.setdefault(key, {"vat_code": key, "net": Decimal("0.00"), "vat": Decimal("0.00"), "gross": Decimal("0.00"), "transactions": 0})
        row["net"] += money(item.get("net"))
        row["vat"] += money(item.get("vat"))
        row["gross"] += money(item.get("gross"))
        row["transactions"] += 1

    def serialize_totals(rows: dict[str, dict]) -> list[dict]:
        return [
            {**row, "net": money_str(row["net"]), "vat": money_str(row["vat"]), "gross": money_str(row["gross"])}
            for row in sorted(rows.values(), key=lambda item: item["vat_code"])
        ]

    def percent_str(value: Decimal) -> str:
        return f"{value.quantize(Decimal('0.01'))}%"

    bank_reports = banking.get("reports", {})
    bank_transactions = banking.get("transactions", [])
    purchase_invoices = ap.get("invoices", [])
    sales_invoices = ar.get("invoices", [])
    supplier_spend = []
    for row in ap.get("suppliers", []):
        supplier_spend.append({
            "supplier": row.get("name"),
            "outstanding": row.get("outstanding_balance") or "0.00",
            "invoice_count": len([i for i in purchase_invoices if str(i.get("supplier_id") or "") == str(row.get("id") or "")]),
        })
    customer_sales = []
    for row in ar.get("customers", []):
        customer_sales.append({
            "customer": row.get("name"),
            "outstanding": row.get("outstanding_balance") or "0.00",
            "invoice_count": len([i for i in sales_invoices if str(i.get("customer_id") or "") == str(row.get("id") or "")]),
        })

    return {
        "dashboard": {
            "revenue_this_month": money_str(current_month_income),
            "expenses_this_month": money_str(current_month_expenses),
            "gross_profit": money_str(gross_profit),
            "net_profit": money_str(net_profit),
            "cash_at_bank": money_str(cash_at_bank),
            "vat_liability": money_str(vat_liability),
            "accounts_receivable": money_str(ar_total),
            "accounts_payable": money_str(ap_total),
            "financial_performance": month_rows,
            "bank_balances": banking.get("bank_accounts", []),
            "working_capital": {
                "debtors": money_str(ar_total),
                "creditors": money_str(ap_total),
                "cash": money_str(cash_at_bank),
                "net_working_capital": money_str(ar_total + cash_at_bank - ap_total),
            },
            "recent_activity": recent_activity,
        },
        "profit_and_loss": {
            "income": money_str(income_total),
            "expenses": money_str(expense_total),
            "profit": money_str(income_total - expense_total),
            "gross_profit": money_str(gross_profit),
            "sections": {
                "income": sections["income"],
                "expenses": sections["expenses"],
            },
            "monthly": month_rows,
        },
        "balance_sheet": {
            "assets": money_str(asset_total),
            "liabilities": money_str(liability_total),
            "equity": money_str(equity_total),
            "net_assets": money_str(asset_total - liability_total),
            "current_year_profit": money_str(net_profit),
            "sections": {
                "assets": sections["assets"],
                "liabilities": sections["liabilities"],
                "equity": sections["equity"],
            },
        },
        "trial_balance": trial_balance,
        "cash_flow": {
            "operating_activities": money_str(net_profit),
            "investing_activities": money_str(Decimal("0.00")),
            "financing_activities": money_str(Decimal("0.00")),
            "net_cash_movement": money_str(sum((bank_transaction_amount(t) for t in bank_transactions), Decimal("0.00"))),
            "rows": bank_transactions[:50],
        },
        "statement_of_changes_in_equity": {
            "opening_equity": money_str(equity_total - net_profit),
            "current_year_profit": money_str(net_profit),
            "closing_equity": money_str(equity_total),
        },
        "management": {
            "department_summary": [],
            "income_vs_expenses": month_rows,
            "monthly_performance": month_rows,
            "trend_analysis": month_rows,
            "kpi_summary": {
                "gross_margin": percent_str((gross_profit / income_total * Decimal("100")) if income_total else Decimal("0.00")),
                "net_margin": percent_str((net_profit / income_total * Decimal("100")) if income_total else Decimal("0.00")),
                "working_capital": money_str(ar_total + cash_at_bank - ap_total),
            },
        },
        "vat_reports": {
            "return_summary": vat.get("current_boxes", {}),
            "detail": vat_transactions,
            "audit": vat_transactions,
            "exceptions": vat.get("reports", {}).get("exceptions", []),
            "by_code": serialize_totals(vat_by_code),
        },
        "sales_reports": {
            "sales_analysis": sales_invoices,
            "customer_sales": customer_sales,
            "invoice_analysis": sales_invoices,
            "receipts_analysis": ar.get("receipts", []),
            "aged_debtors": serialize_aged_balances(aged_receivables),
        },
        "purchase_reports": {
            "purchase_analysis": purchase_invoices,
            "supplier_spend": supplier_spend,
            "outstanding_bills": [i for i in purchase_invoices if money(i.get("outstanding_amount")) > Decimal("0.00")],
            "purchase_vat": [t for t in vat_transactions if t.get("direction") == "purchase"],
            "payment_forecast": ap.get("payments", []),
            "aged_creditors": serialize_aged_balances(aged_payables),
        },
        "bank_reports": {
            "cashbook": banking.get("cashbook", []),
            "reconciliation": bank_reports.get("unreconciled_items", []),
            "bank_charges": bank_reports.get("bank_charges", []),
            "interest": bank_reports.get("interest", []),
            "bank_activity": bank_transactions,
            "outstanding_transactions": bank_reports.get("unreconciled_items", []),
            "balances": banking.get("bank_accounts", []),
        },
        "custom_reports": {
            "available_columns": ["Date", "Reference", "Account", "Contact", "Net", "VAT", "Gross", "Source Module", "Status"],
            "saved_reports": [],
            "grouping_options": ["Account", "Contact", "VAT Code", "Month", "Source Module"],
            "sorting_options": ["Date", "Amount", "Reference", "Account"],
        },
        "report_scheduler": {
            "frequencies": ["Daily", "Weekly", "Monthly", "Quarterly"],
            "delivery_methods": ["Download", "Email (future)", "Client Portal (future)"],
            "scheduled_reports": [],
        },
        "exports": {
            "formats": ["PDF", "Excel", "CSV"],
            "print_layout": "EPOS standard report layout",
            "generated": [],
        },
        "settings": {
            "report_basis": "accrual",
            "default_date_range": "current_financial_year",
            "comparative_periods": True,
            "currency": "GBP",
            "pdf_branding": "EPOS Accountancy",
        },
        "aged_receivables": serialize_aged_balances(aged_receivables),
        "aged_payables": serialize_aged_balances(aged_payables),
        "account_count": len(account_by_code),
    }


def serialize_aged_balances(rows: dict[str, dict]) -> list[dict]:
    result = []
    for row in rows.values():
        if row["total"] == Decimal("0.00"):
            continue
        result.append({
            "contact_id": row.get("contact_id"),
            "contact_name": row.get("contact_name"),
            "current": money_str(row["current"]),
            "days_31_60": money_str(row["days_31_60"]),
            "days_61_90": money_str(row["days_61_90"]),
            "days_90_plus": money_str(row["days_90_plus"]),
            "total": money_str(row["total"]),
        })
    return sorted(result, key=lambda item: str(item.get("contact_name") or "").lower())


FIXED_ASSET_DEFAULT_CATEGORIES = [
    ("Plant & Machinery", 60),
    ("Motor Vehicles", 48),
    ("Office Equipment", 36),
    ("Computer Equipment", 36),
    ("Furniture & Fixtures", 60),
    ("Buildings", 300),
    ("Leasehold Improvements", 120),
]


def default_fixed_asset_settings(client_id: str, now: Optional[str] = None) -> dict:
    timestamp = now or utc_now_iso()
    return {
        "id": new_id(),
        "client_id": client_id,
        "default_depreciation_method": "straight_line",
        "posting_frequency": "monthly",
        "asset_number_prefix": "FA",
        "next_asset_number": 1,
        "capitalisation_threshold": "500.00",
        "default_fixed_asset_account": "1500",
        "default_accumulated_depreciation_account": "1590",
        "default_depreciation_expense_account": "7500",
        "default_disposal_account": "7010",
        "created_at": timestamp,
        "updated_at": timestamp,
    }


async def ensure_fixed_asset_settings(session: AsyncSession, client_id: str) -> dict:
    existing = await one(session, select(accounting_fixed_asset_settings).where(accounting_fixed_asset_settings.c.client_id == client_id))
    if existing:
        return existing
    row = default_fixed_asset_settings(client_id)
    await session.execute(insert(accounting_fixed_asset_settings).values(**row))
    return row


async def ensure_fixed_asset_categories(session: AsyncSession, client_id: str, settings_row: Optional[dict] = None) -> list[dict]:
    existing = await many(
        session,
        select(accounting_fixed_asset_categories)
        .where(accounting_fixed_asset_categories.c.client_id == client_id)
        .order_by(accounting_fixed_asset_categories.c.name.asc()),
    )
    if existing:
        return existing
    settings_row = settings_row or await ensure_fixed_asset_settings(session, client_id)
    now = utc_now_iso()
    for name, life_months in FIXED_ASSET_DEFAULT_CATEGORIES:
        await session.execute(
            insert(accounting_fixed_asset_categories).values(
                id=new_id(),
                client_id=client_id,
                name=name,
                description=f"Default category for {name.lower()}",
                default_depreciation_method=settings_row.get("default_depreciation_method") or "straight_line",
                default_useful_life_months=life_months,
                default_residual_value="0.00",
                fixed_asset_account=settings_row.get("default_fixed_asset_account") or "1500",
                accumulated_depreciation_account=settings_row.get("default_accumulated_depreciation_account") or "1590",
                depreciation_expense_account=settings_row.get("default_depreciation_expense_account") or "7500",
                active=True,
                created_at=now,
                updated_at=now,
            )
        )
    return await many(
        session,
        select(accounting_fixed_asset_categories)
        .where(accounting_fixed_asset_categories.c.client_id == client_id)
        .order_by(accounting_fixed_asset_categories.c.name.asc()),
    )


def serialize_fixed_asset(row: dict) -> dict:
    item = dict(row)
    item["purchase_cost"] = money_str(money(item.get("purchase_cost")))
    item["residual_value"] = money_str(money(item.get("residual_value")))
    item["accumulated_depreciation"] = money_str(money(item.get("accumulated_depreciation")))
    item["net_book_value"] = money_str(money(item.get("net_book_value") or item.get("purchase_cost")))
    item["disposal_proceeds"] = money_str(money(item.get("disposal_proceeds")))
    return item


def serialize_fixed_asset_category(row: dict) -> dict:
    item = dict(row)
    item["default_residual_value"] = money_str(money(item.get("default_residual_value")))
    return item


def serialize_fixed_asset_event(row: dict) -> dict:
    item = dict(row)
    item["amount"] = money_str(money(item.get("amount")))
    return item


def next_asset_code(settings_row: dict) -> str:
    prefix = str(settings_row.get("asset_number_prefix") or "FA").strip() or "FA"
    number = int(settings_row.get("next_asset_number") or 1)
    return f"{prefix}-{number:05d}"


def account_from_code(accounts: list[dict], code: str, label: str) -> dict:
    account = next((a for a in accounts if str(a.get("code") or "") == str(code or "")), None)
    if not account:
        raise HTTPException(status_code=400, detail=f"{label} account {code or ''} is missing from the chart of accounts.")
    return account


def build_asset_schedule(asset: dict, months: int = 24) -> list[dict]:
    if str(asset.get("status") or "active") != "active":
        return []
    purchase_cost = money(asset.get("purchase_cost"))
    residual = money(asset.get("residual_value"))
    accumulated = money(asset.get("accumulated_depreciation"))
    life_months = max(1, int(asset.get("useful_life_months") or 36))
    start_date = parse_date_or_today(asset.get("in_service_date") or asset.get("capitalisation_date") or asset.get("purchase_date"))
    depreciable = max(Decimal("0.00"), purchase_cost - residual)
    straight_charge = (depreciable / Decimal(life_months)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    current_nbv = money(asset.get("net_book_value"))
    opening_nbv = max(residual, current_nbv if current_nbv else purchase_cost - accumulated)
    ytd = Decimal("0.00")
    schedule = []
    cursor = date(start_date.year, start_date.month, 1)
    for index in range(months):
        period_start = add_months_to_date(cursor, index)
        period_end = add_months_to_date(period_start, 1) - timedelta(days=1)
        if str(asset.get("depreciation_method") or "straight_line") == "reducing_balance":
            charge = (opening_nbv * Decimal("0.25") / Decimal("12")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            charge = min(charge, max(Decimal("0.00"), opening_nbv - residual))
        else:
            charge = min(straight_charge, max(Decimal("0.00"), purchase_cost - residual - accumulated - ytd))
        closing = max(residual, opening_nbv - charge)
        ytd += charge
        schedule.append({
            "asset_id": asset.get("id"),
            "asset_code": asset.get("asset_code"),
            "asset_name": asset.get("asset_name"),
            "period_label": period_start.strftime("%b %Y"),
            "period_start": period_start.isoformat(),
            "period_end": period_end.isoformat(),
            "opening_nbv": money_str(opening_nbv),
            "charge": money_str(charge),
            "ytd_depreciation": money_str(ytd),
            "accumulated_depreciation": money_str(accumulated + ytd),
            "closing_nbv": money_str(closing),
            "status": "scheduled",
        })
        opening_nbv = closing
        if charge <= Decimal("0.00"):
            break
    return schedule


async def fixed_assets_workspace(session: AsyncSession, client_id: str, accounts: Optional[list[dict]] = None, ap: Optional[dict] = None) -> dict:
    settings_row = await ensure_fixed_asset_settings(session, client_id)
    categories = await ensure_fixed_asset_categories(session, client_id, settings_row)
    assets = await many(
        session,
        select(accounting_fixed_assets)
        .where(accounting_fixed_assets.c.client_id == client_id)
        .order_by(accounting_fixed_assets.c.created_at.desc()),
    )
    events = await many(
        session,
        select(accounting_fixed_asset_events)
        .where(accounting_fixed_asset_events.c.client_id == client_id)
        .order_by(accounting_fixed_asset_events.c.created_at.desc())
        .limit(100),
    )
    posted_depreciation = await many(
        session,
        select(accounting_fixed_asset_depreciation)
        .where(accounting_fixed_asset_depreciation.c.client_id == client_id)
        .order_by(accounting_fixed_asset_depreciation.c.period_start.desc(), accounting_fixed_asset_depreciation.c.created_at.desc())
        .limit(200),
    )
    active_assets = [serialize_fixed_asset(a) for a in assets if str(a.get("status") or "active") == "active"]
    disposed_assets = [serialize_fixed_asset(a) for a in assets if str(a.get("status") or "") in {"disposed", "scrapped", "written_off"}]
    schedules = []
    for asset in active_assets:
        schedules.extend(build_asset_schedule(asset, 12))
    today = datetime.now(timezone.utc).date()
    current_month = today.strftime("%Y-%m")
    total_cost = sum((money(a.get("purchase_cost")) for a in active_assets), Decimal("0.00"))
    accumulated = sum((money(a.get("accumulated_depreciation")) for a in active_assets), Decimal("0.00"))
    nbv = sum((money(a.get("net_book_value")) for a in active_assets), Decimal("0.00"))
    added_this_year = len([a for a in assets if str(a.get("purchase_date") or "").startswith(str(today.year))])
    depreciation_this_month = sum((money(r.get("charge")) for r in posted_depreciation if str(r.get("period_start") or "").startswith(current_month)), Decimal("0.00"))
    category_totals: dict[str, dict] = {}
    for asset in active_assets:
        name = asset.get("category_name") or "Uncategorised"
        row = category_totals.setdefault(name, {"category": name, "count": 0, "cost": Decimal("0.00"), "nbv": Decimal("0.00")})
        row["count"] += 1
        row["cost"] += money(asset.get("purchase_cost"))
        row["nbv"] += money(asset.get("net_book_value"))
    threshold = money(settings_row.get("capitalisation_threshold"))
    existing_invoice_ids = {str(a.get("purchase_invoice_id") or "") for a in assets if a.get("purchase_invoice_id")}
    suggestions = []
    for invoice in (ap or {}).get("invoices", []):
        if str(invoice.get("id") or "") in existing_invoice_ids:
            continue
        gross = money(invoice.get("gross_amount"))
        net = money(invoice.get("net_amount"))
        candidate = gross if gross > Decimal("0.00") else net
        if candidate >= threshold:
            suggestions.append({
                "purchase_invoice_id": invoice.get("id"),
                "supplier_id": invoice.get("supplier_id"),
                "supplier_name": invoice.get("supplier_name"),
                "asset_name": invoice.get("description") or invoice.get("invoice_number") or "Purchase invoice asset",
                "purchase_date": invoice.get("invoice_date"),
                "purchase_cost": money_str(net if net > Decimal("0.00") else candidate),
                "reference": invoice.get("invoice_number") or invoice.get("reference"),
                "confidence": 72,
                "reason": f"Purchase is above the capitalisation threshold of {money_str(threshold)}.",
            })
    return {
        "settings": dict(settings_row),
        "categories": [serialize_fixed_asset_category(c) for c in categories],
        "assets": [serialize_fixed_asset(a) for a in assets],
        "events": [serialize_fixed_asset_event(e) for e in events],
        "depreciation_schedule": schedules,
        "posted_depreciation": [serialize_fixed_asset_event(r) if "event_type" in r else dict(r) for r in posted_depreciation],
        "suggestions": suggestions[:20],
        "dashboard": {
            "total_asset_cost": money_str(total_cost),
            "net_book_value": money_str(nbv),
            "accumulated_depreciation": money_str(accumulated),
            "assets_added_this_year": added_this_year,
            "assets_disposed": len(disposed_assets),
            "depreciation_this_month": money_str(depreciation_this_month),
            "awaiting_depreciation": len([s for s in schedules if money(s.get("charge")) > Decimal("0.00")]),
        },
        "panels": {
            "awaiting_depreciation": [s for s in schedules if money(s.get("charge")) > Decimal("0.00")][:8],
            "recently_acquired": active_assets[:8],
            "upcoming_disposals": [a for a in active_assets if "dispose" in str(a.get("notes") or "").lower()][:8],
            "fully_depreciated": [a for a in active_assets if money(a.get("net_book_value")) <= money(a.get("residual_value"))][:8],
        },
        "reports": {
            "asset_register": active_assets,
            "depreciation_schedule": schedules,
            "asset_additions": [serialize_fixed_asset(a) for a in assets if str(a.get("purchase_date") or "").startswith(str(today.year))],
            "asset_disposals": disposed_assets,
            "revaluations": [serialize_fixed_asset_event(e) for e in events if str(e.get("event_type") or "") == "revaluation"],
            "nbv_summary": [{"category": row["category"], "count": row["count"], "cost": money_str(row["cost"]), "nbv": money_str(row["nbv"])} for row in category_totals.values()],
            "category_analysis": [{"category": row["category"], "count": row["count"], "cost": money_str(row["cost"]), "nbv": money_str(row["nbv"])} for row in category_totals.values()],
        },
    }


def build_ai_accounting_workspace(
    client_id: str,
    summary: dict,
    accounts: list[dict],
    contacts: list[dict],
    journals: list[dict],
    periods: list[dict],
    audit_events: list[dict],
    ap: dict,
    ar: dict,
    banking: dict,
    vat: dict,
    reports: dict,
) -> dict:
    today = datetime.now(timezone.utc).date()
    ap_dashboard = ap.get("dashboard", {})
    ar_dashboard = ar.get("dashboard", {})
    banking_dashboard = banking.get("dashboard", {})
    vat_dashboard = vat.get("dashboard", {})
    report_dashboard = reports.get("dashboard", {})

    def amount_value(value) -> Decimal:
        return money(value)

    def due_days(value) -> Optional[int]:
        try:
            due = datetime.fromisoformat(str(value or "")[:10]).date()
            return (due - today).days
        except Exception:
            return None

    def dated_item_date(row: dict, *keys: str) -> str:
        for key in keys:
            value = str(row.get(key) or "")[:10]
            if value:
                return value
        return ""

    def queue_item(priority: str, module: str, title: str, detail: str, action: str, tab: str = "") -> dict:
        return {
            "id": new_id(),
            "priority": priority,
            "module": module,
            "title": title,
            "detail": detail,
            "action": action,
            "target_tab": tab,
        }

    work_queue: dict[str, list[dict]] = {"high": [], "medium": [], "low": []}
    exceptions: list[dict] = []
    approvals: list[dict] = []
    deadlines: list[dict] = []
    insights: list[dict] = []

    unreconciled = int(banking_dashboard.get("unreconciled_transactions") or 0)
    awaiting_match = int(banking_dashboard.get("awaiting_match") or 0)
    vat_outstanding = int(vat_dashboard.get("outstanding_returns") or 0)
    ap_awaiting = int(ap_dashboard.get("awaiting_approval") or 0)
    ar_awaiting = len([i for i in ar.get("invoices", []) if i.get("status") in {"draft", "awaiting_approval", "approved"}])
    ap_overdue = int(ap_dashboard.get("overdue_invoices") or 0)
    ar_overdue = int(ar_dashboard.get("overdue_invoices") or 0)

    if vat_outstanding:
        work_queue["high"].append(queue_item("High", "VAT", f"{vat_outstanding} VAT return needs attention", "A VAT period is open and at or past its return due date.", "Review VAT Returns", "VAT Returns"))
    if unreconciled:
        work_queue["high"].append(queue_item("High", "Banking", f"{unreconciled} unreconciled bank transactions", "Reconcile imported and manual bank transactions before reporting.", "Open Reconciliation", "Reconciliation"))
    if ar_overdue:
        work_queue["high"].append(queue_item("High", "Accounts Receivable", f"{ar_overdue} overdue customer invoices", "Customer cash collection needs review.", "Open Aged Debtors", "Aged Debtors"))
    if ap_overdue:
        work_queue["medium"].append(queue_item("Medium", "Accounts Payable", f"{ap_overdue} overdue supplier bills", "Supplier balances have passed their due date.", "Open Aged Creditors", "Aged Creditors"))
    if ap_awaiting:
        work_queue["medium"].append(queue_item("Medium", "Accounts Payable", f"{ap_awaiting} purchase invoices awaiting approval", "Approve or reject purchase invoices before posting.", "Open Purchase Invoices", "Purchase Invoices"))
    if ar_awaiting:
        work_queue["medium"].append(queue_item("Medium", "Accounts Receivable", f"{ar_awaiting} sales invoices awaiting posting", "Review sales invoices so income and debtors are up to date.", "Open Sales Invoices", "Sales Invoices"))
    if awaiting_match:
        work_queue["low"].append(queue_item("Low", "Banking", f"{awaiting_match} suggested bank matches", "Suggested matches are available for approval.", "Review Suggested Matches", "Reconciliation"))

    for invoice in ap.get("invoices", []):
        status = str(invoice.get("status") or "")
        if status in {"draft", "awaiting_approval", "approved"}:
            approvals.append({
                "module": "Accounts Payable",
                "record_type": "Purchase Invoice",
                "reference": invoice.get("invoice_number") or invoice.get("reference") or "Purchase invoice",
                "contact": invoice.get("supplier_name"),
                "amount": invoice.get("gross_amount"),
                "status": status.replace("_", " ").title(),
                "date": dated_item_date(invoice, "invoice_date", "created_at"),
            })
    for invoice in ar.get("invoices", []):
        status = str(invoice.get("status") or "")
        if status in {"draft", "awaiting_approval", "approved"}:
            approvals.append({
                "module": "Accounts Receivable",
                "record_type": "Sales Invoice",
                "reference": invoice.get("invoice_number") or invoice.get("reference") or "Sales invoice",
                "contact": invoice.get("customer_name"),
                "amount": invoice.get("gross_amount"),
                "status": status.replace("_", " ").title(),
                "date": dated_item_date(invoice, "invoice_date", "created_at"),
            })

    invoice_keys: dict[str, list[str]] = {}
    for invoice in ap.get("invoices", []):
        key = f"ap:{invoice.get('supplier_id')}:{str(invoice.get('invoice_number') or '').strip().lower()}:{money_str(money(invoice.get('gross_amount')))}"
        if invoice.get("invoice_number"):
            invoice_keys.setdefault(key, []).append(invoice.get("invoice_number"))
    for key, values in invoice_keys.items():
        if len(values) > 1:
            exceptions.append({"severity": "High", "module": "Accounts Payable", "type": "Possible duplicate", "detail": f"{len(values)} purchase invoices share supplier, number and amount.", "reference": values[0]})

    for item in vat.get("reports", {}).get("exceptions", []):
        exceptions.append({
            "severity": "Medium",
            "module": "VAT",
            "type": "Missing VAT data",
            "detail": "A VAT transaction is missing a VAT code or VAT period.",
            "reference": item.get("document_number") or item.get("source_id") or item.get("id"),
        })

    suspense_accounts = {str(a.get("code") or "") for a in accounts if str(a.get("purpose") or "").lower() == "suspense" or "suspense" in str(a.get("name") or "").lower()}
    for journal in journals:
        total = amount_value(journal.get("total_debit"))
        if total >= Decimal("5000.00"):
            exceptions.append({"severity": "Medium", "module": "General Ledger", "type": "Large journal", "detail": f"Journal total is {money_str(total)}.", "reference": journal.get("reference") or journal.get("id")})
        for line in journal.get("lines", []) or []:
            if str(line.get("account_code") or "") in suspense_accounts:
                exceptions.append({"severity": "High", "module": "General Ledger", "type": "Suspense posting", "detail": "A journal line has been posted to suspense.", "reference": journal.get("reference") or journal.get("id")})
                break

    for period in periods:
        if period.get("status") == "open":
            days = due_days(period.get("period_end"))
            if days is not None and 0 <= days <= 14:
                deadlines.append({"module": "General Ledger", "title": f"{period.get('period_name') or 'Accounting period'} ends soon", "start_date": period.get("period_start"), "due_date": period.get("period_end"), "status": period.get("status"), "days": days})
    for row in vat.get("periods", []):
        days = due_days(row.get("due_date"))
        if days is not None and days <= 45 and row.get("status") == "open":
            deadlines.append({"module": "VAT", "title": "VAT return due", "start_date": row.get("period_start"), "due_date": row.get("due_date"), "status": row.get("status"), "days": days})
    for invoice in ar.get("overdue_invoices", [])[:10]:
        deadlines.append({"module": "Accounts Receivable", "title": f"Customer invoice overdue: {invoice.get('invoice_number')}", "start_date": invoice.get("invoice_date"), "due_date": invoice.get("due_date"), "status": invoice.get("status"), "days": -int(invoice.get("days_overdue") or 0)})
    for invoice in ap.get("invoices", []):
        if money(invoice.get("outstanding_amount")) > Decimal("0.00"):
            days = due_days(invoice.get("due_date"))
            if days is not None and days <= 14:
                deadlines.append({"module": "Accounts Payable", "title": f"Supplier bill due: {invoice.get('invoice_number')}", "start_date": invoice.get("invoice_date"), "due_date": invoice.get("due_date"), "status": invoice.get("status"), "days": days})

    if amount_value(report_dashboard.get("net_profit")) < Decimal("0.00"):
        net_profit = report_dashboard.get("net_profit") or "0.00"
        insights.append({"tone": "warning", "module": "Reports", "title": "Profit is negative this month", "detail": f"Net profit is {net_profit}. Review high expense categories and unposted income."})
    if amount_value(ap_dashboard.get("outstanding_total")) > amount_value(ar_dashboard.get("outstanding_total")) and amount_value(ap_dashboard.get("outstanding_total")) > 0:
        insights.append({"tone": "warning", "module": "Cash", "title": "Supplier exposure is higher than customer debt", "detail": "Outstanding payables exceed outstanding receivables. Check short-term cash position before payment runs."})
    if banking_dashboard.get("last_bank_import"):
        insights.append({"tone": "info", "module": "Banking", "title": "Bank data is available", "detail": f"Last bank import was {banking_dashboard.get('last_bank_import')}. Review suggested matches while they are fresh."})
    if not insights:
        insights.append({"tone": "success", "module": "AI Workspace", "title": "No major accounting issues detected", "detail": "The current ledgers do not show urgent rule-based exceptions."})

    health_penalty = (
        min(25, len(exceptions) * 4)
        + min(20, unreconciled)
        + min(20, vat_outstanding * 8)
        + min(15, ap_awaiting + ar_awaiting)
        + min(20, ap_overdue + ar_overdue)
    )
    health_score = max(0, 100 - health_penalty)
    health_categories = [
        {"area": "Banking", "score": max(0, 100 - min(60, unreconciled * 5)), "status": "Healthy" if unreconciled == 0 else "Needs reconciliation"},
        {"area": "VAT", "score": max(0, 100 - min(70, vat_outstanding * 25 + len(vat.get("reports", {}).get("exceptions", [])) * 10)), "status": "Healthy" if not vat_outstanding else "Return due"},
        {"area": "Approvals", "score": max(0, 100 - min(60, (ap_awaiting + ar_awaiting) * 8)), "status": "Clear" if not (ap_awaiting + ar_awaiting) else "Waiting"},
        {"area": "Debtors/Creditors", "score": max(0, 100 - min(70, (ap_overdue + ar_overdue) * 10)), "status": "Healthy" if not (ap_overdue + ar_overdue) else "Overdue items"},
    ]

    def search_row(kind: str, label: str, reference: str = "", amount: str = "", module: str = "") -> dict:
        return {"type": kind, "label": label, "reference": reference or "", "amount": amount or "", "module": module or kind}

    search_index = []
    search_index += [search_row("Contact", c.get("name"), c.get("email"), "", str(c.get("contact_type") or "Contact").title()) for c in contacts]
    search_index += [search_row("Purchase Invoice", i.get("invoice_number") or "Purchase invoice", i.get("supplier_name"), i.get("gross_amount"), "Accounts Payable") for i in ap.get("invoices", [])]
    search_index += [search_row("Sales Invoice", i.get("invoice_number") or "Sales invoice", i.get("customer_name"), i.get("gross_amount"), "Accounts Receivable") for i in ar.get("invoices", [])]
    search_index += [search_row("Bank Transaction", t.get("description") or t.get("reference") or "Bank transaction", t.get("reference"), t.get("amount"), "Banking") for t in banking.get("transactions", [])]
    search_index += [search_row("Journal", j.get("reference") or "Journal", j.get("description"), j.get("total_debit"), "General Ledger") for j in journals]
    search_index += [search_row("VAT Return", str(r.get("period_end") or "VAT return"), r.get("status"), r.get("box5"), "VAT") for r in vat.get("returns", [])]

    assistant_answers = {
        "What needs my attention first?": (work_queue["high"][0]["detail"] if work_queue["high"] else "There is no high priority work in the current accounting workspace."),
        "Are bank transactions reconciled?": f"{unreconciled} bank transactions are unreconciled and {awaiting_match} have suggested matches.",
        "Is VAT ready?": f"Current VAT period: {vat_dashboard.get('current_period') or '-'}; net VAT due: {vat_dashboard.get('net_vat_due') or '0.00'}; outstanding returns: {vat_outstanding}.",
        "How is cash looking?": f"Cash at bank is {report_dashboard.get('cash_at_bank') or summary.get('bank_balance') or '0.00'}. Outstanding debtors are {ar_dashboard.get('outstanding_total') or '0.00'} and creditors are {ap_dashboard.get('outstanding_total') or '0.00'}.",
    }

    return {
        "kpis": [
            {"label": "Documents Awaiting Review", "value": ap_dashboard.get("draft_invoices", 0) + ar_awaiting, "module": "AI Workspace"},
            {"label": "Purchase Invoices Awaiting Approval", "value": ap_awaiting, "module": "Accounts Payable"},
            {"label": "Sales Invoices Awaiting Approval", "value": ar_awaiting, "module": "Accounts Receivable"},
            {"label": "Bank Transactions Awaiting Reconciliation", "value": unreconciled, "module": "Banking"},
            {"label": "VAT Return Status", "value": "Due" if vat_outstanding else "Current", "module": "VAT"},
            {"label": "Overdue Customer Invoices", "value": ar_overdue, "module": "Accounts Receivable"},
            {"label": "Overdue Supplier Bills", "value": ap_overdue, "module": "Accounts Payable"},
            {"label": "Cash Position", "value": report_dashboard.get("cash_at_bank") or summary.get("bank_balance") or "0.00", "module": "Reports"},
            {"label": "Profit This Month", "value": report_dashboard.get("net_profit") or reports.get("profit_and_loss", {}).get("profit") or "0.00", "module": "Reports"},
        ],
        "work_queue": work_queue,
        "insights": insights,
        "exceptions": exceptions,
        "approvals": approvals,
        "deadlines": sorted(deadlines, key=lambda item: str(item.get("due_date") or "9999-99-99")),
        "health_check": {"score": health_score, "categories": health_categories, "exception_count": len(exceptions)},
        "assistant": {"suggested_questions": list(assistant_answers.keys()), "answers": assistant_answers},
        "global_search": {"index": search_index[:500]},
        "notifications": (work_queue["high"] + exceptions)[:12],
        "settings": {
            "default_landing_tab": "Overview",
            "kpi_visibility": [item["label"] for item in [
                {"label": "Documents Awaiting Review"},
                {"label": "Bank Transactions Awaiting Reconciliation"},
                {"label": "VAT Return Status"},
                {"label": "Cash Position"},
                {"label": "Profit This Month"},
            ]],
            "work_queue_priorities": ["High", "Medium", "Low"],
            "assistant_mode": "Rule-based now, LLM-ready later",
        },
    }


def pick_csv_value(row: dict, candidates: list[str]) -> str:
    lookup = {str(k or "").strip().lower(): v for k, v in row.items()}
    for candidate in candidates:
        if candidate in lookup and lookup[candidate] not in (None, ""):
            return str(lookup[candidate]).strip()
    return ""


def parse_bank_csv_amount(value: str) -> Decimal:
    text_value = str(value or "").strip()
    if not text_value:
        return Decimal("0.00")
    negative = text_value.startswith("(") and text_value.endswith(")")
    text_value = text_value.replace("£", "").replace(",", "").replace("(", "").replace(")", "")
    parsed = money(text_value)
    return -parsed if negative else parsed


def normalize_csv_date(value: str) -> str:
    text_value = str(value or "").strip()
    if not text_value:
        return datetime.now(timezone.utc).date().isoformat()
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%d.%m.%Y", "%d/%m/%y", "%d-%m-%y"):
        try:
            return datetime.strptime(text_value, fmt).date().isoformat()
        except ValueError:
            pass
    return text_value


def add_months_to_date(value: date, months: int) -> date:
    month_index = value.month - 1 + months
    year = value.year + month_index // 12
    month = month_index % 12 + 1
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(value.day, last_day))


def parse_iso_date(value: str, field_name: str) -> date:
    try:
        return datetime.fromisoformat(str(value or "")[:10]).date()
    except Exception:
        raise HTTPException(status_code=400, detail=f"{field_name} must be a valid date.")


@api.get("/admin/automation")
async def get_automation_workspace(
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    return await automation_workspace(session, str(user["practice_id"]))


@api.post("/admin/automation/workflows")
async def create_automation_workflow(
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    name = str(payload.get("name") or "").strip()
    trigger_type = str(payload.get("trigger_type") or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Workflow name is required.")
    if not trigger_type:
        raise HTTPException(status_code=400, detail="Workflow trigger is required.")
    valid_triggers = {item["id"] for item in AUTOMATION_TRIGGER_CATALOG}
    valid_conditions = {item["id"] for item in AUTOMATION_CONDITION_CATALOG}
    valid_actions = {item["id"] for item in AUTOMATION_ACTION_CATALOG}
    conditions = payload.get("conditions") or []
    actions = payload.get("actions") or []
    if trigger_type not in valid_triggers:
        raise HTTPException(status_code=400, detail="Select a supported workflow trigger.")
    if any(not isinstance(item, dict) or item.get("field") not in valid_conditions for item in conditions):
        raise HTTPException(status_code=400, detail="One or more workflow conditions are not supported.")
    if any(not isinstance(item, dict) or item.get("type") not in valid_actions for item in actions):
        raise HTTPException(status_code=400, detail="One or more workflow actions are not supported.")
    now = utc_now_iso()
    workflow_id = new_id()
    await session.execute(
        insert(automation_workflows).values(
            id=workflow_id,
            practice_id=str(user["practice_id"]),
            name=name,
            description=str(payload.get("description") or ""),
            trigger_type=trigger_type,
            status=str(payload.get("status") or "active"),
            permission_role=str(payload.get("permission_role") or "admin"),
            blocks_json=automation_json(payload.get("blocks") or []),
            conditions_json=automation_json(conditions),
            actions_json=automation_json(actions),
            approval_required=bool(payload.get("approval_required")),
            time_saved_minutes=int(payload.get("time_saved_minutes") or 10),
            created_by=str(user.get("id") or ""),
            created_at=now,
            updated_at=now,
        )
    )
    await add_accounting_audit(session, "platform", str(user.get("id") or ""), "automation_workflow_created", "automation", workflow_id, {"name": name})
    await session.commit()
    return {"workflow": serialize_automation_workflow((await one(session, select(automation_workflows).where(automation_workflows.c.id == workflow_id))) or {})}


@api.put("/admin/automation/workflows/{workflow_id}")
async def update_automation_workflow(
    workflow_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    existing = await one(session, select(automation_workflows).where(automation_workflows.c.id == workflow_id, automation_workflows.c.practice_id == str(user["practice_id"])))
    if not existing:
        raise HTTPException(status_code=404, detail="Workflow not found.")
    values = {
        "name": str(payload.get("name") or existing.get("name") or "").strip(),
        "description": str(payload.get("description") if payload.get("description") is not None else existing.get("description") or ""),
        "trigger_type": str(payload.get("trigger_type") or existing.get("trigger_type") or ""),
        "status": str(payload.get("status") or existing.get("status") or "active"),
        "permission_role": str(payload.get("permission_role") or existing.get("permission_role") or "admin"),
        "approval_required": bool(payload.get("approval_required")) if "approval_required" in payload else bool(existing.get("approval_required")),
        "time_saved_minutes": int(payload.get("time_saved_minutes") if payload.get("time_saved_minutes") is not None else existing.get("time_saved_minutes") or 0),
        "updated_at": utc_now_iso(),
    }
    if "blocks" in payload:
        values["blocks_json"] = automation_json(payload.get("blocks") or [])
    if "conditions" in payload:
        values["conditions_json"] = automation_json(payload.get("conditions") or [])
    if "actions" in payload:
        values["actions_json"] = automation_json(payload.get("actions") or [])
    await session.execute(update(automation_workflows).where(automation_workflows.c.id == workflow_id, automation_workflows.c.practice_id == str(user["practice_id"])).values(**values))
    await add_accounting_audit(session, "platform", str(user.get("id") or ""), "automation_workflow_updated", "automation", workflow_id, {"name": values["name"], "status": values["status"]})
    await session.commit()
    return {"workflow": serialize_automation_workflow((await one(session, select(automation_workflows).where(automation_workflows.c.id == workflow_id))) or {})}


@api.post("/admin/automation/workflows/{workflow_id}/execute")
async def execute_automation_workflow(
    workflow_id: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    workflow = await one(session, select(automation_workflows).where(automation_workflows.c.id == workflow_id, automation_workflows.c.practice_id == str(user["practice_id"])))
    if not workflow:
        raise HTTPException(status_code=404, detail="Workflow not found.")
    if workflow.get("status") != "active":
        raise HTTPException(status_code=400, detail="Only active workflows can be executed.")
    request_payload = {**(payload or {}), "mode": "test", "manual": True}
    run = await create_automation_run(session, workflow, str(user.get("id") or ""), request_payload)
    await session.commit()
    return {"run": run, "workspace": await automation_workspace(session, str(user["practice_id"]))}


@api.post("/admin/automation/approvals/{approval_id}/{action}")
async def resolve_automation_approval(
    approval_id: str,
    action: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    if action not in {"approve", "reject"}:
        raise HTTPException(status_code=400, detail="Approval action must be approve or reject.")
    approval = await one(session, select(automation_approvals).where(automation_approvals.c.id == approval_id, automation_approvals.c.practice_id == str(user["practice_id"])))
    if not approval:
        raise HTTPException(status_code=404, detail="Approval not found.")
    now = utc_now_iso()
    new_status = "approved" if action == "approve" else "rejected"
    await session.execute(
        update(automation_approvals)
        .where(automation_approvals.c.id == approval_id)
        .values(status=new_status, resolved_by=str(user.get("id") or ""), resolved_at=now)
    )
    run_status = "completed" if action == "approve" else "failed"
    run_result = "Approved and resumed" if action == "approve" else "Rejected by approver"
    await session.execute(
        update(automation_runs)
        .where(automation_runs.c.id == approval.get("run_id"))
        .values(status=run_status, result=run_result, finished_at=now)
    )
    if action == "reject":
        await session.execute(
            insert(automation_exceptions).values(
                id=new_id(),
                practice_id=str(user["practice_id"]),
                workflow_id=approval.get("workflow_id"),
                run_id=approval.get("run_id"),
                exception_type="approval_rejected",
                message=str(payload.get("reason") or "Approval was rejected."),
                status="open",
                payload_json=json.dumps({"approval_id": approval_id}, default=str),
                created_at=now,
            )
        )
    await add_accounting_audit(session, "platform", str(user.get("id") or ""), f"automation_approval_{new_status}", "automation", approval_id, {"run_id": approval.get("run_id")})
    await session.commit()
    return await automation_workspace(session, str(user["practice_id"]))


@api.post("/admin/automation/exceptions/{exception_id}/{action}")
async def resolve_automation_exception(
    exception_id: str,
    action: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    if action not in {"retry", "resolve"}:
        raise HTTPException(status_code=400, detail="Exception action must be retry or resolve.")
    exception = await one(session, select(automation_exceptions).where(automation_exceptions.c.id == exception_id, automation_exceptions.c.practice_id == str(user["practice_id"])))
    if not exception:
        raise HTTPException(status_code=404, detail="Exception not found.")
    now = utc_now_iso()
    if action == "resolve":
        await session.execute(
            update(automation_exceptions)
            .where(automation_exceptions.c.id == exception_id)
            .values(status="resolved", resolution=str(payload.get("resolution") or "Resolved by admin."), resolved_at=now)
        )
    else:
        await session.execute(
            update(automation_exceptions)
            .where(automation_exceptions.c.id == exception_id)
            .values(status="retried", resolution=str(payload.get("resolution") or "Retry requested."), resolved_at=now)
        )
        await session.execute(
            update(automation_runs)
            .where(automation_runs.c.id == exception.get("run_id"))
            .values(status="queued", result="Retry requested", finished_at=None)
        )
    await add_accounting_audit(session, "platform", str(user.get("id") or ""), f"automation_exception_{action}", "automation", exception_id, {"run_id": exception.get("run_id")})
    await session.commit()
    return await automation_workspace(session, str(user["practice_id"]))


