@api.put("/admin/automation/settings")
async def update_automation_settings(
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    settings_row = await ensure_automation_seed_data(session, str(user["practice_id"]))
    recommendation_mode = str(payload.get("recommendation_mode") or "rule_based")
    permission_mode = str(payload.get("permission_mode") or "admin_only")
    retention_days = int(payload.get("execution_retention_days") or 365)
    if recommendation_mode not in {"rule_based", "disabled"}:
        raise HTTPException(status_code=400, detail="Recommendation mode must be rule_based or disabled.")
    if permission_mode not in {"admin_only", "role_based"}:
        raise HTTPException(status_code=400, detail="Permission mode must be admin_only or role_based.")
    if retention_days < 1 or retention_days > 3650:
        raise HTTPException(status_code=400, detail="Execution retention must be between 1 and 3650 days.")
    values = {
        "approval_required_by_default": bool(payload.get("approval_required_by_default")),
        "auto_retry_enabled": bool(payload.get("auto_retry_enabled")),
        "recommendation_mode": recommendation_mode,
        "permission_mode": permission_mode,
        "execution_retention_days": retention_days,
        "default_assignee": str(payload.get("default_assignee") or "admin"),
        "updated_at": utc_now_iso(),
    }
    await session.execute(update(automation_settings).where(automation_settings.c.id == settings_row.get("id")).values(**values))
    await add_accounting_audit(session, "platform", str(user.get("id") or ""), "automation_settings_updated", "automation", str(settings_row.get("id")), values)
    await session.commit()
    return await automation_workspace(session, str(user["practice_id"]))


