@api.post("/admin/accounting/clients/{client_id}/dimensions")
async def create_accounting_dimension(client_id: str, payload: dict, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    await ensure_native_accounting_client(session, client_id)
    type_id = str(payload.get("dimension_type_id") or "").strip()
    dimension_type = await one(session, select(accounting_dimension_types).where(accounting_dimension_types.c.client_id == client_id, accounting_dimension_types.c.id == type_id, accounting_dimension_types.c.status == "active"))
    if not dimension_type:
        raise HTTPException(status_code=400, detail="Select an active dimension type belonging to this client.")
    code = str(payload.get("code") or "").strip().upper()
    name = str(payload.get("name") or "").strip()
    if not code or not name:
        raise HTTPException(status_code=400, detail="Dimension code and name are required.")
    duplicate = await one(session, select(accounting_dimensions.c.id).where(accounting_dimensions.c.client_id == client_id, func.lower(accounting_dimensions.c.code) == code.lower()))
    if duplicate:
        raise HTTPException(status_code=409, detail=f"Dimension code '{code}' already exists.")
    now = utc_now_iso()
    row = {"id": new_id(), "client_id": client_id, "dimension_type_id": type_id, "code": code, "name": name, "description": str(payload.get("description") or "").strip(), "status": "active" if str(payload.get("status") or "active").lower() == "active" else "inactive", "is_default": bool(payload.get("is_default")), "created_at": now, "updated_at": now}
    if row["is_default"]:
        await session.execute(update(accounting_dimensions).where(accounting_dimensions.c.client_id == client_id).values(is_default=False, updated_at=now))
    await session.execute(insert(accounting_dimensions).values(**row))
    await add_accounting_audit(session, client_id, user.get("id"), "dimension_created", "accounting_settings", row["id"], row)
    await session.commit()
    return serialize_dimension(row, dimension_type)


@api.patch("/admin/accounting/clients/{client_id}/dimensions/{dimension_id}")
async def update_accounting_dimension(client_id: str, dimension_id: str, payload: dict, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    row = await validate_analytical_value(session, client_id, dimension_id, "dimension", allow_inactive=True)
    type_id = str(payload.get("dimension_type_id", row.get("dimension_type_id")) or "").strip()
    dimension_type = await one(session, select(accounting_dimension_types).where(accounting_dimension_types.c.client_id == client_id, accounting_dimension_types.c.id == type_id))
    if not dimension_type:
        raise HTTPException(status_code=400, detail="Dimension type does not belong to this client.")
    code = str(payload.get("code", row.get("code")) or "").strip().upper()
    name = str(payload.get("name", row.get("name")) or "").strip()
    if not code or not name:
        raise HTTPException(status_code=400, detail="Dimension code and name are required.")
    duplicate = await one(session, select(accounting_dimensions.c.id).where(accounting_dimensions.c.client_id == client_id, accounting_dimensions.c.id != dimension_id, func.lower(accounting_dimensions.c.code) == code.lower()))
    if duplicate:
        raise HTTPException(status_code=409, detail=f"Dimension code '{code}' already exists.")
    now = utc_now_iso()
    values = {"dimension_type_id": type_id, "code": code, "name": name, "description": str(payload.get("description", row.get("description") or "") or "").strip(), "status": "active" if str(payload.get("status", row.get("status") or "active")).lower() == "active" else "inactive", "is_default": bool(payload.get("is_default", row.get("is_default"))), "updated_at": now}
    if values["is_default"]:
        await session.execute(update(accounting_dimensions).where(accounting_dimensions.c.client_id == client_id, accounting_dimensions.c.id != dimension_id).values(is_default=False, updated_at=now))
    await session.execute(update(accounting_dimensions).where(accounting_dimensions.c.id == dimension_id).values(**values))
    await add_accounting_audit(session, client_id, user.get("id"), "dimension_updated", "accounting_settings", dimension_id, values)
    await session.commit()
    return serialize_dimension({**row, **values}, dimension_type)


@api.delete("/admin/accounting/clients/{client_id}/dimensions/{dimension_id}")
async def delete_accounting_dimension(client_id: str, dimension_id: str, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    row = await validate_analytical_value(session, client_id, dimension_id, "dimension", allow_inactive=True)
    usage_count = await analytical_value_usage_count(session, client_id, dimension_id, "dimension")
    if usage_count:
        raise HTTPException(status_code=409, detail=f"Dimension '{row.get('code')}' has been used on {usage_count} accounting record(s). Make it inactive instead.")
    await session.execute(delete(accounting_dimensions).where(accounting_dimensions.c.id == dimension_id))
    await add_accounting_audit(session, client_id, user.get("id"), "dimension_deleted", "accounting_settings", dimension_id, {"code": row.get("code")})
    await session.commit()
    return {"ok": True}


async def paged_audit_trail(
    session: AsyncSession, client_id: str, page: int, page_size: int, date_from: str = "", date_to: str = "",
    module: str = "", action: str = "", user_filter: str = "", entity_type: str = "", entity_id: str = "", search: str = "",
    scope_entity_id: str = "", scope_module: str = "",
) -> dict:
    safe_page, safe_size, offset = gl_page_values(page, page_size)
    conditions = [accounting_audit_log.c.client_id == client_id]
    if date_from: conditions.append(accounting_audit_log.c.created_at >= date_from)
    if date_to: conditions.append(accounting_audit_log.c.created_at <= f"{date_to}T23:59:59")
    if module: conditions.append(accounting_audit_log.c.module == module)
    if action: conditions.append(accounting_audit_log.c.action == action)
    if user_filter: conditions.append(accounting_audit_log.c.actor_id == user_filter)
    if entity_type: conditions.append(accounting_audit_log.c.entity_type == entity_type)
    if entity_id: conditions.append(or_(accounting_audit_log.c.entity_id == entity_id, accounting_audit_log.c.record_id == entity_id))
    if scope_module: conditions.append(or_(accounting_audit_log.c.module == scope_module, accounting_audit_log.c.entity_type == scope_module, accounting_audit_log.c.record_type == scope_module))
    if scope_entity_id:
        scope_conditions = [accounting_audit_log.c.entity_id == scope_entity_id, accounting_audit_log.c.record_id == scope_entity_id, accounting_audit_log.c.details_json.like(f"%{scope_entity_id}%")]
        if scope_module == "banking":
            bank_transaction_ids = select(accounting_bank_transactions.c.id).where(accounting_bank_transactions.c.client_id == client_id, accounting_bank_transactions.c.bank_account_id == scope_entity_id)
            scope_conditions.extend([accounting_audit_log.c.entity_id.in_(bank_transaction_ids), accounting_audit_log.c.record_id.in_(bank_transaction_ids)])
        conditions.append(or_(*scope_conditions))
    if search:
        pattern = f"%{search.strip().lower()}%"
        conditions.append(or_(func.lower(func.coalesce(accounting_audit_log.c.action, "")).like(pattern), func.lower(func.coalesce(accounting_audit_log.c.module, "")).like(pattern), func.lower(func.coalesce(accounting_audit_log.c.details_json, "")).like(pattern), func.lower(func.coalesce(accounting_audit_log.c.new_value, "")).like(pattern)))
    total_rows = int((await session.execute(select(func.count()).select_from(accounting_audit_log).where(*conditions))).scalar() or 0)
    records = await many(session, select(accounting_audit_log).where(*conditions).order_by(accounting_audit_log.c.created_at.desc()).offset(offset).limit(safe_size))
    rows = [serialize_audit_event(row) for row in records]
    return gl_response(rows, safe_page, safe_size, total_rows, {"audit_count": total_rows})


def log_audit_response(endpoint: str, client_id: str, started: float, payload: dict) -> None:
    logger.info("Native accounting audit %s client_id=%s elapsed_ms=%s rows=%s total_rows=%s payload_bytes=%s", endpoint, client_id, int((time.perf_counter() - started) * 1000), len(payload.get("rows") or []), payload.get("total_rows", 0), approximate_payload_size(payload))


