async def paged_report_query(session: AsyncSession, query, count_query, page: int, page_size: int, summary: Optional[dict] = None) -> dict:
    safe_page, safe_size, offset = gl_page_values(page, page_size)
    total_rows = int((await session.execute(count_query)).scalar() or 0)
    rows = await many(session, query.offset(offset).limit(safe_size))
    return gl_response([dict(row) for row in rows], safe_page, safe_size, total_rows, summary)


def financial_statement_account_section(account: dict) -> str:
    """Map a nominal to its UK financial-statement presentation section."""
    category = str(account.get("category") or "").strip().lower()
    account_type = str(account.get("account_type") or "").strip().lower()
    purpose = str(account.get("purpose") or "").strip().lower()
    name = str(account.get("name") or "").strip().lower()
    code = str(account.get("code") or "").strip()
    descriptor = " ".join((name, purpose, account_type))

    if category in {"income", "other income"} or account_type in {"income", "sales", "other income"}:
        if "interest" in descriptor or "investment income" in descriptor:
            return "finance_income"
        if category == "other income" or account_type == "other income":
            return "other_operating_income"
        return "turnover"

    if category in {"expense", "other expense"} or account_type in {"expense", "expenses", "purchases", "cost of sales", "overheads", "other expense"}:
        if code == "7510" or "dividend" in descriptor or "distribution" in descriptor:
            return "dividends"
        if "corporation tax" in descriptor or ("tax" in descriptor and "income" in descriptor):
            return "tax_on_profit"
        if account_type == "cost of sales" or "cost of sales" in descriptor or "cost of goods" in descriptor:
            return "cost_of_sales"
        if "finance cost" in descriptor or "interest payable" in descriptor or "bank charge" in descriptor or "credit card charge" in descriptor:
            return "finance_costs"
        return "operating_expenses"

    if category == "asset" or account_type in {"asset", "bank", "receivable", "current asset", "current assets", "fixed asset", "fixed asset contra", "tangible assets"}:
        return "assets"
    if category == "liability" or account_type in {"liability", "payable", "vat", "tax", "payroll", "current liability", "current liabilities"}:
        return "liabilities"
    if category == "equity" or account_type == "equity":
        return "equity"
    return ""


async def financial_statement_balances(
    session: AsyncSession,
    client_id: str,
    date_from: str = "",
    date_to: str = "",
    location_id: str = "",
    dimension_id: str = "",
) -> dict[str, Decimal]:
    result = await canonical_trial_balance(
        session,
        client_id,
        date_from=date_from,
        date_to=date_to,
        date_mode="movement" if date_from else "as_at",
        location_id=location_id,
        dimension_id=dimension_id,
    )
    return {
        str(row.get("code") or ""): money(row.get("raw_balance"))
        for row in result["trial_balance"]
    }


async def financial_report_snapshot(
    session: AsyncSession,
    client_id: str,
    date_from: str = "",
    date_to: str = "",
    financial_year: str = "",
    period: str = "",
    location_id: str = "",
    dimension_id: str = "",
) -> dict:
    start, end = await report_dates(session, client_id, date_from, date_to, financial_year, period)
    if location_id:
        await validate_analytical_value(session, client_id, "location", location_id, allow_inactive=True)
    if dimension_id:
        await validate_analytical_value(session, client_id, "dimension", dimension_id, allow_inactive=True)

    # Profit and loss is movement for the selected period. The balance sheet is
    # cumulative through the reporting date, not movement within the date range.
    accounts = await many(session, select(accounting_accounts).where(accounting_accounts.c.client_id == client_id).order_by(accounting_accounts.c.code.asc()))
    period_result = await canonical_trial_balance(
        session,
        client_id,
        date_from=start,
        date_to=end,
        date_mode="movement",
        location_id=location_id,
        dimension_id=dimension_id,
        accounts=accounts,
    )
    as_at_result = await canonical_trial_balance(
        session,
        client_id,
        date_to=end,
        date_mode="as_at",
        location_id=location_id,
        dimension_id=dimension_id,
        accounts=accounts,
    )
    period_balances = {str(row.get("code") or ""): money(row.get("raw_balance")) for row in period_result["trial_balance"]}
    as_at_balances = {str(row.get("code") or ""): money(row.get("raw_balance")) for row in as_at_result["trial_balance"]}
    opening_end = ""
    if start:
        try:
            opening_end = (date.fromisoformat(start) - timedelta(days=1)).isoformat()
        except ValueError:
            opening_end = ""
    opening_balances = await financial_statement_balances(session, client_id, "", opening_end, location_id, dimension_id) if opening_end else {}
    pnl_keys = ("turnover", "other_operating_income", "cost_of_sales", "operating_expenses", "finance_income", "finance_costs", "tax_on_profit", "dividends")
    sections = {key: [] for key in (*pnl_keys, "assets", "liabilities", "equity")}
    totals = {key: Decimal("0.00") for key in sections}
    opening_equity = Decimal("0.00")
    trial_balance = list(as_at_result["trial_balance"])
    for account in accounts:
        code = str(account.get("code") or "")
        section = financial_statement_account_section(account)
        raw_balance = period_balances.get(code, Decimal("0.00")) if section in pnl_keys else as_at_balances.get(code, Decimal("0.00"))
        signed = -raw_balance if section in {"turnover", "other_operating_income", "finance_income", "liabilities", "equity"} else raw_balance
        if section and signed:
            totals[section] += signed
            sections[section].append({
                "account_id": account.get("id"),
                "code": code,
                "name": account.get("name"),
                "balance": money_str(signed),
            })
        if section == "equity":
            opening_equity += -opening_balances.get(code, Decimal("0.00"))

    gross_profit = totals["turnover"] - totals["cost_of_sales"]
    operating_profit = gross_profit + totals["other_operating_income"] - totals["operating_expenses"]
    profit_before_tax = operating_profit + totals["finance_income"] - totals["finance_costs"]
    profit_after_tax = profit_before_tax - totals["tax_on_profit"]
    total_income = totals["turnover"] + totals["other_operating_income"] + totals["finance_income"]
    total_expenses = totals["cost_of_sales"] + totals["operating_expenses"] + totals["finance_costs"] + totals["tax_on_profit"]
    base_equity = totals["equity"]
    total_equity = base_equity + profit_after_tax - totals["dividends"]
    other_equity_movement = base_equity - opening_equity
    bank_conditions = [accounting_bank_transactions.c.client_id == client_id]
    if start: bank_conditions.append(accounting_bank_transactions.c.transaction_date >= start)
    if end: bank_conditions.append(accounting_bank_transactions.c.transaction_date <= end)
    if location_id: bank_conditions.append(accounting_bank_transactions.c.default_location_id == location_id)
    if dimension_id: bank_conditions.append(accounting_bank_transactions.c.default_dimension_id == dimension_id)
    cash_row = await one(session, select(func.sum(accounting_bank_transactions.c.money_in - accounting_bank_transactions.c.money_out).label("movement")).where(*bank_conditions)) or {}
    return {
        "profit_and_loss": {
            "income": money_str(total_income),
            "expenses": money_str(total_expenses),
            "turnover": money_str(totals["turnover"]),
            "cost_of_sales": money_str(totals["cost_of_sales"]),
            "gross_profit": money_str(gross_profit),
            "other_operating_income": money_str(totals["other_operating_income"]),
            "operating_expenses": money_str(totals["operating_expenses"]),
            "operating_profit": money_str(operating_profit),
            "finance_income": money_str(totals["finance_income"]),
            "finance_costs": money_str(totals["finance_costs"]),
            "profit_before_tax": money_str(profit_before_tax),
            "tax_on_profit": money_str(totals["tax_on_profit"]),
            "profit_after_tax": money_str(profit_after_tax),
            "profit": money_str(profit_after_tax),
            "sections": {key: sections[key] for key in pnl_keys if key != "dividends"},
        },
        "balance_sheet": {
            "as_at": end or None,
            "assets": money_str(totals["assets"]),
            "liabilities": money_str(totals["liabilities"]),
            "equity": money_str(total_equity),
            "equity_accounts": money_str(base_equity),
            "current_year_profit": money_str(profit_after_tax),
            "dividends": money_str(totals["dividends"]),
            "net_assets": money_str(totals["assets"] - totals["liabilities"]),
            "sections": {"assets": sections["assets"], "liabilities": sections["liabilities"], "equity": sections["equity"]},
        },
        "cash_flow": {"operating_activities": money_str(profit_after_tax), "investing_activities": "0.00", "financing_activities": "0.00", "net_cash_movement": money_str(money(cash_row.get("movement")))},
        "statement_of_changes_in_equity": {
            "opening_equity": money_str(opening_equity),
            "current_year_profit": money_str(profit_after_tax),
            "dividends": money_str(totals["dividends"]),
            "other_equity_movements": money_str(other_equity_movement),
            "closing_equity": money_str(total_equity),
            "sections": {"dividends": sections["dividends"], "equity": sections["equity"]},
        },
        "trial_balance": trial_balance,
        "trial_balance_summary": as_at_result["summary"],
        "presentation": {
            "framework": "UK Companies Act / FRS 102 presentation",
            "period_start": start or None,
            "period_end": end or None,
            "balance_sheet_basis": "as_at_period_end",
            "dividends_presentation": "statement_of_changes_in_equity",
            "prior_period_corrections": "post through the controlled journal and period-lock workflow",
        },
        "filters": {"location_id": location_id or None, "dimension_id": dimension_id or None},
    }


async def analytical_profit_and_loss_breakdown(
    session: AsyncSession,
    client_id: str,
    date_from: str,
    date_to: str,
    financial_year: str,
    period: str,
    group_by: str,
    location_id: str = "",
    dimension_id: str = "",
) -> list[dict]:
    start, end = await report_dates(session, client_id, date_from, date_to, financial_year, period)
    joined = accounting_journal_lines.join(
        accounting_journal_entries,
        accounting_journal_lines.c.entry_id == accounting_journal_entries.c.id,
    ).join(
        accounting_accounts,
        and_(
            accounting_accounts.c.client_id == client_id,
            accounting_accounts.c.code == accounting_journal_lines.c.account_code,
        ),
    )
    conditions = [
        accounting_journal_lines.c.client_id == client_id,
        accounting_journal_entries.c.status == "posted",
    ]
    if start: conditions.append(accounting_journal_entries.c.entry_date >= start)
    if end: conditions.append(accounting_journal_entries.c.entry_date <= end)
    if location_id: conditions.append(accounting_journal_lines.c.location_id == location_id)
    if dimension_id: conditions.append(accounting_journal_lines.c.dimension_id == dimension_id)
    income_case = case((
        or_(func.lower(accounting_accounts.c.category) == "income", func.lower(accounting_accounts.c.account_type).in_(["income", "sales"])),
        accounting_journal_lines.c.credit - accounting_journal_lines.c.debit,
    ), else_=0)
    expense_case = case((
        or_(func.lower(accounting_accounts.c.category) == "expense", func.lower(accounting_accounts.c.account_type).in_(["expense", "purchases", "cost of sales", "overheads"])),
        accounting_journal_lines.c.debit - accounting_journal_lines.c.credit,
    ), else_=0)
    group_columns = []
    if group_by in {"location", "location_dimension"}:
        group_columns.append(accounting_journal_lines.c.location_id)
    if group_by in {"dimension", "location_dimension"}:
        group_columns.append(accounting_journal_lines.c.dimension_id)
    result_rows = await many(
        session,
        select(*group_columns, func.sum(income_case).label("income"), func.sum(expense_case).label("expenses"))
        .select_from(joined).where(*conditions).group_by(*group_columns),
    )
    locations = {str(row["id"]): row for row in await many(session, select(accounting_locations).where(accounting_locations.c.client_id == client_id))}
    dimensions = {
        str(row["id"]): row
        for row in await many(
            session,
            select(accounting_dimensions, accounting_dimension_types.c.name.label("dimension_type_name"))
            .select_from(accounting_dimensions.join(accounting_dimension_types, accounting_dimensions.c.dimension_type_id == accounting_dimension_types.c.id))
            .where(accounting_dimensions.c.client_id == client_id),
        )
    }
    rows = []
    for result in result_rows:
        location = locations.get(str(result.get("location_id") or ""), {})
        dimension = dimensions.get(str(result.get("dimension_id") or ""), {})
        income = money(result.get("income"))
        expenses = money(result.get("expenses"))
        rows.append({
            "location_id": result.get("location_id"),
            "location_code": location.get("code"),
            "location_name": location.get("name") or "Unassigned",
            "dimension_id": result.get("dimension_id"),
            "dimension_type": dimension.get("dimension_type_name"),
            "dimension_code": dimension.get("code"),
            "dimension_name": dimension.get("name") or "Unassigned",
            "income": money_str(income),
            "expenses": money_str(expenses),
            "profit": money_str(income - expenses),
        })
    return rows


@api.get("/admin/accounting/clients/{client_id}/reports/financial-statements")
async def get_report_financial_statements(client_id: str, date_from: str = "", date_to: str = "", financial_year: str = "", period: str = "", search: str = "", location_id: str = "", dimension_id: str = "", group_by: str = "", user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    started = time.perf_counter(); await get_client_or_404(session, client_id)
    payload = await financial_report_snapshot(session, client_id, date_from, date_to, financial_year, period, location_id, dimension_id)
    if group_by in {"location", "dimension", "location_dimension"}:
        payload["profit_and_loss"]["analytical_breakdown"] = await analytical_profit_and_loss_breakdown(
            session, client_id, date_from, date_to, financial_year, period, group_by, location_id, dimension_id
        )
    if search:
        needle = search.strip().lower()
        matches = lambda row: needle in f"{row.get('code', '')} {row.get('name', '')}".lower()
        payload["trial_balance"] = [row for row in payload["trial_balance"] if matches(row)]
        for statement_name in ("profit_and_loss", "balance_sheet", "statement_of_changes_in_equity"):
            statement = payload.get(statement_name) or {}
            for section_name, rows in (statement.get("sections") or {}).items():
                statement["sections"][section_name] = [row for row in rows if matches(row)]
    log_report_response("financial-statements", client_id, started, payload); return payload


def filter_statement_account_rows(statement: dict, search: str) -> None:
    needle = str(search or "").strip().lower()
    if not needle:
        return
    for section_name, rows in (statement.get("sections") or {}).items():
        statement["sections"][section_name] = [
            row for row in rows
            if needle in f"{row.get('code', '')} {row.get('name', '')}".lower()
        ]


