@api.post("/admin/accounting/clients/{client_id}/year-end-accounts/packs")
async def create_year_end_accounts_pack(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    year_id = str(payload.get("financial_year_id") or "").strip()
    year = await one(
        session,
        select(accounting_financial_years).where(
            accounting_financial_years.c.id == year_id,
            accounting_financial_years.c.client_id == client_id,
        ),
    )
    period_from = str(year.get("start_date") or "") if year else str(payload.get("period_from") or "").strip()
    period_to = str(year.get("end_date") or "") if year else str(payload.get("period_to") or "").strip()
    try:
        if date.fromisoformat(period_to) < date.fromisoformat(period_from):
            raise HTTPException(status_code=400, detail="Accounts period end cannot be before its start.")
    except ValueError:
        raise HTTPException(status_code=400, detail="Choose a financial year or enter valid accounts period dates.")
    existing = await one(
        session,
        select(accounting_annual_accounts_packs).where(
            accounting_annual_accounts_packs.c.client_id == client_id,
            accounting_annual_accounts_packs.c.period_from == period_from,
            accounting_annual_accounts_packs.c.period_to == period_to,
        ),
    )
    if existing:
        raise HTTPException(status_code=409, detail="A Year End Accounts pack already exists for this financial year.")
    comparative_year = await one(
        session,
        select(accounting_financial_years)
        .where(
            accounting_financial_years.c.client_id == client_id,
            accounting_financial_years.c.end_date < period_from,
        )
        .order_by(accounting_financial_years.c.end_date.desc())
        .limit(1),
    )
    accounts_standard = str(payload.get("accounts_standard") or "FRS_102_1A").strip()
    accounts_format = str(payload.get("accounts_format") or "small_full").strip()
    company_trading_status = str(payload.get("company_trading_status") or "trading").strip()
    is_company_workflow = native_year_end_filing_profile(client.get("client_type")).get("workflow") == "corporation_tax"
    if not is_company_workflow:
        accounts_standard = "SOLE_TRADER"
        accounts_format = "sole_trader"
    configuration_issues = annual_accounts_configuration_issues(accounts_standard, accounts_format, company_trading_status) if is_company_workflow else []
    if configuration_issues:
        raise HTTPException(status_code=400, detail=" ".join(configuration_issues))
    now = utc_now_iso()
    client_directors = annual_accounts_directors(client)
    row = {
        "id": new_id(),
        "client_id": client_id,
        "period_from": period_from,
        "period_to": period_to,
        "comparative_period_from": payload.get("comparative_period_from") or (comparative_year.get("start_date") if comparative_year else None),
        "comparative_period_to": payload.get("comparative_period_to") or (comparative_year.get("end_date") if comparative_year else None),
        "accounts_standard": accounts_standard,
        "accounts_format": accounts_format,
        "filing_output": str(payload.get("filing_output") or "full_accounts"),
        "status": "draft",
        "hmrc_status": "draft",
        "version_number": 1,
        "locked_snapshot": False,
        "prepared_by": user.get("id"),
        "responsible_staff_member": payload.get("responsible_staff_member") or (
            f"{user.get('first_name') or ''} {user.get('last_name') or ''}".strip()
            or user.get("email")
        ),
        "company_trading_status": company_trading_status,
        "audit_exemption": payload.get("audit_exemption"),
        "director_signing_name": payload.get("director_signing_name") or (client_directors[0]["name"] if len(client_directors) == 1 else None),
        "board_approval_date": payload.get("board_approval_date"),
        "companies_house_submission_status": "not_prepared",
        "hmrc_submission_status": "not_prepared",
        "details_json": json_compact({
            "financial_year_id": year_id or None,
            "employee_count": payload.get("employee_count"),
            "accounts_taxonomy": payload.get("accounts_taxonomy"),
            "computations_taxonomy": payload.get("computations_taxonomy"),
        }),
        "contents_json": json_compact({}),
        "created_at": now,
        "updated_at": now,
    }
    await session.execute(insert(accounting_annual_accounts_packs).values(**row))
    await add_accounting_audit(session, client_id, user.get("id"), "annual_accounts_pack_created", "annual_accounts_pack", row["id"], row)
    await session.commit()
    return serialize_annual_accounts_pack(row)


@api.put("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}")
async def update_year_end_accounts_pack(
    client_id: str,
    pack_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    pack = await annual_accounts_pack_or_404(session, client_id, pack_id)
    if pack.get("locked_snapshot"):
        raise HTTPException(status_code=409, detail="Approved accounts are locked. Reopen the pack to create a new version.")
    allowed = {
        "accounts_standard", "accounts_format", "filing_output", "responsible_staff_member",
        "company_trading_status", "audit_exemption", "director_signing_name",
        "board_approval_date", "signature_date", "period_from", "period_to",
        "comparative_period_from", "comparative_period_to",
    }
    values = {key: payload.get(key) for key in allowed if key in payload}
    next_period_from = str(values.get("period_from") or pack.get("period_from") or "")
    next_period_to = str(values.get("period_to") or pack.get("period_to") or "")
    try:
        parsed_period_from = date.fromisoformat(next_period_from)
        parsed_period_to = date.fromisoformat(next_period_to)
    except ValueError:
        raise HTTPException(status_code=400, detail="Accounts period dates must use YYYY-MM-DD.")
    if parsed_period_to < parsed_period_from:
        raise HTTPException(status_code=400, detail="Accounts period end cannot be before its start.")
    period_changed = next_period_from != str(pack.get("period_from") or "") or next_period_to != str(pack.get("period_to") or "")
    if period_changed:
        duplicate = await one(
            session,
            select(accounting_annual_accounts_packs.c.id).where(
                accounting_annual_accounts_packs.c.client_id == client_id,
                accounting_annual_accounts_packs.c.period_from == next_period_from,
                accounting_annual_accounts_packs.c.period_to == next_period_to,
                accounting_annual_accounts_packs.c.id != pack_id,
            ),
        )
        if duplicate:
            raise HTTPException(status_code=409, detail="Another accounts pack already uses this period.")
        values.update({
            "status": "draft",
            "contents_json": json_compact({}),
            "reviewed_by": None,
            "approved_by": None,
            "hmrc_submission_status": "not_prepared",
            "companies_house_submission_status": "not_prepared",
        })
    details = annual_accounts_json(pack.get("details_json"), {})
    if "employee_count" in payload:
        try:
            employee_count = int(payload.get("employee_count"))
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="Average employee count must be a whole number.")
        if employee_count < 0:
            raise HTTPException(status_code=400, detail="Average employee count cannot be negative.")
        details["employee_count"] = employee_count
    for key, taxonomy_kind in (
        ("accounts_taxonomy", "accounts"),
        ("computations_taxonomy", "computations"),
    ):
        if key in payload:
            taxonomy_id = str(payload.get(key) or "").strip() or None
            if taxonomy_id and taxonomy_id not in {row["id"] for row in ANNUAL_ACCOUNTS_TAXONOMIES[taxonomy_kind]}:
                raise HTTPException(status_code=400, detail=f"Choose a supported {taxonomy_kind} taxonomy.")
            details[key] = taxonomy_id
    if "ct600_fields" in payload:
        valid_boxes = {
            box
            for page in CT600_OFFICIAL_PRINT_PAGES
            for box in page
        }
        submitted_fields = payload.get("ct600_fields")
        if not isinstance(submitted_fields, dict):
            raise HTTPException(status_code=400, detail="CT600 fields must be submitted as an object keyed by box number.")
        unknown_boxes = set(submitted_fields) - valid_boxes
        if unknown_boxes:
            raise HTTPException(status_code=400, detail=f"Unsupported CT600 boxes: {', '.join(sorted(unknown_boxes))}.")
        field_types = {
            box: field_type
            for section in CT600_FORM_SECTIONS
            for box, _label, field_type in section["fields"]
        }
        for box, value in submitted_fields.items():
            try:
                validate_ct600_submitted_value(str(box), value, field_types.get(str(box), "money"))
            except ValueError as error:
                raise HTTPException(status_code=400, detail=f"CT600 box {box} {error}.") from error
        details["ct600_fields"] = submitted_fields
    if payload.get("reset_ct600_fields") is True:
        details.pop("ct600_fields", None)
    if "self_assessment_fields" in payload:
        submitted_sa_fields = payload.get("self_assessment_fields")
        if not isinstance(submitted_sa_fields, dict):
            raise HTTPException(status_code=400, detail="Self Assessment fields must be submitted as an object.")
        valid_sa_fields = {key for section in SA100_SOLE_TRADER_SECTIONS for key, _label, _type, _automatic in section["fields"]}
        supplementary_key_pattern = re.compile(r"^sa(?:101|102|104s|105|106|107|108|109|110)_box_[0-9a-z_]+$")
        unknown_sa_fields = {
            key for key in submitted_sa_fields
            if key not in valid_sa_fields and not supplementary_key_pattern.fullmatch(str(key))
        }
        if unknown_sa_fields:
            raise HTTPException(status_code=400, detail=f"Unsupported Self Assessment fields: {', '.join(sorted(unknown_sa_fields))}.")
        oversized_sa_fields = [key for key, value in submitted_sa_fields.items() if len(str(value or "")) > 4000]
        if oversized_sa_fields:
            raise HTTPException(status_code=400, detail=f"Self Assessment field is too long: {', '.join(sorted(oversized_sa_fields))}.")
        details["self_assessment_fields"] = {
            str(key): value for key, value in submitted_sa_fields.items()
        }
    if payload.get("reset_self_assessment_fields") is True:
        details.pop("self_assessment_fields", None)
    if "companies_house_sections" in payload:
        valid_sections = {key for key, _label, _default in COMPANIES_HOUSE_SECTION_OPTIONS}
        submitted_sections = payload.get("companies_house_sections")
        if not isinstance(submitted_sections, dict):
            raise HTTPException(status_code=400, detail="Companies House sections must be submitted as an object.")
        unknown_sections = set(submitted_sections) - valid_sections
        if unknown_sections:
            raise HTTPException(status_code=400, detail=f"Unsupported Companies House sections: {', '.join(sorted(unknown_sections))}.")
        details["companies_house_sections"] = {
            key: bool(value) for key, value in submitted_sections.items()
        }
    if "companies_house_custom_sections" in payload:
        submitted_custom_sections = payload.get("companies_house_custom_sections")
        if not isinstance(submitted_custom_sections, list):
            raise HTTPException(status_code=400, detail="Custom Companies House sections must be submitted as a list.")
        if len(submitted_custom_sections) > 20:
            raise HTTPException(status_code=400, detail="No more than 20 custom Companies House sections can be added.")
        custom_sections = []
        seen_custom_ids = set()
        for index, row in enumerate(submitted_custom_sections):
            if not isinstance(row, dict):
                raise HTTPException(status_code=400, detail="Each custom Companies House section must be an object.")
            custom_id = re.sub(r"[^a-z0-9_-]", "", str(row.get("id") or "").lower())[:64] or f"custom_{index + 1}"
            title = str(row.get("title") or "").strip()[:160]
            content = str(row.get("content") or "").strip()[:5000]
            if not title:
                raise HTTPException(status_code=400, detail="Every custom Companies House section requires a title.")
            if custom_id in seen_custom_ids:
                raise HTTPException(status_code=400, detail="Custom Companies House section identifiers must be unique.")
            seen_custom_ids.add(custom_id)
            custom_sections.append({
                "id": custom_id,
                "title": title,
                "content": content,
                "enabled": bool(row.get("enabled", True)),
            })
        details["companies_house_custom_sections"] = custom_sections
    if any(key in payload for key in {
        "employee_count", "accounts_taxonomy", "computations_taxonomy",
        "ct600_fields", "reset_ct600_fields", "companies_house_sections", "companies_house_custom_sections",
        "self_assessment_fields", "reset_self_assessment_fields",
    }):
        values["details_json"] = json_compact(details)
    next_accounts_standard = str(values.get("accounts_standard") or pack.get("accounts_standard") or "")
    next_accounts_format = str(values.get("accounts_format") or pack.get("accounts_format") or "")
    next_trading_status = str(values.get("company_trading_status") or pack.get("company_trading_status") or "trading")
    configuration_issues = annual_accounts_configuration_issues(
        next_accounts_standard,
        next_accounts_format,
        next_trading_status,
    ) if native_year_end_filing_profile((await get_client_or_404(session, client_id)).get("client_type")).get("workflow") == "corporation_tax" else []
    if configuration_issues:
        raise HTTPException(status_code=400, detail=" ".join(configuration_issues))
    if values.get("audit_exemption") and values["audit_exemption"] not in ANNUAL_ACCOUNTS_AUDIT_BASES:
        raise HTTPException(status_code=400, detail="Choose a supported audit exemption or auditor-report basis.")
    if values.get("director_signing_name") and values["director_signing_name"] not in {
        row["name"] for row in annual_accounts_directors(await get_client_or_404(session, client_id))
    }:
        raise HTTPException(status_code=400, detail="Choose a signing director recorded on the client account.")
    if values.get("board_approval_date") and values["board_approval_date"] < next_period_to:
        raise HTTPException(status_code=400, detail="Board approval date cannot be before the accounts period end.")
    values["updated_at"] = utc_now_iso()
    await session.execute(update(accounting_annual_accounts_packs).where(accounting_annual_accounts_packs.c.id == pack_id).values(**values))
    await add_accounting_audit(session, client_id, user.get("id"), "annual_accounts_pack_updated", "annual_accounts_pack", pack_id, values)
    await session.commit()
    return serialize_annual_accounts_pack({**pack, **values})


@api.post("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}/snapshot")
async def snapshot_year_end_accounts_pack(
    client_id: str,
    pack_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    pack = await annual_accounts_pack_or_404(session, client_id, pack_id)
    if pack.get("locked_snapshot"):
        raise HTTPException(status_code=409, detail="Approved accounts are locked. Reopen the pack before refreshing its snapshot.")
    result = await create_annual_accounts_snapshot(session, client, pack, user.get("id"))
    await session.commit()
    return result


@api.post("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}/generate-preview")
async def generate_year_end_accounts_preview_package(
    client_id: str,
    pack_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    pack_row = await annual_accounts_pack_or_404(session, client_id, pack_id)
    pack = serialize_annual_accounts_pack(pack_row)
    snapshot_id = (pack.get("contents") or {}).get("snapshot_id")
    if not snapshot_id:
        raise HTTPException(status_code=409, detail="Create a Trial Balance snapshot before generating preview artefacts.")
    taxonomy = annual_accounts_taxonomy_selection(pack)
    if not taxonomy["ready"]:
        raise HTTPException(
            status_code=409,
            detail="Save both a period-valid FRC accounts taxonomy and Corporation Tax computations taxonomy before generation.",
        )

    workspace = await year_end_accounts_workspace(session, client, user)
    accounts_preview = workspace["companies_house"]["accounts_preview"]
    ct600_preview = workspace["hmrc"]["ct600_form"]
    ixbrl_html = annual_accounts_production_preview_html(client, pack, accounts_preview)
    computation_preview = {
        "title": f"{client.get('business_name') or ''} - Corporation Tax computation",
        "period_from": pack.get("period_from"),
        "period_to": pack.get("period_to"),
        "profit_before_tax": (workspace.get("accounts_preview") or {}).get("profit_and_loss", {}).get("profit_before_tax"),
        "depreciation_add_back": None,
        "capital_allowances": None,
        "taxable_total_profits": None,
        "corporation_tax_charge_per_accounts": (workspace.get("accounts_preview") or {}).get("profit_and_loss", {}).get("tax_on_profit"),
        "status": "Tax adjustments and capital allowances require completion",
    }
    ct600_html = annual_accounts_ct600_preview_html(client, pack, ct600_preview, computation_preview)
    now = utc_now_iso()
    common_validation = {
        "internal_structure_checked": True,
        "taxonomy_selected": True,
        "period_valid": True,
        "external_schema_validation": False,
        "hmrc_local_test_service": False,
        "companies_house_test_validation": False,
        "submission_ready": False,
    }
    output_rows = [
        {
            "id": new_id(),
            "client_id": client_id,
            "pack_id": pack_id,
            "snapshot_id": snapshot_id,
            "output_type": "companies_house_accounts_preview",
            "format": "html",
            "status": "draft_review",
            "content_text": ixbrl_html,
            "metadata_json": json_compact({
                "filename": f"{annual_accounts_filename_slug(client.get('business_name'))}-{pack.get('period_to')}-accounts-draft.html",
                "taxonomy": taxonomy["accounts"],
                "reference_format": "Companies House statutory accounts iXBRL",
            }),
            "validation_json": json_compact(common_validation),
            "generated_by": user.get("id"),
            "created_at": now,
        },
        {
            "id": new_id(),
            "client_id": client_id,
            "pack_id": pack_id,
            "snapshot_id": snapshot_id,
            "output_type": "hmrc_ct600_computation_preview",
            "format": "html",
            "status": "draft_review",
            "content_text": ct600_html,
            "metadata_json": json_compact({
                "filename": f"{annual_accounts_filename_slug(client.get('business_name'))}-{pack.get('period_to')}-ct600-computation-draft.html",
                "taxonomy": taxonomy["computations"],
                "reference_format": "Printable CT600 Version 3 pages plus Corporation Tax computation",
            }),
            "validation_json": json_compact(common_validation),
            "generated_by": user.get("id"),
            "created_at": now,
        },
    ]
    for row in output_rows:
        await session.execute(insert(accounting_annual_accounts_outputs).values(**row))
    await add_accounting_audit(
        session,
        client_id,
        user.get("id"),
        "annual_accounts_preview_package_generated",
        "annual_accounts_pack",
        pack_id,
        {"output_ids": [row["id"] for row in output_rows], "snapshot_id": snapshot_id},
    )
    await session.commit()
    return {
        "status": "draft_review",
        "message": "Draft review artefacts generated. External schema and destination validation are still required.",
        "outputs": [
            {
                "id": row["id"],
                "output_type": row["output_type"],
                "format": row["format"],
                "filename": annual_accounts_json(row["metadata_json"], {}).get("filename"),
            }
            for row in output_rows
        ],
    }


@api.get("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}/ct600.pdf")
async def download_native_fillable_ct600(
    client_id: str,
    pack_id: str,
    read_only: bool = False,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    pack = await annual_accounts_pack_or_404(session, client_id, pack_id)
    workspace = await year_end_accounts_workspace(session, client, user)
    if str((workspace.get("active_pack") or {}).get("id")) != str(pack_id):
        raise HTTPException(status_code=409, detail="Select this accounts pack before generating its CT600.")
    form = (workspace.get("hmrc") or {}).get("ct600_form") or {}
    try:
        content = ct600_fillable_pdf_bytes(form, read_only=read_only)
    except FileNotFoundError as error:
        raise HTTPException(status_code=500, detail=str(error)) from error
    filename = (
        f"{annual_accounts_filename_slug(client.get('business_name'))}-"
        f"{pack.get('period_to') or 'period'}-CT600-2026-fillable.pdf"
    )
    return Response(
        content=content,
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@api.get("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}/self-assessment/{form_code}.pdf")
async def download_native_self_assessment_form(
    client_id: str,
    pack_id: str,
    form_code: str,
    read_only: bool = True,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    pack = await annual_accounts_pack_or_404(session, client_id, pack_id)
    workspace = await year_end_accounts_workspace(session, client, user, selected_pack_id=pack_id)
    form = (workspace.get("hmrc") or {}).get("self_assessment_form")
    if not form:
        raise HTTPException(status_code=409, detail="This accounts pack does not use the Self Assessment workflow.")
    package = system_pdf_form_package(form_code)
    if not package or not package.get("available"):
        raise HTTPException(
            status_code=409,
            detail=f"{form_code} has not yet been exported as a system package from PDF Editor and Viewer.",
        )
    requested_code = str(form_code or "").upper()
    allowed = {
        str(row.get("form_code") or "").upper()
        for row in self_assessment_system_form_status(form)
    }
    if requested_code not in allowed:
        raise HTTPException(status_code=409, detail=f"{form_code} is not selected for this tax return.")
    try:
        content = fill_system_pdf_package(
            package,
            self_assessment_system_form_values(form),
            read_only=read_only,
        )
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    filename = (
        f"{annual_accounts_filename_slug(client.get('business_name'))}-"
        f"{pack.get('period_to') or 'period'}-{requested_code}.pdf"
    )
    return Response(
        content=content,
        media_type="application/pdf",
        headers={"Content-Disposition": f'inline; filename="{filename}"'},
    )


