@api.post("/admin/accounting/clients/{client_id}/year-end-accounts/packs/{pack_id}/action")
async def action_year_end_accounts_pack(
    client_id: str,
    pack_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    pack = await annual_accounts_pack_or_404(session, client_id, pack_id)
    action = str(payload.get("action") or "").strip().lower()
    now = utc_now_iso()
    if action == "submit_for_review":
        if not pack.get("contents_json") or not annual_accounts_json(pack.get("contents_json"), {}).get("snapshot_id"):
            raise HTTPException(status_code=409, detail="Create a Trial Balance snapshot before submitting the accounts for review.")
        values = {"status": "in_review", "updated_at": now}
    elif action == "approve":
        report = await financial_report_snapshot(session, client_id, str(pack.get("period_from") or ""), str(pack.get("period_to") or ""))
        issues = annual_accounts_pack_validation(pack, client, report.get("trial_balance_summary") or {}, {
            "turnover": report.get("profit_and_loss", {}).get("turnover"),
            "balance_sheet_total": report.get("balance_sheet", {}).get("assets"),
        })
        if issues:
            raise HTTPException(status_code=409, detail={"message": "Resolve all accounts approval checks.", "issues": issues})
        if not annual_accounts_json(pack.get("contents_json"), {}).get("snapshot_id"):
            raise HTTPException(status_code=409, detail="Create a Trial Balance snapshot before approval.")
        values = {
            "status": "approved",
            "locked_snapshot": True,
            "reviewed_by": pack.get("reviewed_by") or user.get("id"),
            "approved_by": user.get("id"),
            "signature_date": pack.get("signature_date") or now[:10],
            "updated_at": now,
        }
    elif action == "reopen":
        if pack.get("status") != "approved":
            raise HTTPException(status_code=409, detail="Only an approved accounts pack can be reopened.")
        values = {
            "status": "draft",
            "locked_snapshot": False,
            "version_number": int(pack.get("version_number") or 1) + 1,
            "approved_by": None,
            "updated_at": now,
        }
    else:
        raise HTTPException(status_code=400, detail="Action must be submit_for_review, approve, or reopen.")
    await session.execute(update(accounting_annual_accounts_packs).where(accounting_annual_accounts_packs.c.id == pack_id).values(**values))
    await add_accounting_audit(session, client_id, user.get("id"), f"annual_accounts_{action}", "annual_accounts_pack", pack_id, {"reason": payload.get("reason"), **values})
    await session.commit()
    return serialize_annual_accounts_pack({**pack, **values})


