@api.put("/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}")
async def update_ap_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ap_invoices, accounting_ap_invoice_lines))
    invoice = await get_ap_invoice_or_404(session, client_id, invoice_id)
    require_unpaid_invoice_editable(invoice, "Purchase invoice")
    ap_settings = await ensure_ap_settings(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    default_location_id, default_dimension_id = await validate_analytical_pair(
        session,
        client_id,
        payload.get("default_location_id", invoice.get("default_location_id")),
        payload.get("default_dimension_id", invoice.get("default_dimension_id")),
    )
    supplier = await get_ap_supplier_or_404(session, client_id, str(payload.get("supplier_id") or invoice.get("supplier_id")))
    invoice_number = str(payload.get("invoice_number") or payload.get("bill_number") or invoice.get("invoice_number") or "").strip()
    if not invoice_number:
        raise HTTPException(status_code=400, detail="Invoice number is required.")
    duplicate = await one(
        session,
        select(accounting_ap_invoices).where(
            accounting_ap_invoices.c.client_id == client_id,
            accounting_ap_invoices.c.supplier_id == supplier["id"],
            accounting_ap_invoices.c.id != invoice_id,
            func.lower(accounting_ap_invoices.c.invoice_number) == invoice_number.lower(),
            accounting_ap_invoices.c.status != "void",
        ),
    )
    if duplicate and bool(ap_settings.get("duplicate_invoice_warning", True)):
        raise HTTPException(status_code=409, detail={"has_warning": True, "message": f"Possible duplicate: supplier already has invoice {invoice_number}.", "matches": [serialize_ap_invoice(duplicate)]})
    existing_lines = await many(session, select(accounting_ap_invoice_lines).where(accounting_ap_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ap_invoice_lines.c.line_number.asc()))
    raw_lines = payload.get("lines") if isinstance(payload.get("lines"), list) else existing_lines
    default_purchase_account = supplier.get("default_purchase_account") or settings_row.get("default_purchase_account") or "5000"
    header_vat_code = vat_code_value(first_present(payload, "vat_code", "tax_code", "tax_rate_code") or invoice.get("vat_code"))
    lines = [ap_line_values(line, default_purchase_account) for line in raw_lines]
    lines = await validate_document_line_analytics(session, client_id, lines)
    invoice_date = parse_date_or_today(payload.get("invoice_date") or payload.get("date") or invoice.get("invoice_date")).isoformat()
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, header_vat_code, lines, "Purchase invoice", invoice_date, "purchase")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ap_document_totals({**invoice, **payload}, lines, "Purchase invoice")
    due_date = parse_date_or_today(payload.get("due_date") or invoice.get("due_date")).isoformat()
    try:
        payment_terms_days = int(payload.get("payment_terms_days", invoice.get("payment_terms_days") or supplier.get("payment_terms_days") or 30) or 30)
    except (TypeError, ValueError):
        payment_terms_days = int(ap_settings.get("default_payment_terms_days") or 30)
    was_posted = bool(invoice.get("posted_journal_id")) and str(invoice.get("status") or "").lower() == "posted"
    status = str(payload.get("status") or invoice.get("status") or "draft").strip().lower()
    if status not in AP_EDITABLE_STATUSES:
        status = invoice.get("status")
    if was_posted:
        await reverse_native_journal(session, client_id, str(invoice.get("posted_journal_id")), "ap_invoice", invoice_id, user.get("id"))
        status = "approved"
    now = utc_now_iso()
    values = {
        "supplier_id": supplier["id"],
        "contact_id": supplier.get("contact_id"),
        "invoice_number": invoice_number,
        "reference": str(payload.get("reference", invoice.get("reference") or "") or "").strip(),
        "invoice_date": invoice_date,
        "due_date": due_date,
        "payment_terms_days": payment_terms_days,
        "currency": str(payload.get("currency", invoice.get("currency") or "GBP") or "GBP").strip().upper()[:8],
        "status": status,
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "posted_journal_id": None if was_posted else invoice.get("posted_journal_id"),
        "description": str(payload.get("description", invoice.get("description") or "") or "").strip(),
        "attachment_path": str(payload.get("attachment_path", invoice.get("attachment_path") or "") or "").strip(),
        "vat_code": header_vat_code,
        "original_filename": str(payload.get("original_filename", invoice.get("original_filename") or "") or "").strip()[:255],
        "outstanding_amount": totals["gross_amount"],
        "updated_at": now,
        **totals,
    }
    await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice_id).values(**values))
    await session.execute(delete(accounting_ap_invoice_lines).where(accounting_ap_invoice_lines.c.invoice_id == invoice_id))
    for index, line in enumerate(lines, start=1):
        await session.execute(insert(accounting_ap_invoice_lines).values(id=new_id(), client_id=client_id, invoice_id=invoice_id, line_number=index, created_at=now, updated_at=now, **line))
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_updated", "accounts_payable", invoice_id, {"status": status})
    if was_posted:
        await session.flush()
        await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_reposted_after_edit", "accounts_payable", invoice_id, {"original_journal_id": invoice.get("posted_journal_id")})
        return await post_ap_invoice(client_id, invoice_id, payload, user, session)
    await session.commit()
    updated = await get_ap_invoice_or_404(session, client_id, invoice_id)
    return ap_document_response("purchase_invoice", serialize_ap_invoice(updated, lines, supplier), lines)


async def ap_copy_invoice_payload(session: AsyncSession, client_id: str, original: dict, supplier: dict, lines: list[dict], today: date) -> dict:
    payment_terms_days = int(original.get("payment_terms_days") or supplier.get("payment_terms_days") or 30)
    copied_lines = [
        {
            key: line.get(key)
            for key in (
                "description",
                "nominal_account_code",
                "vat_code",
                "quantity",
                "unit_price",
                "discount_amount",
                "net_amount",
                "vat_amount",
                "gross_amount",
            )
        }
        for line in lines
    ]
    return {
        "supplier_id": original.get("supplier_id"),
        "invoice_number": await next_ap_invoice_number(session, client_id),
        "reference": original.get("reference") or "",
        "invoice_date": today.isoformat(),
        "due_date": (today + timedelta(days=payment_terms_days)).isoformat(),
        "payment_terms_days": payment_terms_days,
        "currency": original.get("currency") or supplier.get("default_currency") or "GBP",
        "description": original.get("description") or "",
        "vat_code": original.get("vat_code") or "",
        "status": "awaiting_approval" if bool(ap_settings.get("approval_required", True)) else "approved",
        "lines": copied_lines,
        "source_submission_id": "",
        "attachment_path": "",
        "original_filename": "",
        "extracted_json": {},
    }


@api.post("/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}/copy")
async def copy_ap_invoice(
    client_id: str,
    invoice_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    original = await get_ap_invoice_or_404(session, client_id, invoice_id)
    supplier = await get_ap_supplier_or_404(session, client_id, str(original.get("supplier_id")))
    lines = await many(session, select(accounting_ap_invoice_lines).where(accounting_ap_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ap_invoice_lines.c.line_number.asc()))
    payload = await ap_copy_invoice_payload(session, client_id, original, supplier, lines, datetime.now(timezone.utc).date())
    copied = await create_ap_invoice_record(session, client_id, payload, user.get("id"))
    copied_id = str(copied.get("id") or "")
    await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == copied_id).values(source_submission_id="", attachment_path="", original_filename="", extracted_json="{}", posted_journal_id=None, updated_at=utc_now_iso()))
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_copied", "accounts_payable", invoice_id, {"new_invoice_id": copied_id})
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_created_from_copy", "accounts_payable", copied_id, {"source_invoice_id": invoice_id})
    await session.commit()
    ap_settings = await ensure_ap_settings(session, client_id)
    if not bool(ap_settings.get("approval_required", True)):
        return await post_ap_invoice(client_id, copied_id, {}, user, session)
    return await get_ap_invoice_detail(client_id, copied_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}/approve")
async def approve_ap_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ap_invoice_or_404(session, client_id, invoice_id)
    if invoice.get("status") in {"posted", "paid", "part_paid"}:
        raise HTTPException(status_code=400, detail="Posted invoices are already approved.")
    if invoice.get("status") not in {"awaiting_approval", "draft"}:
        raise HTTPException(status_code=400, detail="Purchase invoice is not awaiting approval.")
    now = utc_now_iso()
    await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice_id).values(status="approved", approved_by=user.get("id"), approved_at=now, updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_approved", "accounts_payable", invoice_id, {"previous_status": invoice.get("status")})
    await session.flush()
    return await post_ap_invoice(client_id, invoice_id, payload, user, session)


async def create_ap_payment_record(
    session: AsyncSession,
    client_id: str,
    payload: dict,
    actor_id: Optional[str],
) -> dict:
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding supplier payments.")
    supplier = await get_ap_supplier_or_404(session, client_id, str(payload.get("supplier_id") or ""))
    default_location_id, default_dimension_id = await analytical_defaults_from_payload(session, client_id, payload)
    amount = money(payload.get("amount") or payload.get("amount_paid") or payload.get("payment_amount"))
    if amount == 0:
        raise HTTPException(status_code=400, detail="Payment amount must not be zero. Use a negative amount for a supplier refund.")
    posting_amount = abs(amount)
    is_refund = amount < 0
    settings_row = await ensure_accounting_settings(session, client_id)
    ap_settings = await ensure_ap_settings(session, client_id)
    accounts = await ensure_native_accounting_client(session, client_id)
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == supplier.get("contact_id")))
    bank_account_code = str(payload.get("bank_account_code") or "").strip()
    if not bank_account_code:
        raise HTTPException(status_code=400, detail="Bank account is required before posting a supplier payment.")
    bank = require_native_bank_account(accounts, bank_account_code)
    creditors = find_native_account(accounts, settings_row.get("default_creditors_control_account"), "2000")
    payment_date = parse_date_or_today(payload.get("payment_date")).isoformat()
    reference = str(payload.get("reference") or f"Payment {payment_date}").strip()
    payment_id = str(payload.get("_payment_id") or new_id())
    now = utc_now_iso()
    if bool(ap_settings.get("approval_required", True)) and not bool(payload.get("_approved")):
        row = {"id": payment_id, "client_id": client_id, "supplier_id": supplier["id"], "contact_id": supplier.get("contact_id"), "payment_date": payment_date, "bank_account_code": bank_account_code, "payment_method": str(payload.get("payment_method") or "Bank Transfer").strip(), "reference": reference, "amount": money_str(amount), "currency": str(payload.get("currency") or "GBP").strip().upper()[:8], "status": "awaiting_approval", "posted_journal_id": None, "bank_transaction_id": str(payload.get("bank_transaction_id") or "").strip() or None, "default_location_id": default_location_id, "default_dimension_id": default_dimension_id, "attachment_path": str(payload.get("attachment_path") or "").strip(), "original_filename": str(payload.get("original_filename") or "").strip()[:255], "created_at": now, "updated_at": now}
        await session.execute(insert(accounting_ap_payments).values(**row))
        pending_allocations = []
        for requested in payload.get("allocations") or []:
            allocation = {"id": new_id(), "client_id": client_id, "payment_id": payment_id, "invoice_id": requested.get("invoice_id"), "credit_note_id": requested.get("credit_note_id"), "amount": money_str(money(requested.get("amount"))), "created_at": now}
            await session.execute(insert(accounting_ap_payment_allocations).values(**allocation)); pending_allocations.append(allocation)
        await add_accounting_audit(session, client_id, actor_id, "supplier_payment_created", "accounts_payable", payment_id, {"status": "awaiting_approval", "amount": money_str(amount)})
        return {"payment": serialize_ap_payment(row, pending_allocations, supplier), "allocations": pending_allocations, "journal": {}, "unallocated_amount": money_str(posting_amount)}
    journal = await post_native_journal(
        session,
        client_id=client_id,
        source_type="ap_payment",
        source_id="pending",
        entry_date=payment_date,
        reference=reference,
        description=f"Supplier {'refund' if is_refund else 'payment'} {supplier.get('trading_name') or contact.get('name')}",
        lines=[
            {"account": creditors, "contact": contact, "debit": money_str(posting_amount) if not is_refund else "0.00", "credit": money_str(posting_amount) if is_refund else "0.00", "description": reference},
            {"account": bank, "contact": contact, "debit": money_str(posting_amount) if is_refund else "0.00", "credit": money_str(posting_amount) if not is_refund else "0.00", "description": reference},
        ],
        actor_id=actor_id,
        default_location_id=default_location_id,
        default_dimension_id=default_dimension_id,
    )
    row = {
        "id": payment_id,
        "client_id": client_id,
        "supplier_id": supplier["id"],
        "contact_id": supplier.get("contact_id"),
        "payment_date": payment_date,
        "bank_account_code": bank_account_code,
        "payment_method": str(payload.get("payment_method") or "Bank Transfer").strip(),
        "reference": reference,
        "amount": money_str(amount),
        "currency": str(payload.get("currency") or "GBP").strip().upper()[:8],
        "status": "posted",
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "posted_journal_id": journal.get("id"),
        "bank_transaction_id": str(payload.get("bank_transaction_id") or "").strip() or None,
        "attachment_path": str(payload.get("attachment_path") or "").strip(),
        "original_filename": str(payload.get("original_filename") or "").strip()[:255],
        "created_at": now,
        "updated_at": now,
    }
    await session.execute(insert(accounting_ap_payments).values(**row))
    remaining = posting_amount
    allocation_target = str(payload.get("allocation_target") or ("selected" if payload.get("allocations") else "on_account")).strip().lower()
    invoice_ids = [] if is_refund else [str(item.get("invoice_id")) for item in (payload.get("allocations") or []) if item.get("invoice_id")]
    if invoice_ids:
        invoices = await many(
            session,
            select(accounting_ap_invoices).where(
                accounting_ap_invoices.c.client_id == client_id,
                accounting_ap_invoices.c.supplier_id == supplier["id"],
                accounting_ap_invoices.c.id.in_(invoice_ids),
                accounting_ap_invoices.c.status.in_(["posted", "part_paid"]),
            ),
        )
    elif allocation_target == "oldest" and not is_refund:
        invoices = await many(
            session,
            select(accounting_ap_invoices)
            .where(accounting_ap_invoices.c.client_id == client_id, accounting_ap_invoices.c.supplier_id == supplier["id"], accounting_ap_invoices.c.status.in_(["posted", "part_paid"]), accounting_ap_invoices.c.outstanding_amount != "0.00")
            .order_by(accounting_ap_invoices.c.due_date.asc(), accounting_ap_invoices.c.invoice_date.asc()),
        )
    else:
        invoices = []
    allocation_by_invoice = {str(item.get("invoice_id")): money(item.get("amount")) for item in (payload.get("allocations") or []) if item.get("invoice_id")}
    allocations = []
    for invoice in invoices:
        if remaining <= 0:
            break
        existing_allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.invoice_id == invoice["id"]))
        outstanding = max(money(invoice.get("gross_amount")) - sum((money(row.get("amount")) for row in existing_allocations), Decimal("0.00")), Decimal("0.00"))
        if outstanding <= 0:
            continue
        desired = allocation_by_invoice.get(str(invoice["id"]), outstanding)
        allocate = min(remaining, outstanding, desired if desired > 0 else outstanding)
        if allocate <= 0:
            continue
        allocation = {"id": new_id(), "client_id": client_id, "payment_id": payment_id, "invoice_id": invoice["id"], "amount": money_str(allocate), "created_at": now}
        await session.execute(insert(accounting_ap_payment_allocations).values(**allocation))
        allocations.append(allocation)
        new_outstanding = outstanding - allocate
        new_status = "paid" if new_outstanding == 0 else "part_paid"
        await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice["id"]).values(outstanding_amount=money_str(new_outstanding), status=new_status, updated_at=now))
        remaining -= allocate
    await session.execute(update(accounting_journal_entries).where(accounting_journal_entries.c.id == journal.get("id")).values(source_id=payment_id))
    await add_accounting_audit(session, client_id, actor_id, "supplier_payment_posted", "accounts_payable", payment_id, {"journal_id": journal.get("id"), "amount": money_str(amount), "unallocated_amount": money_str(remaining)})
    return {"payment": serialize_ap_payment(row, allocations, supplier), "allocations": allocations, "journal": journal, "unallocated_amount": money_str(remaining)}


@api.post("/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}/post")
async def post_ap_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ap_invoice_or_404(session, client_id, invoice_id)
    if invoice.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Purchase invoice is already posted.")
    ap_settings = await ensure_ap_settings(session, client_id)
    if bool(ap_settings.get("approval_required", True)) and invoice.get("status") != "approved":
        raise HTTPException(status_code=400, detail="Approve this purchase invoice before posting.")
    if invoice.get("status") != "approved":
        raise HTTPException(status_code=400, detail="Purchase invoice cannot be posted from this status.")
    accounts = await ensure_native_accounting_client(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    supplier = await get_ap_supplier_or_404(session, client_id, str(invoice.get("supplier_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == supplier.get("contact_id")))
    lines = await many(session, select(accounting_ap_invoice_lines).where(accounting_ap_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ap_invoice_lines.c.line_number.asc()))
    await validate_native_vat_codes_for_document(session, client_id, invoice.get("vat_code"), lines, "Purchase invoice", invoice.get("invoice_date"), "purchase")
    validate_ap_document_totals(invoice, lines, "Purchase invoice")
    vat_context = await late_invoice_vat_context(session, client_id, str(invoice.get("invoice_date") or ""), invoice.get("vat_amount"))
    if vat_context and vat_context.get("requires_reopen"):
        raise HTTPException(status_code=409, detail={
            "code": "vat_period_locked",
            "message": "This invoice belongs to a locked VAT period that has not been closed. Reopen that period before posting.",
            "original_period": serialize_vat_period(vat_context["original_period"]),
        })
    if vat_context and not bool(payload.get("confirm_prior_period_vat_adjustment")):
        raise HTTPException(status_code=409, detail={
            "code": "prior_period_vat_adjustment_confirmation",
            "message": "The invoice date belongs to a closed VAT period. Create the recommended VAT adjustment automatically in the current open period?",
            "original_period": serialize_vat_period(vat_context["original_period"]),
            "reported_period": serialize_vat_period(vat_context["reported_period"]),
            "vat_amount": money_str(money(invoice.get("vat_amount"))),
        })
    journal_lines = []
    for line in lines:
        amount = money(line.get("net_amount"))
        if amount:
            expense_account = find_native_account(accounts, line.get("nominal_account_code"), supplier.get("default_purchase_account") or settings_row.get("default_purchase_account") or "5000")
            journal_lines.append({"account": expense_account, "contact": contact, "debit": money_str(amount), "credit": "0.00", "vat_code": line.get("vat_code"), "description": line.get("description"), "location_id": line.get("location_id"), "dimension_id": line.get("dimension_id")})
    vat_amount = money(invoice.get("vat_amount"))
    if vat_amount:
        vat_account = find_native_account(accounts, settings_row.get("default_vat_control_account"), "2200")
        journal_lines.append({"account": vat_account, "contact": contact, "debit": money_str(vat_amount), "credit": "0.00", "description": f"VAT on {invoice.get('invoice_number')}"})
    creditors = find_native_account(accounts, settings_row.get("default_creditors_control_account"), "2000")
    gross = money(invoice.get("gross_amount"))
    journal_lines.append({"account": creditors, "contact": contact, "debit": "0.00", "credit": money_str(gross), "description": invoice.get("invoice_number")})
    journal = await post_native_journal(
        session,
        client_id=client_id,
        source_type="ap_invoice",
        source_id=invoice_id,
        entry_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
        reference=invoice.get("invoice_number") or invoice_id,
        description=f"Purchase invoice {invoice.get('invoice_number')}",
        lines=journal_lines,
        actor_id=user.get("id"),
        default_location_id=invoice.get("default_location_id"),
        default_dimension_id=invoice.get("default_dimension_id"),
    )
    now = utc_now_iso()
    await session.execute(
        update(accounting_ap_invoices)
        .where(accounting_ap_invoices.c.id == invoice_id)
        .values(
            status="posted",
            posted_journal_id=journal.get("id"),
            posting_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
            vat_effective_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
            vat_treatment="prior_period_correction" if vat_context else "normal",
            original_vat_period_id=vat_context["original_period"].get("id") if vat_context else None,
            reported_vat_period_id=vat_context["reported_period"].get("id") if vat_context else None,
            posted_by=user.get("id"),
            posted_at=now,
            approved_by=invoice.get("approved_by") or user.get("id"),
            approved_at=invoice.get("approved_at") or now,
            updated_at=now,
        )
    )
    vat_adjustment = None
    if vat_context:
        vat_adjustment = await apply_confirmed_late_invoice_vat_adjustment(
            session, client_id, "ap_invoice", invoice_id, str(invoice.get("invoice_number") or invoice_id),
            str(invoice.get("vat_code") or ""), invoice.get("net_amount"), invoice.get("vat_amount"), invoice.get("gross_amount"),
            vat_context, user.get("id"), str(payload.get("prior_period_vat_adjustment_comment") or ""),
        )
    payment_result = None
    if bool(payload.get("mark_as_paid")):
        paid_amount = payload.get("amount_paid") or payload.get("payment_amount") or payload.get("amount")
        if paid_amount in (None, ""):
            raise HTTPException(status_code=400, detail="Payment amount is required when marking a purchase invoice as paid.")
        if not str(payload.get("payment_date") or "").strip():
            raise HTTPException(status_code=400, detail="Payment date is required when marking a purchase invoice as paid.")
        if not str(payload.get("bank_account_code") or "").strip():
            raise HTTPException(status_code=400, detail="Bank account is required when marking a purchase invoice as paid.")
        payment_result = await create_ap_payment_record(
            session,
            client_id,
            {
                "supplier_id": supplier["id"],
                "payment_date": payload.get("payment_date"),
                "bank_account_code": payload.get("bank_account_code"),
                "payment_method": payload.get("payment_method") or "Bank Transfer",
                "reference": payload.get("payment_reference") or payload.get("reference") or invoice.get("invoice_number"),
                "amount": paid_amount,
                "currency": payload.get("currency") or invoice.get("currency") or "GBP",
                "allocations": [{"invoice_id": invoice_id, "amount": paid_amount}],
            },
            user.get("id"),
        )
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_posted", "accounts_payable", invoice_id, {"journal_id": journal.get("id")})
    await session.commit()
    fresh_invoice = await get_ap_invoice_or_404(session, client_id, invoice_id)
    detail = await get_ap_invoice_detail(client_id, invoice_id, user, session)
    ledger = await get_ap_supplier_ledger(client_id, str(supplier["id"]), 1, 50, None, None, None, None, None, user, session)
    return {
        "ok": True,
        "document_type": "purchase_invoice",
        "destination": "accounts_payable",
        "invoice": serialize_ap_invoice(fresh_invoice, lines, supplier),
        "journal": journal,
        "payment": (payment_result or {}).get("payment"),
        "allocations": (payment_result or {}).get("allocations"),
        "ledger_effect": ap_ledger_effect("purchase_invoice"),
        "invoice_or_transaction": detail.get("invoice") or detail,
        "lines": detail.get("lines") or lines,
        "totals": detail.get("totals") or {},
        "ledger_impact": detail.get("ledger_effect") or ap_ledger_effect("purchase_invoice"),
        "source_document": detail.get("source_document") or {},
        "audit_trail": detail.get("audit_trail") or [],
        "status": "posted",
        "detail": detail,
        "ledger_summary": ledger.get("summary") or {},
        "vat_adjustment": serialize_vat_adjustment(vat_adjustment) if vat_adjustment else None,
    }


@api.post("/admin/accounting/clients/{client_id}/ap/invoices/{invoice_id}/void")
async def void_ap_invoice(
    client_id: str,
    invoice_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ap_invoice_or_404(session, client_id, invoice_id)
    if invoice.get("posted_journal_id") or invoice.get("status") in {"posted", "paid", "part_paid"}:
        raise HTTPException(status_code=400, detail="Posted purchase invoices cannot be voided. Post a credit note instead.")
    if invoice.get("status") == "void":
        return {"ok": True}
    now = utc_now_iso()
    await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice_id).values(status="void", outstanding_amount="0.00", updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "purchase_invoice_voided", "accounts_payable", invoice_id, {"previous_status": invoice.get("status")})
    await session.commit()
    return {"ok": True}


@api.post("/admin/accounting/clients/{client_id}/ap/credit-notes")
async def create_ap_credit_note(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ap_credit_notes, accounting_ap_credit_note_lines))
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding supplier credit notes.")
    ap_settings = await ensure_ap_settings(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    default_location_id, default_dimension_id = await analytical_defaults_from_payload(session, client_id, payload)
    supplier = await get_ap_supplier_or_404(session, client_id, str(payload.get("supplier_id") or ""))
    number = str(payload.get("credit_note_number") or payload.get("number") or "").strip()
    if not number:
        raise HTTPException(status_code=400, detail="Credit note number is required.")
    duplicate = await one(
        session,
        select(accounting_ap_credit_notes).where(
            accounting_ap_credit_notes.c.client_id == client_id,
            accounting_ap_credit_notes.c.supplier_id == supplier["id"],
            func.lower(accounting_ap_credit_notes.c.credit_note_number) == number.lower(),
            accounting_ap_credit_notes.c.status != "void",
        ),
    )
    if duplicate and bool(ap_settings.get("duplicate_invoice_warning", True)):
        raise HTTPException(status_code=409, detail={"has_warning": True, "message": f"Possible duplicate: supplier already has credit note {number}.", "matches": [serialize_ap_credit_note(duplicate)]})
    credit_date = parse_date_or_today(payload.get("credit_note_date") or payload.get("date")).isoformat()
    lines = [ap_line_values(line, supplier.get("default_purchase_account") or settings_row.get("default_purchase_account") or "5000") for line in (payload.get("lines") or [])]
    if not lines:
        lines = [ap_line_values({"description": payload.get("description") or number, "net_amount": payload.get("net_amount"), "vat_amount": payload.get("vat_amount"), "gross_amount": payload.get("gross_amount"), "vat_code": payload.get("vat_code")}, supplier.get("default_purchase_account") or "5000")]
    lines = await validate_document_line_analytics(session, client_id, lines)
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, payload.get("vat_code"), lines, "Supplier credit note", credit_date, "purchase")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ap_document_totals(payload, lines, "Supplier credit note")
    now = utc_now_iso()
    row = {
        "id": new_id(),
        "client_id": client_id,
        "supplier_id": supplier["id"],
        "contact_id": supplier.get("contact_id"),
        "credit_note_number": number,
        "reference": str(payload.get("reference") or "").strip(),
        "credit_note_date": credit_date,
        "currency": str(payload.get("currency") or "GBP").strip().upper()[:8],
        "status": "draft",
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "description": str(payload.get("description") or "").strip(),
        "vat_code": header_vat_code,
        **totals,
        "unallocated_amount": totals["gross_amount"],
        "attachment_path": str(payload.get("attachment_path") or "").strip(),
        "created_at": now,
        "updated_at": now,
    }
    await session.execute(insert(accounting_ap_credit_notes).values(**row))
    for index, line in enumerate(lines, start=1):
        cleaned = dict(line)
        cleaned.pop("discount_amount", None)
        await session.execute(insert(accounting_ap_credit_note_lines).values(id=new_id(), client_id=client_id, credit_note_id=row["id"], line_number=index, created_at=now, updated_at=now, **cleaned))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_credit_note_created", "accounts_payable", row["id"], {"credit_note_number": number})
    await session.commit()
    if not bool(ap_settings.get("approval_required", True)):
        return await post_ap_credit_note(client_id, row["id"], user, session)
    return await get_ap_credit_note_detail(client_id, row["id"], user, session)


@api.get("/admin/accounting/clients/{client_id}/ap/credit-notes/{credit_note_id}")
async def get_ap_credit_note_detail(
    client_id: str,
    credit_note_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ap_credit_notes, accounting_ap_credit_note_lines))
    credit = await one(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Supplier credit note not found.")
    supplier = await get_ap_supplier_or_404(session, client_id, str(credit.get("supplier_id")))
    lines = await many(session, select(accounting_ap_credit_note_lines).where(accounting_ap_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ap_credit_note_lines.c.line_number.asc()))
    journal = await one(session, select(accounting_journal_entries).where(accounting_journal_entries.c.id == credit.get("posted_journal_id"))) if credit.get("posted_journal_id") else None
    item = serialize_ap_credit_note(credit, lines, supplier)
    item["view_only"] = credit.get("status") not in AP_EDITABLE_STATUSES
    item["journal"] = journal or {}
    item["allocation_status"] = "allocated" if money(credit.get("unallocated_amount")) == Decimal("0.00") else "unallocated"
    item["audit_trail"] = await ap_audit_events(session, client_id, credit_note_id)
    return ap_document_response("supplier_credit_note", item, lines)


@api.put("/admin/accounting/clients/{client_id}/ap/credit-notes/{credit_note_id}")
async def update_ap_credit_note(
    client_id: str,
    credit_note_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ap_credit_notes, accounting_ap_credit_note_lines))
    credit = await one(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Supplier credit note not found.")
    require_ap_editable(credit, "Supplier credit note")
    ap_settings = await ensure_ap_settings(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    default_location_id, default_dimension_id = await validate_analytical_pair(
        session,
        client_id,
        payload.get("default_location_id", credit.get("default_location_id")),
        payload.get("default_dimension_id", credit.get("default_dimension_id")),
    )
    supplier = await get_ap_supplier_or_404(session, client_id, str(payload.get("supplier_id") or credit.get("supplier_id")))
    number = str(payload.get("credit_note_number") or payload.get("number") or credit.get("credit_note_number") or "").strip()
    if not number:
        raise HTTPException(status_code=400, detail="Credit note number is required.")
    duplicate = await one(
        session,
        select(accounting_ap_credit_notes).where(
            accounting_ap_credit_notes.c.client_id == client_id,
            accounting_ap_credit_notes.c.supplier_id == supplier["id"],
            accounting_ap_credit_notes.c.id != credit_note_id,
            func.lower(accounting_ap_credit_notes.c.credit_note_number) == number.lower(),
            accounting_ap_credit_notes.c.status != "void",
        ),
    )
    if duplicate and bool(ap_settings.get("duplicate_invoice_warning", True)):
        raise HTTPException(status_code=409, detail={"has_warning": True, "message": f"Possible duplicate: supplier already has credit note {number}.", "matches": [serialize_ap_credit_note(duplicate)]})
    existing_lines = await many(session, select(accounting_ap_credit_note_lines).where(accounting_ap_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ap_credit_note_lines.c.line_number.asc()))
    raw_lines = payload.get("lines") if isinstance(payload.get("lines"), list) else existing_lines
    lines = [ap_line_values(line, supplier.get("default_purchase_account") or settings_row.get("default_purchase_account") or "5000") for line in raw_lines]
    lines = await validate_document_line_analytics(session, client_id, lines)
    effective_credit_date = parse_date_or_today(payload.get("credit_note_date") or payload.get("date") or credit.get("credit_note_date")).isoformat()
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, payload.get("vat_code") or credit.get("vat_code"), lines, "Supplier credit note", effective_credit_date, "purchase")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ap_document_totals({**credit, **payload}, lines, "Supplier credit note")
    now = utc_now_iso()
    values = {
        "supplier_id": supplier["id"],
        "contact_id": supplier.get("contact_id"),
        "credit_note_number": number,
        "reference": str(payload.get("reference", credit.get("reference") or "") or "").strip(),
        "credit_note_date": parse_date_or_today(payload.get("credit_note_date") or payload.get("date") or credit.get("credit_note_date")).isoformat(),
        "currency": str(payload.get("currency", credit.get("currency") or "GBP") or "GBP").strip().upper()[:8],
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "description": str(payload.get("description", credit.get("description") or "") or "").strip(),
        "attachment_path": str(payload.get("attachment_path", credit.get("attachment_path") or "") or "").strip(),
        "vat_code": header_vat_code,
        "unallocated_amount": totals["gross_amount"],
        "updated_at": now,
        **totals,
    }
    await session.execute(update(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.id == credit_note_id).values(**values))
    await session.execute(delete(accounting_ap_credit_note_lines).where(accounting_ap_credit_note_lines.c.credit_note_id == credit_note_id))
    for index, line in enumerate(lines, start=1):
        cleaned = dict(line)
        cleaned.pop("discount_amount", None)
        await session.execute(insert(accounting_ap_credit_note_lines).values(id=new_id(), client_id=client_id, credit_note_id=credit_note_id, line_number=index, created_at=now, updated_at=now, **cleaned))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_credit_note_updated", "accounts_payable", credit_note_id, {"status": credit.get("status")})
    await session.commit()
    updated = await one(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.id == credit_note_id))
    return ap_document_response("supplier_credit_note", serialize_ap_credit_note(updated, lines, supplier), lines)


@api.post("/admin/accounting/clients/{client_id}/ap/credit-notes/{credit_note_id}/post")
async def post_ap_credit_note(
    client_id: str,
    credit_note_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    credit = await one(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Supplier credit note not found.")
    if credit.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Supplier credit note is already posted.")
    if credit.get("status") not in AP_EDITABLE_STATUSES | {"approved"}:
        raise HTTPException(status_code=400, detail="Supplier credit note cannot be posted from this status.")
    accounts = await ensure_native_accounting_client(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    supplier = await get_ap_supplier_or_404(session, client_id, str(credit.get("supplier_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == supplier.get("contact_id")))
    lines = await many(session, select(accounting_ap_credit_note_lines).where(accounting_ap_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ap_credit_note_lines.c.line_number.asc()))
    await validate_native_vat_codes_for_document(session, client_id, credit.get("vat_code"), lines, "Supplier credit note", credit.get("credit_note_date"), "purchase")
    validate_ap_document_totals(credit, lines, "Supplier credit note")
    creditors = find_native_account(accounts, settings_row.get("default_creditors_control_account"), "2000")
    journal_lines = [{"account": creditors, "contact": contact, "debit": money_str(money(credit.get("gross_amount"))), "credit": "0.00", "description": credit.get("credit_note_number")}]
    for line in lines:
        amount = money(line.get("net_amount"))
        if amount:
            expense_account = find_native_account(accounts, line.get("nominal_account_code"), supplier.get("default_purchase_account") or settings_row.get("default_purchase_account") or "5000")
            journal_lines.append({"account": expense_account, "contact": contact, "debit": "0.00", "credit": money_str(amount), "vat_code": line.get("vat_code"), "description": line.get("description"), "location_id": line.get("location_id"), "dimension_id": line.get("dimension_id")})
    vat_amount = money(credit.get("vat_amount"))
    if vat_amount:
        vat_account = find_native_account(accounts, settings_row.get("default_vat_control_account"), "2200")
        journal_lines.append({"account": vat_account, "contact": contact, "debit": "0.00", "credit": money_str(vat_amount), "description": f"VAT credit {credit.get('credit_note_number')}"})
    journal = await post_native_journal(
        session,
        client_id=client_id,
        source_type="ap_credit_note",
        source_id=credit_note_id,
        entry_date=credit.get("credit_note_date"),
        reference=credit.get("credit_note_number") or credit_note_id,
        description=f"Supplier credit note {credit.get('credit_note_number')}",
        lines=journal_lines,
        actor_id=user.get("id"),
        default_location_id=credit.get("default_location_id"),
        default_dimension_id=credit.get("default_dimension_id"),
    )
    now = utc_now_iso()
    await session.execute(update(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.id == credit_note_id).values(status="posted", posted_journal_id=journal.get("id"), posted_by=user.get("id"), posted_at=now, updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_credit_note_posted", "accounts_payable", credit_note_id, {"journal_id": journal.get("id")})
    await session.commit()
    return await get_ap_credit_note_detail(client_id, credit_note_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ap/payments")
async def create_ap_payment(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    result = await create_ap_payment_record(session, client_id, payload, user.get("id"))
    await session.commit()
    payment = result["payment"]
    return {
        "ok": True,
        "transaction_type": "supplier_payment",
        "document_type": "supplier_payment",
        "destination": "accounts_payable",
        "payment": payment,
        "invoice_or_transaction": payment,
        "lines": result["allocations"],
        "totals": {"amount": payment.get("amount"), "unallocated_amount": result.get("unallocated_amount")},
        "allocations": result["allocations"],
        "journal": result["journal"],
        "ledger_effect": ap_ledger_effect("supplier_payment"),
        "source_document": {"status": "none", "missing": False},
        "audit_trail": [],
        "status": payment.get("status"),
    }


@api.get("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}")
async def get_ap_payment_detail(
    client_id: str,
    payment_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment:
        raise HTTPException(status_code=404, detail="Supplier payment not found.")
    supplier = await get_ap_supplier_or_404(session, client_id, str(payment.get("supplier_id")))
    allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.payment_id == payment_id))
    journal = await one(session, select(accounting_journal_entries).where(accounting_journal_entries.c.id == payment.get("posted_journal_id"))) if payment.get("posted_journal_id") else None
    item = serialize_ap_payment(payment, allocations, supplier)
    item["view_only"] = True
    item["journal"] = journal or {}
    item["audit_trail"] = await ap_audit_events(session, client_id, payment_id)
    return {
        "ok": True,
        "transaction_type": "supplier_payment",
        "document_type": "supplier_payment",
        "destination": "accounts_payable",
        "payment": item,
        "invoice_or_transaction": item,
        "lines": allocations,
        "totals": {"amount": item.get("amount")},
        "allocations": allocations,
        "journal": journal or {},
        "ledger_effect": ap_ledger_effect("supplier_payment"),
        "source_document": {"status": "none", "missing": False},
        "audit_trail": item["audit_trail"],
        "status": item.get("status"),
    }


@api.post("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}/approve")
async def approve_ap_payment(client_id: str, payment_id: str, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment:
        raise HTTPException(status_code=404, detail="Supplier payment not found.")
    if payment.get("status") != "awaiting_approval" or payment.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Only awaiting-approval supplier payments can be approved.")
    allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.payment_id == payment_id))
    await session.execute(delete(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.payment_id == payment_id))
    await session.execute(delete(accounting_ap_payments).where(accounting_ap_payments.c.id == payment_id))
    result = await create_ap_payment_record(session, client_id, {**payment, "_payment_id": payment_id, "_approved": True, "allocations": allocations}, user.get("id"))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_payment_approved", "accounts_payable", payment_id, {"journal_id": result.get("journal", {}).get("id")})
    await session.commit()
    return await get_ap_payment_detail(client_id, payment_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}/allocations/{allocation_id}/unallocate")
async def unallocate_ap_payment(
    client_id: str,
    payment_id: str,
    allocation_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment:
        raise HTTPException(status_code=404, detail="Supplier payment not found.")
    allocation = await one(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.payment_id == payment_id, accounting_ap_payment_allocations.c.id == allocation_id))
    if not allocation:
        raise HTTPException(status_code=404, detail="Payment allocation not found.")
    invoice_id = allocation.get("invoice_id")
    if invoice_id:
        invoice = await get_ap_invoice_or_404(session, client_id, str(invoice_id))
        remaining_allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.invoice_id == invoice_id, accounting_ap_payment_allocations.c.id != allocation_id))
        remaining_credit_allocations = await many(session, select(accounting_ap_credit_allocations).where(accounting_ap_credit_allocations.c.client_id == client_id, accounting_ap_credit_allocations.c.invoice_id == invoice_id))
        values = invoice_allocation_values(invoice, sum((money(row.get("amount")) for row in [*remaining_allocations, *remaining_credit_allocations]), Decimal("0.00")))
        await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice_id).values(outstanding_amount=values["invoice_balance"], status=values["status"], updated_at=utc_now_iso()))
    credit_note_id = allocation.get("credit_note_id")
    if credit_note_id:
        credit = await one(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.id == credit_note_id))
        if credit:
            remaining_allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.credit_note_id == credit_note_id, accounting_ap_payment_allocations.c.id != allocation_id))
            remaining = max(money(credit.get("gross_amount")) - sum((money(row.get("amount")) for row in remaining_allocations), Decimal("0.00")), Decimal("0.00"))
            await session.execute(update(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.id == credit_note_id).values(unallocated_amount=money_str(remaining), status="posted" if remaining == money(credit.get("gross_amount")) else "part_paid" if remaining > 0 else "paid", updated_at=utc_now_iso()))
    await session.execute(delete(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.id == allocation_id))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_payment_unallocated", "accounts_payable", payment_id, {"allocation_id": allocation_id, "invoice_id": invoice_id, "amount": allocation.get("amount"), "bank_journal_changed": False})
    await session.commit()
    return await get_ap_payment_detail(client_id, payment_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}/allocations")
async def allocate_ap_payment(
    client_id: str,
    payment_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment or payment.get("status") not in {"posted", "part_allocated", "allocated"}:
        raise HTTPException(status_code=404, detail="Posted supplier payment not found.")
    payment_allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.payment_id == payment_id))
    is_refund = money(payment.get("amount")) < 0
    payment_remaining = max(abs(money(payment.get("amount"))) - sum((money(row.get("amount")) for row in payment_allocations), Decimal("0.00")), Decimal("0.00"))
    requested_rows = payload.get("allocations") if isinstance(payload.get("allocations"), list) else [payload]
    requested_by_invoice: dict[str, Decimal] = {}
    for requested in requested_rows:
        invoice_id = str((requested or {}).get("invoice_id") or "")
        amount = money((requested or {}).get("amount"))
        if not invoice_id or amount <= 0:
            raise HTTPException(status_code=400, detail="Every allocation requires an invoice and an amount greater than zero.")
        requested_by_invoice[invoice_id] = requested_by_invoice.get(invoice_id, Decimal("0.00")) + amount
    if sum(requested_by_invoice.values(), Decimal("0.00")) > payment_remaining:
        raise HTTPException(status_code=400, detail="The requested allocations exceed the unallocated supplier payment balance.")
    target_table = accounting_ap_credit_notes if is_refund else accounting_ap_invoices
    invoices = await many(session, select(target_table).where(target_table.c.client_id == client_id, target_table.c.id.in_(list(requested_by_invoice))))
    invoice_by_id = {str(invoice["id"]): invoice for invoice in invoices}
    if len(invoice_by_id) != len(requested_by_invoice):
        raise HTTPException(status_code=404, detail="One or more purchase invoices could not be found.")
    now = utc_now_iso()
    created = []
    for invoice_id, amount in requested_by_invoice.items():
        invoice = invoice_by_id[invoice_id]
        if str(invoice.get("supplier_id")) != str(payment.get("supplier_id")):
            raise HTTPException(status_code=400, detail="Every allocation document must belong to the payment supplier.")
        target_column = accounting_ap_payment_allocations.c.credit_note_id if is_refund else accounting_ap_payment_allocations.c.invoice_id
        invoice_allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, target_column == invoice_id))
        invoice_remaining = max(money(invoice.get("gross_amount")) - sum((money(row.get("amount")) for row in invoice_allocations), Decimal("0.00")), Decimal("0.00"))
        if amount > invoice_remaining:
            raise HTTPException(status_code=400, detail=f"Allocation for {invoice.get('invoice_number') or invoice_id} exceeds its outstanding balance.")
        allocation = {"id": new_id(), "client_id": client_id, "payment_id": payment_id, "invoice_id": None if is_refund else invoice_id, "credit_note_id": invoice_id if is_refund else None, "amount": money_str(amount), "created_at": now}
        await session.execute(insert(accounting_ap_payment_allocations).values(**allocation))
        created.append(allocation)
        new_outstanding = invoice_remaining - amount
        if is_refund:
            await session.execute(update(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.id == invoice_id).values(unallocated_amount=money_str(new_outstanding), status="paid" if new_outstanding == 0 else "part_paid", updated_at=now))
        else:
            await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == invoice_id).values(outstanding_amount=money_str(new_outstanding), status="paid" if new_outstanding == 0 else "part_paid", updated_at=now))
        await add_accounting_audit(session, client_id, user.get("id"), "supplier_payment_allocation_created", "accounts_payable", payment_id, {"invoice_id": invoice_id, "amount": money_str(amount), "bank_journal_changed": False})
    await ensure_current_cash_vat_corrections(session, client_id)
    await session.commit()
    response = await get_ap_payment_detail(client_id, payment_id, user, session)
    response["created_allocations"] = created
    return response


@api.get("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}/allocation-options")
async def get_ap_payment_allocation_options(
    client_id: str,
    payment_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment:
        raise HTTPException(status_code=404, detail="Supplier payment not found.")
    allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.client_id == client_id, accounting_ap_payment_allocations.c.payment_id == payment_id).order_by(accounting_ap_payment_allocations.c.created_at.asc()))
    invoice_ids = [str(row.get("invoice_id")) for row in allocations if row.get("invoice_id")]
    credit_note_ids = [str(row.get("credit_note_id")) for row in allocations if row.get("credit_note_id")]
    existing_invoices = await many(session, select(accounting_ap_invoices).where(accounting_ap_invoices.c.client_id == client_id, accounting_ap_invoices.c.id.in_(invoice_ids))) if invoice_ids else []
    existing_credits = await many(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.id.in_(credit_note_ids))) if credit_note_ids else []
    existing_by_id = {str(row["id"]): row for row in existing_invoices}
    existing_by_id.update({str(row["id"]): row for row in existing_credits})
    is_refund = money(payment.get("amount")) < 0
    if is_refund:
        open_invoices = await many(session, select(accounting_ap_credit_notes).where(accounting_ap_credit_notes.c.client_id == client_id, accounting_ap_credit_notes.c.supplier_id == payment.get("supplier_id"), accounting_ap_credit_notes.c.status.in_(["posted", "part_paid"]), accounting_ap_credit_notes.c.unallocated_amount != "0.00").order_by(accounting_ap_credit_notes.c.credit_note_date.asc()))
    else:
        open_invoices = await many(session, select(accounting_ap_invoices).where(
            accounting_ap_invoices.c.client_id == client_id,
            accounting_ap_invoices.c.supplier_id == payment.get("supplier_id"),
            accounting_ap_invoices.c.status.in_(["posted", "part_paid"]),
            accounting_ap_invoices.c.outstanding_amount != "0.00",
        ).order_by(accounting_ap_invoices.c.invoice_date.asc(), accounting_ap_invoices.c.invoice_number.asc()))
    allocated = sum((money(row.get("amount")) for row in allocations), Decimal("0.00"))
    return {
        "payment": {
            "id": payment_id,
            "reference": payment.get("reference"),
            "date": payment.get("payment_date"),
            "amount": money_str(abs(money(payment.get("amount")))),
            "allocated_amount": money_str(allocated),
            "unallocated_amount": money_str(max(abs(money(payment.get("amount"))) - allocated, Decimal("0.00"))),
            "is_refund": is_refund,
        },
        "existing_allocations": [{
            **dict(row),
            "invoice_number": (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("invoice_number") or (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("credit_note_number"),
            "invoice_date": (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("invoice_date") or (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("credit_note_date"),
        } for row in allocations],
        "invoices": [{
            "id": row.get("id"),
            "invoice_number": row.get("invoice_number") or row.get("credit_note_number"),
            "invoice_date": row.get("invoice_date") or row.get("credit_note_date"),
            "due_date": row.get("due_date"),
            "gross_amount": money_str(money(row.get("gross_amount"))),
            "outstanding_amount": money_str(money(row.get("unallocated_amount") if is_refund else row.get("outstanding_amount"))),
            "status": row.get("status"),
        } for row in open_invoices],
    }


@api.post("/admin/accounting/clients/{client_id}/ap/payments/{payment_id}/reverse")
async def reverse_ap_payment(client_id: str, payment_id: str, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    payment = await one(session, select(accounting_ap_payments).where(accounting_ap_payments.c.client_id == client_id, accounting_ap_payments.c.id == payment_id))
    if not payment:
        raise HTTPException(status_code=404, detail="Supplier payment not found.")
    if payment.get("status") == "reversed":
        raise HTTPException(status_code=400, detail="Supplier payment is already reversed.")
    allocations = await many(session, select(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.payment_id == payment_id))
    for allocation in allocations:
        if allocation.get("invoice_id"):
            invoice = await get_ap_invoice_or_404(session, client_id, str(allocation["invoice_id"]))
            restored = min(money(invoice.get("gross_amount")), money(invoice.get("outstanding_amount")) + money(allocation.get("amount")))
            await session.execute(update(accounting_ap_invoices).where(accounting_ap_invoices.c.id == allocation["invoice_id"]).values(outstanding_amount=money_str(restored), status="posted", updated_at=utc_now_iso()))
    await session.execute(delete(accounting_ap_payment_allocations).where(accounting_ap_payment_allocations.c.payment_id == payment_id))
    reversal = await reverse_native_journal(session, client_id, str(payment.get("posted_journal_id") or ""), "ap_payment_reversal", payment_id, user.get("id"))
    await session.execute(update(accounting_ap_payments).where(accounting_ap_payments.c.id == payment_id).values(status="reversed", updated_at=utc_now_iso()))
    await add_accounting_audit(session, client_id, user.get("id"), "supplier_payment_reversed", "accounts_payable", payment_id, {"original_journal_id": payment.get("posted_journal_id"), "reversal_journal_id": reversal.get("id")})
    await session.commit()
    response = await get_ap_payment_detail(client_id, payment_id, user, session)
    response["reversal_journal"] = reversal
    return response


@api.put("/admin/accounting/clients/{client_id}/ap/settings")
async def update_ap_settings(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    await get_client_or_404(session, client_id)
    existing = await ensure_ap_settings(session, client_id)
    default_vat_code = vat_code_value(payload.get("default_vat_code", existing.get("default_vat_code") or ""))
    if default_vat_code:
        await validate_native_vat_code(session, client_id, default_vat_code)
    values = {
        "approval_required": bool(payload.get("approval_required", existing.get("approval_required", True))),
        "default_payment_terms_days": int(payload.get("default_payment_terms_days", existing.get("default_payment_terms_days") or 30) or 30),
        "default_purchase_account": str(payload.get("default_purchase_account", existing.get("default_purchase_account") or "5000") or "5000"),
        "default_vat_code": default_vat_code,
        "default_currency": str(payload.get("default_currency", existing.get("default_currency") or "GBP") or "GBP"),
        "default_bank_account": str(payload.get("default_bank_account", existing.get("default_bank_account") or "1200") or "1200"),
        "supplier_numbering": str(payload.get("supplier_numbering", existing.get("supplier_numbering") or "Automatic") or "Automatic"),
        "ai_matching_threshold": str(payload.get("ai_matching_threshold", existing.get("ai_matching_threshold") or "85") or "85"),
        "document_matching_behaviour": str(payload.get("document_matching_behaviour", existing.get("document_matching_behaviour") or "Suggest supplier ledger match") or "Suggest supplier ledger match"),
        "payment_on_account_behaviour": str(payload.get("payment_on_account_behaviour", existing.get("payment_on_account_behaviour") or "Keep unallocated until matched") or "Keep unallocated until matched"),
        "expense_behaviour": str(payload.get("expense_behaviour", existing.get("expense_behaviour") or "Post direct expenses to selected nominal") or "Post direct expenses to selected nominal"),
        "duplicate_invoice_warning": bool(payload.get("duplicate_invoice_warning", existing.get("duplicate_invoice_warning", True))),
        "allow_future_posting_dates": bool(payload.get("allow_future_posting_dates", existing.get("allow_future_posting_dates", False))),
        "automatic_invoice_numbering": bool(payload.get("automatic_invoice_numbering", existing.get("automatic_invoice_numbering", False))),
        "updated_at": utc_now_iso(),
    }
    await session.execute(update(accounting_ap_settings).where(accounting_ap_settings.c.client_id == client_id).values(**values))
    await add_accounting_audit(session, client_id, user.get("id"), "ap_settings_updated", "accounts_payable", existing["id"], values)
    await session.commit()
    updated = await ensure_ap_settings(session, client_id)
    return serialize_ap_settings(updated)


@api.post("/admin/accounting/clients/{client_id}/ar/customers")
async def create_ar_customer(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding customers.")
    customer = await create_ar_customer_profile(session, client_id, payload, user.get("id"))
    await session.commit()
    return customer


