@api.put("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}")
@api.patch("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}")
async def update_ar_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ar_invoices, accounting_ar_invoice_lines))
    invoice = await get_ar_invoice_or_404(session, client_id, invoice_id)
    require_unpaid_invoice_editable(invoice, "Sales invoice")
    ar_settings = await ensure_ar_settings(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    default_location_id, default_dimension_id = await validate_analytical_pair(
        session,
        client_id,
        payload.get("default_location_id", invoice.get("default_location_id")),
        payload.get("default_dimension_id", invoice.get("default_dimension_id")),
    )
    customer = await get_ar_customer_or_404(session, client_id, str(payload.get("customer_id") or invoice.get("customer_id")))
    invoice_number = str(payload.get("invoice_number") or payload.get("number") or invoice.get("invoice_number") or "").strip()
    if not invoice_number:
        raise HTTPException(status_code=400, detail="Sales invoice number is required.")
    duplicate = await one(
        session,
        select(accounting_ar_invoices).where(
            accounting_ar_invoices.c.client_id == client_id,
            accounting_ar_invoices.c.customer_id == customer["id"],
            accounting_ar_invoices.c.id != invoice_id,
            func.lower(accounting_ar_invoices.c.invoice_number) == invoice_number.lower(),
            accounting_ar_invoices.c.status != "void",
        ),
    )
    if duplicate and bool(ar_settings.get("duplicate_invoice_warning", True)):
        raise HTTPException(status_code=409, detail={"has_warning": True, "message": f"Possible duplicate: customer already has sales invoice {invoice_number}.", "matches": [serialize_ar_invoice(duplicate)]})
    existing_lines = await many(session, select(accounting_ar_invoice_lines).where(accounting_ar_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ar_invoice_lines.c.line_number.asc()))
    raw_lines = payload.get("lines") if isinstance(payload.get("lines"), list) else existing_lines
    lines = [ar_line_values(line, customer.get("default_sales_account") or settings_row.get("default_sales_account") or "4000") for line in raw_lines]
    lines = await validate_document_line_analytics(session, client_id, lines)
    invoice_date = parse_date_or_today(payload.get("invoice_date") or payload.get("date") or invoice.get("invoice_date")).isoformat()
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, payload.get("vat_code") or invoice.get("vat_code"), lines, "Sales invoice", invoice_date, "sales")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ar_document_totals({**invoice, **payload}, lines, "Sales invoice")
    due_date = parse_date_or_today(payload.get("due_date") or invoice.get("due_date")).isoformat()
    try:
        payment_terms_days = int(payload.get("payment_terms_days", invoice.get("payment_terms_days") or customer.get("payment_terms_days") or 30) or 30)
    except (TypeError, ValueError):
        payment_terms_days = int(ar_settings.get("default_payment_terms_days") or 30)
    was_posted = bool(invoice.get("posted_journal_id")) and str(invoice.get("status") or "").lower() == "posted"
    status = str(payload.get("status") or invoice.get("status") or "draft").strip().lower()
    if status not in AR_EDITABLE_STATUSES:
        status = invoice.get("status")
    if was_posted:
        await reverse_native_journal(session, client_id, str(invoice.get("posted_journal_id")), "ar_invoice", invoice_id, user.get("id"))
        status = "approved"
    now = utc_now_iso()
    values = {
        "customer_id": customer["id"],
        "contact_id": customer.get("contact_id"),
        "invoice_number": invoice_number,
        "reference": str(payload.get("reference", invoice.get("reference") or "") or "").strip(),
        "invoice_date": invoice_date,
        "due_date": due_date,
        "payment_terms_days": payment_terms_days,
        "currency": str(payload.get("currency", invoice.get("currency") or "GBP") or "GBP").strip().upper()[:8],
        "description": str(payload.get("description", invoice.get("description") or "") or "").strip(),
        "status": status,
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "posted_journal_id": None if was_posted else invoice.get("posted_journal_id"),
        "attachment_path": str(payload.get("attachment_path", invoice.get("attachment_path") or "") or "").strip(),
        "original_filename": str(payload.get("original_filename", invoice.get("original_filename") or "") or "").strip()[:255],
        "vat_code": header_vat_code,
        "outstanding_amount": totals["gross_amount"],
        "extracted_json": json.dumps(payload.get("extracted_json") or parse_json_object(invoice.get("extracted_json")) or {}, default=str),
        "updated_at": now,
        **totals,
    }
    await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice_id).values(**values))
    await session.execute(delete(accounting_ar_invoice_lines).where(accounting_ar_invoice_lines.c.invoice_id == invoice_id))
    for index, line in enumerate(lines, start=1):
        await session.execute(insert(accounting_ar_invoice_lines).values(id=new_id(), client_id=client_id, invoice_id=invoice_id, line_number=index, created_at=now, updated_at=now, **line))
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_updated", "accounts_receivable", invoice_id, {"status": status})
    old_signatures = [json.dumps({key: line.get(key) for key in ("description", "nominal_account_code", "vat_code", "quantity", "unit_price", "net_amount", "vat_amount", "gross_amount")}, sort_keys=True, default=str) for line in existing_lines]
    new_signatures = [json.dumps({key: line.get(key) for key in ("description", "nominal_account_code", "vat_code", "quantity", "unit_price", "net_amount", "vat_amount", "gross_amount")}, sort_keys=True, default=str) for line in lines]
    if len(lines) > len(existing_lines):
        await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_line_added", "accounts_receivable", invoice_id, {"count": len(lines) - len(existing_lines)})
    if len(lines) < len(existing_lines):
        await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_line_removed", "accounts_receivable", invoice_id, {"count": len(existing_lines) - len(lines)})
    if old_signatures != new_signatures:
        await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_lines_edited", "accounts_receivable", invoice_id, {"line_count": len(lines)})
    if was_posted:
        await session.flush()
        await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_reposted_after_edit", "accounts_receivable", invoice_id, {"original_journal_id": invoice.get("posted_journal_id")})
        return await post_ar_invoice(client_id, invoice_id, payload, user, session)
    await session.commit()
    return await get_ar_invoice_detail(client_id, invoice_id, user, session)


def ar_copy_invoice_payload(original: dict, customer: dict, lines: list[dict], today: date) -> dict:
    payment_terms_days = int(original.get("payment_terms_days") or customer.get("payment_terms_days") or 30)
    copied_lines = [{key: line.get(key) for key in ("description", "nominal_account_code", "vat_code", "quantity", "unit_price", "net_amount", "vat_amount", "gross_amount")} for line in lines]
    return {
        "customer_id": original.get("customer_id"),
        "invoice_date": today.isoformat(),
        "due_date": (today + timedelta(days=payment_terms_days)).isoformat(),
        "payment_terms_days": payment_terms_days,
        "currency": original.get("currency") or customer.get("default_currency") or "GBP",
        "description": original.get("description") or "",
        "vat_code": original.get("vat_code") or "",
        "lines": copied_lines,
    }


@api.post("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}/copy")
async def copy_ar_invoice(
    client_id: str,
    invoice_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    original = await get_ar_invoice_or_404(session, client_id, invoice_id)
    customer = await get_ar_customer_or_404(session, client_id, str(original.get("customer_id")))
    lines = await many(session, select(accounting_ar_invoice_lines).where(accounting_ar_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ar_invoice_lines.c.line_number.asc()))
    payload = ar_copy_invoice_payload(original, customer, lines, datetime.now(timezone.utc).date())
    copied = await create_ar_invoice_record(session, client_id, payload, user.get("id"))
    copied_id = str(copied.get("id") or "")
    await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == copied_id).values(source_submission_id="", attachment_path="", original_filename="", extracted_json="{}", posted_journal_id=None, updated_at=utc_now_iso()))
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_copied", "accounts_receivable", invoice_id, {"new_invoice_id": copied_id})
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_created_from_copy", "accounts_receivable", copied_id, {"source_invoice_id": invoice_id})
    await session.commit()
    ar_settings = await ensure_ar_settings(session, client_id)
    if not bool(ar_settings.get("approval_required", True)):
        return await post_ar_invoice(client_id, copied_id, {}, user, session)
    return await get_ar_invoice_detail(client_id, copied_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}/approve")
async def approve_ar_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ar_invoice_or_404(session, client_id, invoice_id)
    if invoice.get("status") in {"posted", "paid", "part_paid", "archived"}:
        raise HTTPException(status_code=400, detail="Posted invoices are already approved.")
    if invoice.get("status") not in {"awaiting_approval", "draft"}:
        raise HTTPException(status_code=400, detail="Sales invoice is not awaiting approval.")
    now = utc_now_iso()
    await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice_id).values(status="approved", approved_by=user.get("id"), approved_at=now, updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_approved", "accounts_receivable", invoice_id, {"previous_status": invoice.get("status")})
    await session.flush()
    return await post_ar_invoice(client_id, invoice_id, payload, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}/post")
async def post_ar_invoice(
    client_id: str,
    invoice_id: str,
    payload: dict = {},
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ar_invoice_or_404(session, client_id, invoice_id)
    if invoice.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Sales invoice is already posted.")
    ar_settings = await ensure_ar_settings(session, client_id)
    if bool(ar_settings.get("approval_required", True)) and invoice.get("status") != "approved":
        raise HTTPException(status_code=400, detail="Approve this sales invoice before posting.")
    if invoice.get("status") != "approved":
        raise HTTPException(status_code=400, detail="Sales invoice cannot be posted from this status.")
    accounts = await ensure_native_accounting_client(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    customer = await get_ar_customer_or_404(session, client_id, str(invoice.get("customer_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == customer.get("contact_id")))
    lines = await many(session, select(accounting_ar_invoice_lines).where(accounting_ar_invoice_lines.c.invoice_id == invoice_id).order_by(accounting_ar_invoice_lines.c.line_number.asc()))
    await validate_native_vat_codes_for_document(session, client_id, invoice.get("vat_code"), lines, "Sales invoice", invoice.get("invoice_date"), "sales")
    validate_ar_document_totals(invoice, lines, "Sales invoice")
    vat_context = await late_invoice_vat_context(session, client_id, str(invoice.get("invoice_date") or ""), invoice.get("vat_amount"))
    if vat_context and vat_context.get("requires_reopen"):
        raise HTTPException(status_code=409, detail={
            "code": "vat_period_locked",
            "message": "This invoice belongs to a locked VAT period that has not been closed. Reopen that period before posting.",
            "original_period": serialize_vat_period(vat_context["original_period"]),
        })
    if vat_context and not bool(payload.get("confirm_prior_period_vat_adjustment")):
        raise HTTPException(status_code=409, detail={
            "code": "prior_period_vat_adjustment_confirmation",
            "message": "The invoice date belongs to a closed VAT period. Create the recommended VAT adjustment automatically in the current open period?",
            "original_period": serialize_vat_period(vat_context["original_period"]),
            "reported_period": serialize_vat_period(vat_context["reported_period"]),
            "vat_amount": money_str(money(invoice.get("vat_amount"))),
        })
    debtors = find_native_account(accounts, settings_row.get("default_debtors_control_account"), "1100")
    journal_lines = [{"account": debtors, "contact": contact, "debit": money_str(money(invoice.get("gross_amount"))), "credit": "0.00", "description": invoice.get("invoice_number")}]
    for line in lines:
        amount = money(line.get("net_amount"))
        if amount:
            sales_account = find_native_account(accounts, line.get("nominal_account_code"), customer.get("default_sales_account") or ar_settings.get("default_sales_account") or settings_row.get("default_sales_account") or "4000")
            journal_lines.append({"account": sales_account, "contact": contact, "debit": "0.00", "credit": money_str(amount), "vat_code": line.get("vat_code"), "description": line.get("description"), "location_id": line.get("location_id"), "dimension_id": line.get("dimension_id")})
    vat_amount = money(invoice.get("vat_amount"))
    if vat_amount:
        vat_account = find_native_account(accounts, settings_row.get("default_vat_control_account"), "2200")
        journal_lines.append({"account": vat_account, "contact": contact, "debit": "0.00", "credit": money_str(vat_amount), "description": f"VAT on {invoice.get('invoice_number')}"})
    journal = await post_native_journal(
        session,
        client_id=client_id,
        source_type="ar_invoice",
        source_id=invoice_id,
        entry_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
        reference=invoice.get("invoice_number") or invoice_id,
        description=f"Sales invoice {invoice.get('invoice_number')}",
        lines=journal_lines,
        actor_id=user.get("id"),
        default_location_id=invoice.get("default_location_id"),
        default_dimension_id=invoice.get("default_dimension_id"),
    )
    now = utc_now_iso()
    await session.execute(
        update(accounting_ar_invoices)
        .where(accounting_ar_invoices.c.id == invoice_id)
        .values(
            status="posted",
            posted_journal_id=journal.get("id"),
            posting_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
            vat_effective_date=vat_context["posting_date"] if vat_context else invoice.get("invoice_date"),
            vat_treatment="prior_period_correction" if vat_context else "normal",
            original_vat_period_id=vat_context["original_period"].get("id") if vat_context else None,
            reported_vat_period_id=vat_context["reported_period"].get("id") if vat_context else None,
            posted_by=user.get("id"),
            posted_at=now,
            approved_by=invoice.get("approved_by") or user.get("id"),
            approved_at=invoice.get("approved_at") or now,
            updated_at=now,
        )
    )
    vat_adjustment = None
    if vat_context:
        vat_adjustment = await apply_confirmed_late_invoice_vat_adjustment(
            session, client_id, "ar_invoice", invoice_id, str(invoice.get("invoice_number") or invoice_id),
            str(invoice.get("vat_code") or ""), invoice.get("net_amount"), invoice.get("vat_amount"), invoice.get("gross_amount"),
            vat_context, user.get("id"), str(payload.get("prior_period_vat_adjustment_comment") or ""),
        )
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_posted", "accounts_receivable", invoice_id, {"journal_id": journal.get("id")})
    await session.commit()
    detail = await get_ar_invoice_detail(client_id, invoice_id, user, session)
    ledger = await get_ar_customer_ledger(client_id, str(customer["id"]), 1, 50, None, None, None, None, None, user, session)
    return {
        "ok": True,
        "transaction_type": "sales_invoice",
        "destination": "accounts_receivable",
        "invoice": detail.get("invoice") or detail,
        "invoice_or_transaction": detail.get("invoice") or detail,
        "lines": detail.get("lines") or lines,
        "totals": detail.get("totals") or {},
        "journal": journal,
        "ledger_impact": detail.get("ledger_effect") or ar_ledger_effect("sales_invoice"),
        "source_document": detail.get("source_document") or {},
        "audit_trail": detail.get("audit_trail") or [],
        "status": "posted",
        "detail": detail,
        "ledger_summary": ledger.get("summary") or {},
        "vat_adjustment": serialize_vat_adjustment(vat_adjustment) if vat_adjustment else None,
    }


@api.post("/admin/accounting/clients/{client_id}/ar/invoices/{invoice_id}/archive")
async def archive_ar_invoice(
    client_id: str,
    invoice_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    invoice = await get_ar_invoice_or_404(session, client_id, invoice_id)
    if not invoice.get("posted_journal_id") and invoice.get("status") not in {"paid", "part_paid", "posted"}:
        raise HTTPException(status_code=400, detail="Only posted sales invoices can be archived.")
    now = utc_now_iso()
    await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice_id).values(status="archived", archived_at=now, updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "sales_invoice_archived", "accounts_receivable", invoice_id, {"previous_status": invoice.get("status")})
    await session.commit()
    return {"ok": True}


@api.post("/admin/accounting/clients/{client_id}/ar/credit-notes")
async def create_ar_credit_note(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ar_credit_notes, accounting_ar_credit_note_lines))
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding customer credit notes.")
    ar_settings = await ensure_ar_settings(session, client_id)
    default_location_id, default_dimension_id = await analytical_defaults_from_payload(session, client_id, payload)
    customer = await get_ar_customer_or_404(session, client_id, str(payload.get("customer_id") or ""))
    number = str(payload.get("credit_note_number") or payload.get("number") or "").strip()
    if not number:
        raise HTTPException(status_code=400, detail="Credit note number is required.")
    credit_date = parse_date_or_today(payload.get("credit_note_date") or payload.get("date")).isoformat()
    lines = [ar_line_values(line, customer.get("default_sales_account") or ar_settings.get("default_sales_account") or "4000") for line in (payload.get("lines") or [])]
    if not lines:
        lines = [ar_line_values({"description": payload.get("description") or number, "net_amount": payload.get("net_amount"), "vat_amount": payload.get("vat_amount"), "gross_amount": payload.get("gross_amount"), "vat_code": payload.get("vat_code")}, customer.get("default_sales_account") or "4000")]
    lines = await validate_document_line_analytics(session, client_id, lines)
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, payload.get("vat_code"), lines, "Customer credit note", credit_date, "sales")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ar_document_totals(payload, lines, "Customer credit note")
    now = utc_now_iso()
    row = {
        "id": new_id(),
        "client_id": client_id,
        "customer_id": customer["id"],
        "contact_id": customer.get("contact_id"),
        "credit_note_number": number,
        "reference": str(payload.get("reference") or "").strip(),
        "credit_note_date": credit_date,
        "currency": str(payload.get("currency") or "GBP").strip().upper()[:8],
        "status": "awaiting_approval" if bool(ar_settings.get("approval_required", True)) else "approved",
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "description": str(payload.get("description") or "").strip(),
        "vat_code": header_vat_code,
        "unallocated_amount": totals["gross_amount"],
        "created_at": now,
        "updated_at": now,
        **totals,
    }
    await session.execute(insert(accounting_ar_credit_notes).values(**row))
    for index, line in enumerate(lines, start=1):
        cleaned = dict(line)
        cleaned.pop("discount_amount", None)
        await session.execute(insert(accounting_ar_credit_note_lines).values(id=new_id(), client_id=client_id, credit_note_id=row["id"], line_number=index, created_at=now, updated_at=now, **cleaned))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_credit_note_created", "accounts_receivable", row["id"], {"credit_note_number": number})
    await session.commit()
    if not bool(ar_settings.get("approval_required", True)):
        return await post_ar_credit_note(client_id, row["id"], user, session)
    return await get_ar_credit_note_detail(client_id, row["id"], user, session)


@api.get("/admin/accounting/clients/{client_id}/ar/credit-notes/{credit_note_id}")
async def get_ar_credit_note_detail(
    client_id: str,
    credit_note_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ar_credit_notes, accounting_ar_credit_note_lines))
    credit = await one(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Customer credit note not found.")
    customer = await get_ar_customer_or_404(session, client_id, str(credit.get("customer_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == customer.get("contact_id")))
    serialized_customer = serialize_ar_customer(customer, contact or {})
    lines = await many(session, select(accounting_ar_credit_note_lines).where(accounting_ar_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ar_credit_note_lines.c.line_number.asc()))
    allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.credit_note_id == credit_note_id))
    journal = await accounting_journal_with_lines(session, client_id, credit.get("posted_journal_id"))
    item = serialize_ar_credit_note(credit, lines, serialized_customer)
    item["view_only"] = credit.get("status") not in AR_EDITABLE_STATUSES
    item["allocations"] = allocations
    item["allocation_status"] = "allocated" if money(credit.get("unallocated_amount")) == Decimal("0.00") else "unallocated"
    item["journal"] = journal
    item["audit_trail"] = await ar_audit_events(session, client_id, credit_note_id)
    response = ar_document_response("customer_credit_note", item, lines)
    response.update({
        "customer": serialized_customer,
        "journal": journal,
        "audit_trail": item["audit_trail"],
        "ledger_effect": ar_ledger_effect("customer_credit_note"),
        "view_only": item["view_only"],
    })
    return response


@api.put("/admin/accounting/clients/{client_id}/ar/credit-notes/{credit_note_id}")
@api.patch("/admin/accounting/clients/{client_id}/ar/credit-notes/{credit_note_id}")
async def update_ar_credit_note(
    client_id: str,
    credit_note_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    conn = await session.connection()
    await ensure_table_columns(conn, (accounting_ar_credit_notes, accounting_ar_credit_note_lines))
    credit = await one(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Customer credit note not found.")
    require_ar_editable(credit, "Customer credit note")
    ar_settings = await ensure_ar_settings(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    default_location_id, default_dimension_id = await validate_analytical_pair(
        session,
        client_id,
        payload.get("default_location_id", credit.get("default_location_id")),
        payload.get("default_dimension_id", credit.get("default_dimension_id")),
    )
    customer = await get_ar_customer_or_404(session, client_id, str(payload.get("customer_id") or credit.get("customer_id")))
    number = str(payload.get("credit_note_number") or payload.get("number") or credit.get("credit_note_number") or "").strip()
    if not number:
        raise HTTPException(status_code=400, detail="Credit note number is required.")
    duplicate = await one(
        session,
        select(accounting_ar_credit_notes).where(
            accounting_ar_credit_notes.c.client_id == client_id,
            accounting_ar_credit_notes.c.customer_id == customer["id"],
            accounting_ar_credit_notes.c.id != credit_note_id,
            func.lower(accounting_ar_credit_notes.c.credit_note_number) == number.lower(),
        ),
    )
    if duplicate and bool(ar_settings.get("duplicate_invoice_warning", True)):
        raise HTTPException(status_code=409, detail={"has_warning": True, "message": f"Possible duplicate: customer already has credit note {number}.", "matches": [serialize_ar_credit_note(duplicate)]})
    existing_lines = await many(session, select(accounting_ar_credit_note_lines).where(accounting_ar_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ar_credit_note_lines.c.line_number.asc()))
    raw_lines = payload.get("lines") if isinstance(payload.get("lines"), list) else existing_lines
    lines = [ar_line_values(line, customer.get("default_sales_account") or settings_row.get("default_sales_account") or "4000") for line in raw_lines]
    lines = await validate_document_line_analytics(session, client_id, lines)
    effective_credit_date = parse_date_or_today(payload.get("credit_note_date") or payload.get("date") or credit.get("credit_note_date")).isoformat()
    header_vat_code = await validate_native_vat_codes_for_document(session, client_id, payload.get("vat_code") or credit.get("vat_code"), lines, "Customer credit note", effective_credit_date, "sales")
    if header_vat_code == "NO VAT":
        normalize_document_header_outside_vat_period(payload)
    totals = validate_ar_document_totals({**credit, **payload}, lines, "Customer credit note")
    status = str(payload.get("status") or credit.get("status") or "draft").strip().lower()
    if status not in AR_EDITABLE_STATUSES:
        status = credit.get("status")
    now = utc_now_iso()
    values = {
        "customer_id": customer["id"],
        "contact_id": customer.get("contact_id"),
        "credit_note_number": number,
        "reference": str(payload.get("reference", credit.get("reference") or "") or "").strip(),
        "credit_note_date": parse_date_or_today(payload.get("credit_note_date") or payload.get("date") or credit.get("credit_note_date")).isoformat(),
        "currency": str(payload.get("currency", credit.get("currency") or "GBP") or "GBP").strip().upper()[:8],
        "status": status,
        "default_location_id": default_location_id,
        "default_dimension_id": default_dimension_id,
        "description": str(payload.get("description", credit.get("description") or "") or "").strip(),
        "vat_code": header_vat_code,
        "unallocated_amount": totals["gross_amount"],
        "updated_at": now,
        **totals,
    }
    await session.execute(update(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.id == credit_note_id).values(**values))
    await session.execute(delete(accounting_ar_credit_note_lines).where(accounting_ar_credit_note_lines.c.credit_note_id == credit_note_id))
    for index, line in enumerate(lines, start=1):
        cleaned = dict(line)
        cleaned.pop("discount_amount", None)
        await session.execute(insert(accounting_ar_credit_note_lines).values(id=new_id(), client_id=client_id, credit_note_id=credit_note_id, line_number=index, created_at=now, updated_at=now, **cleaned))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_credit_note_updated", "accounts_receivable", credit_note_id, {"status": status})
    await session.commit()
    return await get_ar_credit_note_detail(client_id, credit_note_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/credit-notes/{credit_note_id}/post")
async def post_ar_credit_note(
    client_id: str,
    credit_note_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    credit = await one(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Customer credit note not found.")
    if credit.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Customer credit note is already posted.")
    accounts = await ensure_native_accounting_client(session, client_id)
    settings_row = await ensure_accounting_settings(session, client_id)
    ar_settings = await ensure_ar_settings(session, client_id)
    customer = await get_ar_customer_or_404(session, client_id, str(credit.get("customer_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == customer.get("contact_id")))
    lines = await many(session, select(accounting_ar_credit_note_lines).where(accounting_ar_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ar_credit_note_lines.c.line_number.asc()))
    if credit.get("status") not in AR_EDITABLE_STATUSES | {"approved"}:
        raise HTTPException(status_code=400, detail="Customer credit note cannot be posted from this status.")
    await validate_native_vat_codes_for_document(session, client_id, credit.get("vat_code"), lines, "Customer credit note", credit.get("credit_note_date"), "sales")
    validate_ar_document_totals(credit, lines, "Customer credit note")
    journal_lines = []
    for line in lines:
        amount = money(line.get("net_amount"))
        if amount:
            sales_account = find_native_account(accounts, line.get("nominal_account_code"), customer.get("default_sales_account") or ar_settings.get("default_sales_account") or "4000")
            journal_lines.append({"account": sales_account, "contact": contact, "debit": money_str(amount), "credit": "0.00", "vat_code": line.get("vat_code"), "description": line.get("description"), "location_id": line.get("location_id"), "dimension_id": line.get("dimension_id")})
    vat_amount = money(credit.get("vat_amount"))
    if vat_amount:
        vat_account = find_native_account(accounts, settings_row.get("default_vat_control_account"), "2200")
        journal_lines.append({"account": vat_account, "contact": contact, "debit": money_str(vat_amount), "credit": "0.00", "description": f"VAT credit {credit.get('credit_note_number')}"})
    debtors = find_native_account(accounts, settings_row.get("default_debtors_control_account"), "1100")
    journal_lines.append({"account": debtors, "contact": contact, "debit": "0.00", "credit": money_str(money(credit.get("gross_amount"))), "description": credit.get("credit_note_number")})
    journal = await post_native_journal(
        session, client_id, "ar_credit_note", credit_note_id, credit.get("credit_note_date"),
        credit.get("credit_note_number") or credit_note_id, f"Customer credit note {credit.get('credit_note_number')}",
        journal_lines, user.get("id"), credit.get("default_location_id"), credit.get("default_dimension_id"),
    )
    now = utc_now_iso()
    await session.execute(update(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.id == credit_note_id).values(status="posted", posted_journal_id=journal.get("id"), posted_by=user.get("id"), posted_at=now, updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_credit_note_posted", "accounts_receivable", credit_note_id, {"journal_id": journal.get("id")})
    await session.commit()
    return await get_ar_credit_note_detail(client_id, credit_note_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/credit-notes/{credit_note_id}/approve")
async def approve_ar_credit_note(
    client_id: str,
    credit_note_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    credit = await one(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id == credit_note_id))
    if not credit:
        raise HTTPException(status_code=404, detail="Customer credit note not found.")
    if credit.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Customer credit note is already posted.")
    if str(credit.get("status") or "").lower() not in {"awaiting_approval", "draft"}:
        raise HTTPException(status_code=400, detail="Customer credit note is not awaiting approval.")
    lines = await many(session, select(accounting_ar_credit_note_lines).where(accounting_ar_credit_note_lines.c.credit_note_id == credit_note_id).order_by(accounting_ar_credit_note_lines.c.line_number.asc()))
    await validate_native_vat_codes_for_document(session, client_id, credit.get("vat_code"), lines, "Customer credit note", credit.get("credit_note_date"), "sales")
    validate_ar_document_totals(credit, lines, "Customer credit note")
    now = utc_now_iso()
    await session.execute(update(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.id == credit_note_id).values(status="approved", updated_at=now))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_credit_note_approved", "accounts_receivable", credit_note_id, {"previous_status": credit.get("status")})
    await session.flush()
    return await post_ar_credit_note(client_id, credit_note_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/receipts")
async def create_ar_receipt(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding customer receipts.")
    customer = await get_ar_customer_or_404(session, client_id, str(payload.get("customer_id") or ""))
    amount = money(payload.get("amount"))
    if amount == 0:
        raise HTTPException(status_code=400, detail="Receipt amount must not be zero. Use a negative amount for a customer refund.")
    posting_amount = abs(amount)
    is_refund = amount < 0
    settings_row = await ensure_accounting_settings(session, client_id)
    ar_settings = await ensure_ar_settings(session, client_id)
    accounts = await ensure_native_accounting_client(session, client_id)
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == customer.get("contact_id")))
    bank_account_code = str(payload.get("bank_account_code") or "").strip()
    if not bank_account_code:
        raise HTTPException(status_code=400, detail="Bank account is required before posting a customer receipt.")
    bank_account = await one(session, select(accounting_bank_accounts).where(accounting_bank_accounts.c.client_id == client_id, accounting_bank_accounts.c.nominal_account_code == bank_account_code))
    bank = require_native_bank_account(accounts, bank_account_code)
    debtors = find_native_account(accounts, settings_row.get("default_debtors_control_account"), "1100")
    receipt_date = parse_date_or_today(payload.get("receipt_date")).isoformat()
    reference = str(payload.get("reference") or f"Receipt {receipt_date}").strip()
    receipt_id = str(payload.get("_receipt_id") or new_id())
    now = utc_now_iso()
    if bool(ar_settings.get("approval_required", True)) and not bool(payload.get("_approved")):
        row = {"id": receipt_id, "client_id": client_id, "customer_id": customer["id"], "contact_id": customer.get("contact_id"), "receipt_date": receipt_date, "bank_account_code": bank_account_code, "payment_method": str(payload.get("payment_method") or "Bank Transfer"), "reference": reference, "amount": money_str(amount), "currency": str(payload.get("currency") or "GBP").strip().upper()[:8], "status": "awaiting_approval", "posted_journal_id": None, "bank_transaction_id": None, "default_location_id": default_location_id, "default_dimension_id": default_dimension_id, "attachment_path": str(payload.get("attachment_path") or "").strip(), "original_filename": str(payload.get("original_filename") or "").strip()[:255], "created_at": now, "updated_at": now}
        await session.execute(insert(accounting_ar_receipts).values(**row))
        for requested in payload.get("allocations") or []:
            await session.execute(insert(accounting_ar_receipt_allocations).values(id=new_id(), client_id=client_id, receipt_id=receipt_id, invoice_id=requested.get("invoice_id"), credit_note_id=requested.get("credit_note_id"), amount=money_str(money(requested.get("amount"))), created_at=now))
        await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_created", "accounts_receivable", receipt_id, {"status": "awaiting_approval", "amount": money_str(amount)})
        await session.commit()
        return await get_ar_receipt_detail(client_id, receipt_id, user, session)
    journal = await post_native_journal(
        session,
        client_id=client_id,
        source_type="ar_receipt",
        source_id="pending",
        entry_date=receipt_date,
        reference=reference,
        description=f"Customer {'refund' if is_refund else 'receipt'} {customer.get('trading_name') or contact.get('name')}",
        lines=[
            {"account": bank, "contact": contact, "debit": money_str(posting_amount) if not is_refund else "0.00", "credit": money_str(posting_amount) if is_refund else "0.00", "description": reference},
            {"account": debtors, "contact": contact, "debit": money_str(posting_amount) if is_refund else "0.00", "credit": money_str(posting_amount) if not is_refund else "0.00", "description": reference},
        ],
        actor_id=user.get("id"),
        default_location_id=default_location_id,
        default_dimension_id=default_dimension_id,
    )
    bank_transaction_id = new_id()
    row = {
        "id": receipt_id,
        "client_id": client_id,
        "customer_id": customer["id"],
        "contact_id": customer.get("contact_id"),
        "receipt_date": receipt_date,
        "bank_account_code": bank_account_code,
        "payment_method": str(payload.get("payment_method") or "Bank Transfer"),
        "reference": reference,
        "amount": money_str(amount),
        "currency": str(payload.get("currency") or "GBP").strip().upper()[:8],
        "status": "posted",
        "posted_journal_id": journal.get("id"),
        "bank_transaction_id": bank_transaction_id,
        "attachment_path": str(payload.get("attachment_path") or "").strip(),
        "original_filename": str(payload.get("original_filename") or "").strip()[:255],
        "created_at": now,
        "updated_at": now,
    }
    await session.execute(insert(accounting_ar_receipts).values(**row))
    await session.execute(
        insert(accounting_bank_transactions).values(
            id=bank_transaction_id,
            client_id=client_id,
            bank_account_id=(bank_account or {}).get("id"),
            bank_account_code=bank_account_code,
            transaction_date=receipt_date,
            description=f"Customer receipt {contact.get('name')}",
            reference=reference,
            transaction_type="customer_receipt",
            source_type="ar_receipt",
            money_in=money_str(posting_amount) if not is_refund else "0.00",
            money_out=money_str(posting_amount) if is_refund else "0.00",
            balance="0.00",
            status="unreconciled",
            matched_to=None,
            suggested_match=f"Customer receipt: {contact.get('name')}",
            confidence=90,
            matched_contact_id=customer.get("contact_id"),
            matched_account_code=bank_account_code,
            journal_entry_id=journal.get("id"),
            default_location_id=default_location_id,
            default_dimension_id=default_dimension_id,
            raw_json=json.dumps({"source": "accounts_receivable", "receipt_id": receipt_id, "reconciliation_owner": "banking"}),
            reconciled_at=None,
            created_at=now,
            updated_at=now,
        )
    )
    remaining = posting_amount
    allocation_target = str(payload.get("allocation_target") or ("selected" if payload.get("allocations") else "on_account")).strip().lower()
    invoice_ids = [] if is_refund else [str(item.get("invoice_id")) for item in (payload.get("allocations") or []) if item.get("invoice_id")]
    if invoice_ids:
        invoices = await many(session, select(accounting_ar_invoices).where(accounting_ar_invoices.c.client_id == client_id, accounting_ar_invoices.c.id.in_(invoice_ids)))
    elif allocation_target == "oldest" and not is_refund:
        invoices = await many(
            session,
            select(accounting_ar_invoices)
            .where(accounting_ar_invoices.c.client_id == client_id, accounting_ar_invoices.c.customer_id == customer["id"], accounting_ar_invoices.c.outstanding_amount != "0.00")
            .order_by(accounting_ar_invoices.c.due_date.asc(), accounting_ar_invoices.c.invoice_date.asc()),
        )
    else:
        invoices = []
    allocation_by_invoice = {str(item.get("invoice_id")): money(item.get("amount")) for item in (payload.get("allocations") or []) if item.get("invoice_id")}
    for invoice in invoices:
        if remaining <= 0:
            break
        existing_allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.invoice_id == invoice["id"]))
        outstanding = max(money(invoice.get("gross_amount")) - sum((money(row.get("amount")) for row in existing_allocations), Decimal("0.00")), Decimal("0.00"))
        if outstanding <= 0:
            continue
        desired = allocation_by_invoice.get(str(invoice["id"]), outstanding)
        allocate = min(remaining, outstanding, desired if desired > 0 else outstanding)
        if allocate <= 0:
            continue
        await session.execute(insert(accounting_ar_receipt_allocations).values(id=new_id(), client_id=client_id, receipt_id=receipt_id, invoice_id=invoice["id"], amount=money_str(allocate), created_at=now))
        await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_allocation_created", "accounts_receivable", receipt_id, {"invoice_id": invoice["id"], "amount": money_str(allocate)})
        new_outstanding = outstanding - allocate
        new_status = "paid" if new_outstanding == 0 else "part_paid"
        await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice["id"]).values(outstanding_amount=money_str(new_outstanding), status=new_status, updated_at=now))
        remaining -= allocate
    await session.execute(update(accounting_journal_entries).where(accounting_journal_entries.c.id == journal.get("id")).values(source_id=receipt_id))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_posted", "accounts_receivable", receipt_id, {"journal_id": journal.get("id"), "amount": money_str(amount)})
    await session.commit()
    return await get_ar_receipt_detail(client_id, receipt_id, user, session)


@api.get("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}")
async def get_ar_receipt_detail(
    client_id: str,
    receipt_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt:
        raise HTTPException(status_code=404, detail="Customer receipt not found.")
    customer = await get_ar_customer_or_404(session, client_id, str(receipt.get("customer_id")))
    contact = await one(session, select(accounting_contacts).where(accounting_contacts.c.id == customer.get("contact_id")))
    serialized_customer = serialize_ar_customer(customer, contact or {})
    allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    journal = await accounting_journal_with_lines(session, client_id, receipt.get("posted_journal_id"))
    bank_transaction = await one(session, select(accounting_bank_transactions).where(accounting_bank_transactions.c.client_id == client_id, accounting_bank_transactions.c.id == receipt.get("bank_transaction_id"))) if receipt.get("bank_transaction_id") else None
    item = serialize_ar_receipt(receipt, allocations, serialized_customer)
    item["view_only"] = True
    item["journal"] = journal
    item["audit_trail"] = await ar_audit_events(session, client_id, receipt_id)
    item["bank_transaction"] = bank_transaction or {}
    response = ar_document_response("customer_receipt", item, allocations)
    response.update({
        "customer": serialized_customer,
        "allocations": allocations,
        "journal": journal,
        "audit_trail": item["audit_trail"],
        "ledger_effect": ar_ledger_effect("customer_receipt"),
        "view_only": True,
        "bank_transaction": bank_transaction or {},
    })
    return response


@api.post("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}/allocations/{allocation_id}/unallocate")
async def unallocate_ar_receipt(
    client_id: str,
    receipt_id: str,
    allocation_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt:
        raise HTTPException(status_code=404, detail="Customer receipt not found.")
    allocation = await one(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.receipt_id == receipt_id, accounting_ar_receipt_allocations.c.id == allocation_id))
    if not allocation:
        raise HTTPException(status_code=404, detail="Receipt allocation not found.")
    invoice_id = allocation.get("invoice_id")
    if invoice_id:
        invoice = await get_ar_invoice_or_404(session, client_id, str(invoice_id))
        remaining_allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.invoice_id == invoice_id, accounting_ar_receipt_allocations.c.id != allocation_id))
        remaining_credit_allocations = await many(session, select(accounting_ar_credit_allocations).where(accounting_ar_credit_allocations.c.client_id == client_id, accounting_ar_credit_allocations.c.invoice_id == invoice_id))
        values = invoice_allocation_values(invoice, sum((money(row.get("amount")) for row in [*remaining_allocations, *remaining_credit_allocations]), Decimal("0.00")))
        await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice_id).values(outstanding_amount=values["invoice_balance"], status=values["status"], updated_at=utc_now_iso()))
    credit_note_id = allocation.get("credit_note_id")
    if credit_note_id:
        credit = await one(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id == credit_note_id))
        if credit:
            remaining_allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.credit_note_id == credit_note_id, accounting_ar_receipt_allocations.c.id != allocation_id))
            remaining = max(money(credit.get("gross_amount")) - sum((money(row.get("amount")) for row in remaining_allocations), Decimal("0.00")), Decimal("0.00"))
            await session.execute(update(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.id == credit_note_id).values(unallocated_amount=money_str(remaining), status="posted" if remaining == money(credit.get("gross_amount")) else "part_paid" if remaining > 0 else "paid", updated_at=utc_now_iso()))
    await session.execute(delete(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.id == allocation_id))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_unallocated", "accounts_receivable", receipt_id, {"allocation_id": allocation_id, "invoice_id": invoice_id, "amount": allocation.get("amount"), "bank_journal_changed": False})
    await session.commit()
    return await get_ar_receipt_detail(client_id, receipt_id, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}/allocations")
async def allocate_ar_receipt(
    client_id: str,
    receipt_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt or receipt.get("status") not in {"posted", "part_allocated", "allocated"}:
        raise HTTPException(status_code=404, detail="Posted customer receipt not found.")
    receipt_allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    is_refund = money(receipt.get("amount")) < 0
    receipt_remaining = max(abs(money(receipt.get("amount"))) - sum((money(row.get("amount")) for row in receipt_allocations), Decimal("0.00")), Decimal("0.00"))
    requested_rows = payload.get("allocations") if isinstance(payload.get("allocations"), list) else [payload]
    requested_by_invoice: dict[str, Decimal] = {}
    for requested in requested_rows:
        invoice_id = str((requested or {}).get("invoice_id") or "")
        amount = money((requested or {}).get("amount"))
        if not invoice_id or amount <= 0:
            raise HTTPException(status_code=400, detail="Every allocation requires an invoice and an amount greater than zero.")
        requested_by_invoice[invoice_id] = requested_by_invoice.get(invoice_id, Decimal("0.00")) + amount
    if sum(requested_by_invoice.values(), Decimal("0.00")) > receipt_remaining:
        raise HTTPException(status_code=400, detail="The requested allocations exceed the unallocated customer receipt balance.")
    target_table = accounting_ar_credit_notes if is_refund else accounting_ar_invoices
    invoices = await many(session, select(target_table).where(target_table.c.client_id == client_id, target_table.c.id.in_(list(requested_by_invoice))))
    invoice_by_id = {str(invoice["id"]): invoice for invoice in invoices}
    if len(invoice_by_id) != len(requested_by_invoice):
        raise HTTPException(status_code=404, detail="One or more sales invoices could not be found.")
    now = utc_now_iso()
    created = []
    for invoice_id, amount in requested_by_invoice.items():
        invoice = invoice_by_id[invoice_id]
        if str(invoice.get("customer_id")) != str(receipt.get("customer_id")):
            raise HTTPException(status_code=400, detail="Every allocation document must belong to the receipt customer.")
        target_column = accounting_ar_receipt_allocations.c.credit_note_id if is_refund else accounting_ar_receipt_allocations.c.invoice_id
        invoice_allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, target_column == invoice_id))
        invoice_remaining = max(money(invoice.get("gross_amount")) - sum((money(row.get("amount")) for row in invoice_allocations), Decimal("0.00")), Decimal("0.00"))
        if amount > invoice_remaining:
            raise HTTPException(status_code=400, detail=f"Allocation for {invoice.get('invoice_number') or invoice_id} exceeds its outstanding balance.")
        allocation = {"id": new_id(), "client_id": client_id, "receipt_id": receipt_id, "invoice_id": None if is_refund else invoice_id, "credit_note_id": invoice_id if is_refund else None, "amount": money_str(amount), "created_at": now}
        await session.execute(insert(accounting_ar_receipt_allocations).values(**allocation))
        created.append(allocation)
        new_outstanding = invoice_remaining - amount
        if is_refund:
            await session.execute(update(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.id == invoice_id).values(unallocated_amount=money_str(new_outstanding), status="paid" if new_outstanding == 0 else "part_paid", updated_at=now))
        else:
            await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == invoice_id).values(outstanding_amount=money_str(new_outstanding), status="paid" if new_outstanding == 0 else "part_paid", updated_at=now))
        await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_allocation_created", "accounts_receivable", receipt_id, {"invoice_id": invoice_id, "amount": money_str(amount), "bank_journal_changed": False})
    await ensure_current_cash_vat_corrections(session, client_id)
    await session.commit()
    response = await get_ar_receipt_detail(client_id, receipt_id, user, session)
    response["created_allocations"] = created
    return response


@api.get("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}/allocation-options")
async def get_ar_receipt_allocation_options(
    client_id: str,
    receipt_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt:
        raise HTTPException(status_code=404, detail="Customer receipt not found.")
    allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.client_id == client_id, accounting_ar_receipt_allocations.c.receipt_id == receipt_id).order_by(accounting_ar_receipt_allocations.c.created_at.asc()))
    invoice_ids = [str(row.get("invoice_id")) for row in allocations if row.get("invoice_id")]
    credit_note_ids = [str(row.get("credit_note_id")) for row in allocations if row.get("credit_note_id")]
    existing_invoices = await many(session, select(accounting_ar_invoices).where(accounting_ar_invoices.c.client_id == client_id, accounting_ar_invoices.c.id.in_(invoice_ids))) if invoice_ids else []
    existing_credits = await many(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.id.in_(credit_note_ids))) if credit_note_ids else []
    existing_by_id = {str(row["id"]): row for row in existing_invoices}
    existing_by_id.update({str(row["id"]): row for row in existing_credits})
    is_refund = money(receipt.get("amount")) < 0
    if is_refund:
        open_invoices = await many(session, select(accounting_ar_credit_notes).where(accounting_ar_credit_notes.c.client_id == client_id, accounting_ar_credit_notes.c.customer_id == receipt.get("customer_id"), accounting_ar_credit_notes.c.status.in_(["posted", "part_paid"]), accounting_ar_credit_notes.c.unallocated_amount != "0.00").order_by(accounting_ar_credit_notes.c.credit_note_date.asc()))
    else:
        open_invoices = await many(session, select(accounting_ar_invoices).where(
            accounting_ar_invoices.c.client_id == client_id,
            accounting_ar_invoices.c.customer_id == receipt.get("customer_id"),
            accounting_ar_invoices.c.status.in_(["posted", "part_paid"]),
            accounting_ar_invoices.c.outstanding_amount != "0.00",
        ).order_by(accounting_ar_invoices.c.invoice_date.asc(), accounting_ar_invoices.c.invoice_number.asc()))
    allocated = sum((money(row.get("amount")) for row in allocations), Decimal("0.00"))
    return {
        "receipt": {
            "id": receipt_id,
            "reference": receipt.get("reference"),
            "date": receipt.get("receipt_date"),
            "amount": money_str(abs(money(receipt.get("amount")))),
            "allocated_amount": money_str(allocated),
            "unallocated_amount": money_str(max(abs(money(receipt.get("amount"))) - allocated, Decimal("0.00"))),
            "is_refund": is_refund,
        },
        "existing_allocations": [{
            **dict(row),
            "invoice_number": (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("invoice_number") or (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("credit_note_number"),
            "invoice_date": (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("invoice_date") or (existing_by_id.get(str(row.get("invoice_id") or row.get("credit_note_id"))) or {}).get("credit_note_date"),
        } for row in allocations],
        "invoices": [{
            "id": row.get("id"),
            "invoice_number": row.get("invoice_number") or row.get("credit_note_number"),
            "invoice_date": row.get("invoice_date") or row.get("credit_note_date"),
            "due_date": row.get("due_date"),
            "gross_amount": money_str(money(row.get("gross_amount"))),
            "outstanding_amount": money_str(money(row.get("unallocated_amount") if is_refund else row.get("outstanding_amount"))),
            "status": row.get("status"),
        } for row in open_invoices],
    }


@api.post("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}/approve")
async def approve_ar_receipt(client_id: str, receipt_id: str, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt:
        raise HTTPException(status_code=404, detail="Customer receipt not found.")
    if receipt.get("status") != "awaiting_approval" or receipt.get("posted_journal_id"):
        raise HTTPException(status_code=400, detail="Only awaiting-approval customer receipts can be approved.")
    allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    await session.execute(delete(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    await session.execute(delete(accounting_ar_receipts).where(accounting_ar_receipts.c.id == receipt_id))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_approved", "accounts_receivable", receipt_id, {})
    return await create_ar_receipt(client_id, {**receipt, "_receipt_id": receipt_id, "_approved": True, "allocations": allocations}, user, session)


@api.post("/admin/accounting/clients/{client_id}/ar/receipts/{receipt_id}/reverse")
async def reverse_ar_receipt(client_id: str, receipt_id: str, user: dict = Depends(require_admin), session: AsyncSession = Depends(get_db)):
    receipt = await one(session, select(accounting_ar_receipts).where(accounting_ar_receipts.c.client_id == client_id, accounting_ar_receipts.c.id == receipt_id))
    if not receipt:
        raise HTTPException(status_code=404, detail="Customer receipt not found.")
    if receipt.get("status") == "reversed":
        raise HTTPException(status_code=400, detail="Customer receipt is already reversed.")
    allocations = await many(session, select(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    for allocation in allocations:
        if allocation.get("invoice_id"):
            invoice = await get_ar_invoice_or_404(session, client_id, str(allocation["invoice_id"]))
            restored = min(money(invoice.get("gross_amount")), money(invoice.get("outstanding_amount")) + money(allocation.get("amount")))
            await session.execute(update(accounting_ar_invoices).where(accounting_ar_invoices.c.id == allocation["invoice_id"]).values(outstanding_amount=money_str(restored), status="posted", updated_at=utc_now_iso()))
    await session.execute(delete(accounting_ar_receipt_allocations).where(accounting_ar_receipt_allocations.c.receipt_id == receipt_id))
    reversal = await reverse_native_journal(session, client_id, str(receipt.get("posted_journal_id") or ""), "ar_receipt_reversal", receipt_id, user.get("id"))
    await session.execute(update(accounting_ar_receipts).where(accounting_ar_receipts.c.id == receipt_id).values(status="reversed", updated_at=utc_now_iso()))
    await add_accounting_audit(session, client_id, user.get("id"), "customer_receipt_reversed", "accounts_receivable", receipt_id, {"original_journal_id": receipt.get("posted_journal_id"), "reversal_journal_id": reversal.get("id")})
    await session.commit()
    response = await get_ar_receipt_detail(client_id, receipt_id, user, session)
    response["reversal_journal"] = reversal
    return response


@api.put("/admin/accounting/clients/{client_id}/ar/settings")
async def update_ar_settings(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    await get_client_or_404(session, client_id)
    existing = await ensure_ar_settings(session, client_id)
    default_vat_code = vat_code_value(payload.get("default_vat_code", existing.get("default_vat_code") or ""))
    if default_vat_code:
        await validate_native_vat_code(session, client_id, default_vat_code)
    values = {
        "approval_required": bool(payload.get("approval_required", existing.get("approval_required", True))),
        "default_payment_terms_days": int(payload.get("default_payment_terms_days", existing.get("default_payment_terms_days") or 30) or 30),
        "default_sales_account": str(payload.get("default_sales_account", existing.get("default_sales_account") or "4000") or "4000"),
        "default_vat_code": default_vat_code,
        "invoice_number_prefix": str(payload.get("invoice_number_prefix", existing.get("invoice_number_prefix") or "SINV") or "SINV")[:32],
        "next_invoice_number": int(payload.get("next_invoice_number", existing.get("next_invoice_number") or 1) or 1),
        "duplicate_invoice_warning": bool(payload.get("duplicate_invoice_warning", existing.get("duplicate_invoice_warning", True))),
        "credit_limit_warnings": bool(payload.get("credit_limit_warnings", existing.get("credit_limit_warnings", True))),
        "automatic_customer_numbering": bool(payload.get("automatic_customer_numbering", existing.get("automatic_customer_numbering", True))),
        "customer_numbering": str(payload.get("customer_numbering", existing.get("customer_numbering") or "Automatic") or "Automatic"),
        "receipt_on_account_behaviour": str(payload.get("receipt_on_account_behaviour", existing.get("receipt_on_account_behaviour") or "Keep unallocated until matched") or "Keep unallocated until matched"),
        "sales_behaviour": str(payload.get("sales_behaviour", existing.get("sales_behaviour") or "Post sales invoices to selected nominal") or "Post sales invoices to selected nominal"),
        "credit_control_behaviour": str(payload.get("credit_control_behaviour", existing.get("credit_control_behaviour") or "Use customer credit control settings") or "Use customer credit control settings"),
        "updated_at": utc_now_iso(),
    }
    await session.execute(update(accounting_ar_settings).where(accounting_ar_settings.c.client_id == client_id).values(**values))
    await add_accounting_audit(session, client_id, user.get("id"), "ar_settings_updated", "accounts_receivable", existing["id"], values)
    await session.commit()
    updated = await ensure_ar_settings(session, client_id)
    return serialize_ar_settings(updated)


@api.post("/admin/accounting/clients/{client_id}/bank/accounts")
async def create_bank_account(
    client_id: str,
    payload: dict,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    client = await get_client_or_404(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting before adding bank accounts.")
    accounts = await ensure_native_accounting_client(session, client_id)
    nominal_code = str(payload.get("nominal_account_code") or "").strip()
    if not nominal_code:
        next_code = 1200 + len([a for a in accounts if a.get("purpose") == "Bank Account" or str(a.get("account_type") or "").lower() == "bank"]) * 10
        nominal_code = str(next_code)
    nominal = next((a for a in accounts if str(a.get("code")) == nominal_code), None)
    now = utc_now_iso()
    if not nominal:
        account_name = str(payload.get("account_name") or "Bank account").strip()
        nominal = {
            "id": new_id(),
            "client_id": client_id,
            "code": nominal_code,
            "name": account_name,
            "category": "Asset",
            "account_type": "Bank",
            "purpose": "Bank Account",
            "normal_balance": "debit",
            "control_account": False,
            "is_control_account": False,
            "banking_enabled": True,
            "active": True,
            "created_at": now,
            "updated_at": now,
        }
        await session.execute(insert(accounting_accounts).values(**nominal))
    else:
        nominal_values = apply_banking_account_defaults({"banking_enabled": True})
        nominal_values["updated_at"] = now
        await session.execute(update(accounting_accounts).where(accounting_accounts.c.id == nominal["id"]).values(**nominal_values))
        nominal = {**nominal, **nominal_values}
    default_account = bool(payload.get("default_account"))
    if default_account:
        await session.execute(update(accounting_bank_accounts).where(accounting_bank_accounts.c.client_id == client_id).values(default_account=False, updated_at=now))
    row = {
        "id": new_id(),
        "client_id": client_id,
        "account_name": str(payload.get("account_name") or nominal.get("name") or "Bank account").strip(),
        "bank_name": str(payload.get("bank_name") or "").strip(),
        "account_number": str(payload.get("account_number") or "").strip(),
        "sort_code": str(payload.get("sort_code") or "").strip(),
        "currency": str(payload.get("currency") or "GBP").strip().upper()[:8],
        "nominal_account_code": nominal_code,
        "opening_balance": money_str(money(payload.get("opening_balance"))),
        "default_account": default_account,
        "allow_payments": bool(payload.get("allow_payments", True)),
        "allow_receipts": bool(payload.get("allow_receipts", True)),
        "active": bool(payload.get("active", True)),
        "created_at": now,
        "updated_at": now,
    }
    await session.execute(insert(accounting_bank_accounts).values(**row))
    opening = money(row["opening_balance"])
    if opening:
        suspense = find_native_account(accounts + [nominal], None, (await ensure_accounting_settings(session, client_id)).get("default_suspense_account") or "9999")
        if opening > 0:
            lines = [{"account": nominal, "debit": money_str(opening), "credit": "0.00", "description": "Opening bank balance"}, {"account": suspense, "debit": "0.00", "credit": money_str(opening), "description": "Opening bank balance"}]
        else:
            lines = [{"account": suspense, "debit": money_str(-opening), "credit": "0.00", "description": "Opening bank balance"}, {"account": nominal, "debit": "0.00", "credit": money_str(-opening), "description": "Opening bank balance"}]
        await post_native_journal(session, client_id, "bank_opening_balance", row["id"], datetime.now(timezone.utc).date().isoformat(), f"OPEN-{nominal_code}", "Opening bank balance", lines, user.get("id"))
    await add_accounting_audit(session, client_id, user.get("id"), "bank_account_created", "banking", row["id"], row)
    await session.commit()
    return serialize_bank_account(row)


