@api.put("/admin/integrations/{provider}/config")
async def save_accounting_provider_config(
    provider: str,
    payload: IntegrationAppSettingsIn,
    user: dict = Depends(require_platform_admin),
    session: AsyncSession = Depends(get_db),
):
    provider = clean_provider(provider)
    if provider == "quickbooks":
        return await save_quickbooks_config(
            QuickBooksAppSettingsIn(**payload.dict()),
            user,
            session,
        )
    meta = INTEGRATION_PROVIDER_META[provider]
    environment = str(payload.environment or meta["default_environment"]).strip().lower()
    if environment not in meta["environments"]:
        raise HTTPException(status_code=400, detail=f"Invalid {meta['label']} environment")
    existing = await one(
        session,
        select(integration_app_settings).where(integration_app_settings.c.provider == provider),
    ) or {}
    submitted_client_id = str(payload.client_id or "").strip()
    values = {
        "provider": provider,
        "enabled": bool(payload.enabled),
        "client_id": submitted_client_id or str(existing.get("client_id") or "").strip(),
        "environment": environment,
        "redirect_uri": str(payload.redirect_uri or existing.get("redirect_uri") or "").strip(),
        "updated_at": utc_now_iso(),
    }
    if payload.client_secret:
        values["client_secret_enc"] = encrypt_secret(payload.client_secret.strip())
    else:
        values["client_secret_enc"] = existing.get("client_secret_enc")
    if existing:
        await session.execute(
            update(integration_app_settings)
            .where(integration_app_settings.c.provider == provider)
            .values(**values)
        )
    else:
        values["created_at"] = utc_now_iso()
        await session.execute(insert(integration_app_settings).values(**values))
    await session.commit()
    credentials = await get_provider_credentials(provider, session)
    return provider_config_response(provider, credentials)


@api.put("/admin/integrations/quickbooks/config")
async def save_quickbooks_config(
    payload: QuickBooksAppSettingsIn,
    user: dict = Depends(require_platform_admin),
    session: AsyncSession = Depends(get_db),
):
    existing = await one(session, select(settings).where(settings.c.key == "quickbooks")) or {}
    environment = (payload.environment or "sandbox").strip().lower()
    if environment not in {"sandbox", "production"}:
        raise HTTPException(status_code=400, detail="Invalid QuickBooks environment")
    values = {
        "key": "quickbooks",
        "quickbooks_enabled": bool(payload.enabled),
        "quickbooks_client_id": (payload.client_id or existing.get("quickbooks_client_id") or "").strip(),
        "quickbooks_environment": environment,
        "quickbooks_redirect_uri": (payload.redirect_uri or "").strip(),
    }
    if payload.client_secret:
        values["quickbooks_client_secret_enc"] = encrypt_secret(payload.client_secret.strip())
    elif existing.get("quickbooks_client_secret_enc"):
        values["quickbooks_client_secret_enc"] = existing["quickbooks_client_secret_enc"]
    else:
        values["quickbooks_client_secret_enc"] = None
    if existing:
        await session.execute(update(settings).where(settings.c.key == "quickbooks").values(**values))
    else:
        await session.execute(insert(settings).values(**values))
    await session.commit()
    creds = await get_quickbooks_credentials(session)
    return {
        "configured": creds["configured"],
        "enabled": creds["enabled"],
        "environment": creds["environment"],
        "redirect_uri": creds["redirect_uri"],
        "source": creds["source"],
        "client_id_saved": bool(creds["client_id"]),
        "client_secret_saved": bool(creds["client_secret"]),
    }


