@api.get("/admin/integrations/clients/{client_id}/quickbooks/connect")
async def start_quickbooks_connect(
    client_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    await get_client_or_404(session, client_id)
    creds = await get_quickbooks_credentials(session)
    if not creds["enabled"]:
        raise HTTPException(status_code=403, detail="Accounting software integration is disabled")
    if not creds["configured"]:
        raise HTTPException(status_code=400, detail="QuickBooks OAuth is not configured. Add QUICKBOOKS_CLIENT_ID and QUICKBOOKS_CLIENT_SECRET to the API environment.")
    params = {
        "client_id": creds["client_id"],
        "scope": QUICKBOOKS_SCOPE,
        "redirect_uri": creds["redirect_uri"],
        "response_type": "code",
        "state": create_quickbooks_state(client_id),
    }
    return {"auth_url": f"{QUICKBOOKS_AUTH_URL}?{urlencode(params)}"}


@api.get("/integrations/quickbooks/callback")
async def quickbooks_oauth_callback(
    code: Optional[str] = None,
    state: Optional[str] = None,
    realmId: Optional[str] = None,
    error: Optional[str] = None,
    error_description: Optional[str] = None,
    session: AsyncSession = Depends(get_db),
):
    frontend_url = os.environ.get("FRONTEND_URL", "http://localhost:3000").rstrip("/")
    if error:
        return RedirectResponse(f"{frontend_url}/admin/integrations?quickbooks=error&message={urlencode({'m': error_description or error})[2:]}")
    if not code or not state or not realmId:
        return RedirectResponse(f"{frontend_url}/admin/integrations?quickbooks=missing")
    client_id = verify_quickbooks_state(state)
    await get_client_or_404(session, client_id)
    creds = await get_quickbooks_credentials(session)
    if not creds["enabled"]:
        return RedirectResponse(f"{frontend_url}/admin/clients/{client_id}?quickbooks=error&message=Accounting%20software%20integration%20is%20disabled")
    token_data = await exchange_quickbooks_code(session, code, creds["redirect_uri"])
    now = datetime.now(timezone.utc)
    values = {
        "provider": "quickbooks",
        "status": "connected",
        "company_id": realmId,
        "sandbox": creds["environment"] == "sandbox",
        "access_token_enc": encrypt_secret(token_data.get("access_token")),
        "refresh_token_enc": encrypt_secret(token_data.get("refresh_token")),
        "token_expires_at": (now + timedelta(seconds=int(token_data.get("expires_in") or 3600))).isoformat(),
        "refresh_expires_at": (now + timedelta(seconds=int(token_data.get("x_refresh_token_expires_in") or 0))).isoformat()
            if token_data.get("x_refresh_token_expires_in") else None,
        "scope": token_data.get("scope") or QUICKBOOKS_SCOPE,
        "updated_at": utc_now_iso(),
    }
    existing = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    if existing:
        await session.execute(update(client_integrations).where(client_integrations.c.client_id == client_id).values(**values))
    else:
        await session.execute(insert(client_integrations).values(id=new_id(), client_id=client_id, created_at=utc_now_iso(), **values))
    await session.commit()
    try:
        await sync_quickbooks_lists_for_client(session, client_id)
        return RedirectResponse(f"{frontend_url}/admin/clients/{client_id}?quickbooks=connected&sync=ok")
    except Exception as exc:
        logger.exception("QuickBooks connected but initial sync failed for client %s", client_id)
        message = urlencode({"m": f"QuickBooks connected, but list sync failed: {str(exc)}"})[2:]
        return RedirectResponse(f"{frontend_url}/admin/clients/{client_id}?quickbooks=connected&sync=error&message={message}")


async def save_connected_provider(
    session: AsyncSession,
    client_id: str,
    provider: str,
    company_id: str,
    company_name: str,
    token_data: dict,
    environment: str,
) -> None:
    now = datetime.now(timezone.utc)
    values = {
        "provider": provider,
        "status": "connected",
        "company_id": company_id,
        "company_name": company_name,
        "sandbox": provider == "quickbooks" and environment == "sandbox",
        "access_token_enc": encrypt_secret(token_data.get("access_token")),
        "refresh_token_enc": encrypt_secret(token_data.get("refresh_token")),
        "token_expires_at": (now + timedelta(seconds=int(token_data.get("expires_in") or 1800))).isoformat(),
        "refresh_expires_at": None,
        "scope": token_data.get("scope") or INTEGRATION_PROVIDER_META[provider]["scope"],
        "last_sync_at": None,
        "updated_at": utc_now_iso(),
    }
    existing = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    await session.execute(delete(integration_records).where(integration_records.c.client_id == client_id))
    if existing:
        await session.execute(
            update(client_integrations).where(client_integrations.c.client_id == client_id).values(**values)
        )
    else:
        await session.execute(
            insert(client_integrations).values(
                id=new_id(), client_id=client_id, created_at=utc_now_iso(), **values
            )
        )
    await session.commit()


async def discover_provider_company(provider: str, access_token: str) -> dict:
    if provider == "xero":
        connections = await provider_get_json(provider, access_token, XERO_CONNECTIONS_URL)
        rows = connections if isinstance(connections, list) else []
        if not rows:
            raise HTTPException(status_code=400, detail="Xero returned no connected organisations.")
        row = rows[0]
        return {
            "id": str(row.get("tenantId") or ""),
            "name": str(row.get("tenantName") or row.get("tenantType") or "Xero organisation"),
        }
    businesses = await provider_get_json(provider, access_token, f"{SAGE_API_BASE}/businesses")
    rows = provider_collection(businesses)
    if not rows:
        raise HTTPException(status_code=400, detail="Sage returned no available businesses.")
    row = rows[0]
    return {
        "id": str(row.get("id") or row.get("resource_owner_id") or ""),
        "name": str(row.get("displayed_as") or row.get("name") or "Sage business"),
    }


@api.get("/admin/integrations/clients/{client_id}/{provider}/connect")
async def start_accounting_provider_connect(
    client_id: str,
    provider: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    provider = clean_provider(provider)
    await get_client_or_404(session, client_id)
    credentials = await get_provider_credentials(provider, session)
    if not credentials["enabled"]:
        raise HTTPException(status_code=403, detail=f"{credentials['label']} integration is disabled.")
    if not credentials["configured"]:
        raise HTTPException(status_code=400, detail=f"{credentials['label']} OAuth app credentials are not configured.")
    existing = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    if not existing or existing.get("provider") != provider:
        raise HTTPException(status_code=409, detail=f"Save {credentials['label']} as this client's selected software before connecting.")
    params = {
        "client_id": credentials["client_id"],
        "scope": credentials["scope"],
        "redirect_uri": credentials["redirect_uri"],
        "response_type": "code",
        "state": create_provider_oauth_state(client_id, provider),
    }
    if provider == "sage":
        params["filter"] = "apiv3.1"
    return {"provider": provider, "auth_url": f"{INTEGRATION_PROVIDER_META[provider]['auth_url']}?{urlencode(params)}"}


@api.get("/integrations/{provider}/callback")
async def accounting_provider_oauth_callback(
    provider: str,
    code: Optional[str] = None,
    state: Optional[str] = None,
    error: Optional[str] = None,
    error_description: Optional[str] = None,
    session: AsyncSession = Depends(get_db),
):
    provider = clean_provider(provider)
    frontend_url = os.environ.get("FRONTEND_URL", "http://localhost:3000").rstrip("/")
    label = INTEGRATION_PROVIDER_META[provider]["label"]
    if error:
        message = urlencode({"m": error_description or error})[2:]
        callback_path = "/admin/integrations"
        if state:
            try:
                callback_path = f"/admin/clients/{verify_provider_oauth_state(state, provider)}"
            except HTTPException:
                pass
        return RedirectResponse(
            f"{frontend_url}{callback_path}?provider={provider}&connection=error&message={message}"
        )
    if not code or not state:
        return RedirectResponse(f"{frontend_url}/admin/integrations?provider={provider}&connection=missing")
    client_id = verify_provider_oauth_state(state, provider)
    await get_client_or_404(session, client_id)
    credentials = await get_provider_credentials(provider, session)
    if not credentials["enabled"]:
        return RedirectResponse(
            f"{frontend_url}/admin/clients/{client_id}?provider={provider}&connection=error&message=Integration%20is%20disabled"
        )
    try:
        token_data = await exchange_provider_code(session, provider, code, credentials["redirect_uri"])
        company = await discover_provider_company(provider, str(token_data.get("access_token") or ""))
        if not company["id"]:
            raise HTTPException(status_code=400, detail=f"{label} did not return a company identifier.")
        await save_connected_provider(
            session,
            client_id,
            provider,
            company["id"],
            company["name"],
            token_data,
            credentials["environment"],
        )
    except Exception as exc:
        logger.exception("%s connection failed for client %s", label, client_id)
        detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
        message = urlencode({"m": f"{label} connection failed: {detail}"})[2:]
        return RedirectResponse(
            f"{frontend_url}/admin/clients/{client_id}?provider={provider}&connection=error&message={message}"
        )
    try:
        await sync_provider_lists_for_client(session, client_id, provider)
        return RedirectResponse(
            f"{frontend_url}/admin/clients/{client_id}?provider={provider}&connection=connected&sync=ok"
        )
    except Exception as exc:
        logger.exception("%s connected but initial sync failed for client %s", label, client_id)
        detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
        message = urlencode({"m": f"{label} connected, but list sync failed: {detail}"})[2:]
        return RedirectResponse(
            f"{frontend_url}/admin/clients/{client_id}?provider={provider}&connection=connected&sync=error&message={message}"
        )


async def replace_integration_records(session: AsyncSession, client_id: str, provider: str, record_type: str, records: list[dict]):
    now = utc_now_iso()
    await session.execute(
        delete(integration_records).where(
            integration_records.c.client_id == client_id,
            integration_records.c.provider == provider,
            integration_records.c.record_type == record_type,
        )
    )
    if records:
        await session.execute(insert(integration_records), [
            {
                "id": new_id(),
                "client_id": client_id,
                "provider": provider,
                "record_type": record_type,
                "external_id": record.get("external_id") or "",
                "code": record.get("code") or "",
                "name": record.get("name") or "",
                "email": record.get("email") or None,
                "description": record.get("description") or "",
                "active": bool(record.get("active", True)),
                "raw_json": json.dumps(record.get("raw") or {}),
                "created_at": now,
                "updated_at": now,
            }
            for record in records
            if record.get("name")
        ])


async def sync_quickbooks_lists_for_client(session: AsyncSession, client_id: str) -> dict:
    await get_client_or_404(session, client_id)
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    if not integration or integration.get("provider") != "quickbooks" or not integration.get("company_id"):
        raise HTTPException(status_code=400, detail="QuickBooks is not connected for this client")
    access_token = await get_valid_quickbooks_access_token(session, integration)
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    environment = "sandbox" if integration.get("sandbox") else "production"
    realm_id = integration["company_id"]

    try:
        accounts_response = await quickbooks_query(access_token, realm_id, environment, "SELECT * FROM Account MAXRESULTS 1000")
    except HTTPException as exc:
        detail = str(exc.detail or "")
        if "ApplicationAuthorizationFailed" not in detail and "003100" not in detail:
            raise
        alternate_environment = "production" if environment == "sandbox" else "sandbox"
        logger.warning(
            "QuickBooks %s query failed for client %s; retrying %s",
            environment,
            client_id,
            alternate_environment,
        )
        accounts_response = await quickbooks_query(access_token, realm_id, alternate_environment, "SELECT * FROM Account MAXRESULTS 1000")
        environment = alternate_environment
        await session.execute(
            update(client_integrations)
            .where(client_integrations.c.client_id == client_id)
            .values(sandbox=environment == "sandbox", updated_at=utc_now_iso())
        )
        await session.commit()
        integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    vendors_response = await quickbooks_query(access_token, realm_id, environment, "SELECT * FROM Vendor MAXRESULTS 1000")
    customers_response = await quickbooks_query(access_token, realm_id, environment, "SELECT * FROM Customer MAXRESULTS 1000")
    company_response = await quickbooks_query(access_token, realm_id, environment, "SELECT * FROM CompanyInfo")
    sync_warnings = []
    tax_codes_response = {}
    for tax_code_query in ("SELECT * FROM TaxCode MAXRESULTS 1000", "SELECT * FROM TaxCode"):
        tax_codes_response, warning = await optional_quickbooks_query(access_token, realm_id, environment, tax_code_query)
        if warning:
            sync_warnings.append(warning)
            logger.warning("QuickBooks tax code query skipped for client %s: %s", client_id, warning)
            continue
        if tax_codes_response.get("TaxCode"):
            break
    company_info = (company_response.get("CompanyInfo") or [{}])[0] or {}

    accounts = [
        {
            "external_id": item.get("Id"),
            "code": item.get("AcctNum") or item.get("Id") or "",
            "name": item.get("Name") or item.get("FullyQualifiedName") or "",
            "description": item.get("AccountType") or item.get("Classification") or "",
            "active": item.get("Active", True),
            "raw": item,
        }
        for item in accounts_response.get("Account", []) or []
    ]
    suppliers = [
        {
            "external_id": item.get("Id"),
            "code": item.get("AcctNum") or item.get("Id") or "",
            "name": item.get("DisplayName") or item.get("CompanyName") or item.get("PrintOnCheckName") or "",
            "email": ((item.get("PrimaryEmailAddr") or {}).get("Address") if isinstance(item.get("PrimaryEmailAddr"), dict) else None),
            "description": item.get("CompanyName") or "",
            "active": item.get("Active", True),
            "raw": item,
        }
        for item in vendors_response.get("Vendor", []) or []
    ]
    customers = [
        {
            "external_id": item.get("Id"),
            "code": item.get("Id") or "",
            "name": item.get("DisplayName") or item.get("CompanyName") or item.get("FullyQualifiedName") or "",
            "email": ((item.get("PrimaryEmailAddr") or {}).get("Address") if isinstance(item.get("PrimaryEmailAddr"), dict) else None),
            "description": item.get("CompanyName") or "",
            "active": item.get("Active", True),
            "raw": item,
        }
        for item in customers_response.get("Customer", []) or []
    ]
    tax_codes = [
        {
            "external_id": item.get("Id"),
            "code": item.get("Name") or item.get("Id") or "",
            "name": item.get("Name") or item.get("Description") or item.get("Id") or "",
            "description": item.get("Description") or ("Taxable" if item.get("Taxable") else "Non-taxable"),
            "active": item.get("Active", True),
            "raw": item,
        }
        for item in tax_codes_response.get("TaxCode", []) or []
    ]
    if not tax_codes:
        tax_rates_response = {}
        for tax_rate_query in ("SELECT * FROM TaxRate MAXRESULTS 1000", "SELECT * FROM TaxRate"):
            tax_rates_response, warning = await optional_quickbooks_query(access_token, realm_id, environment, tax_rate_query)
            if warning:
                sync_warnings.append(warning)
                logger.warning("QuickBooks tax rate query skipped for client %s: %s", client_id, warning)
                continue
            if tax_rates_response.get("TaxRate"):
                break
        sync_warnings.append("QuickBooks returned no TaxCode rows, so TaxRate rows were used as a fallback.")
        existing_tax_names = set()
        for item in tax_rates_response.get("TaxRate", []) or []:
            rate_name = item.get("Name") or item.get("Description") or item.get("Id") or ""
            if not rate_name or rate_name.strip().lower() in existing_tax_names:
                continue
            rate_value = item.get("RateValue")
            rate_label = f"{rate_name} ({rate_value}%)" if rate_value not in (None, "") else rate_name
            tax_codes.append({
                "external_id": item.get("Id"),
                "code": rate_name,
                "name": rate_label,
                "description": item.get("Description") or "QuickBooks tax rate",
                "active": item.get("Active", True),
                "raw": item,
            })
            existing_tax_names.add(rate_name.strip().lower())

    await replace_integration_records(session, client_id, "quickbooks", "account", accounts)
    await replace_integration_records(session, client_id, "quickbooks", "supplier", suppliers)
    await replace_integration_records(session, client_id, "quickbooks", "customer", customers)
    await replace_integration_records(session, client_id, "quickbooks", "tax_code", tax_codes)
    company_name = (
        company_info.get("CompanyName")
        or company_info.get("LegalName")
        or company_info.get("Name")
        or integration.get("company_name")
        or ""
    )
    await session.execute(
        update(client_integrations)
        .where(client_integrations.c.client_id == client_id)
        .values(status="connected", company_name=company_name, last_sync_at=utc_now_iso(), updated_at=utc_now_iso())
    )
    await session.commit()
    if not tax_codes:
        sync_warnings.append("QuickBooks returned 0 VAT/tax codes. Check the connected company VAT/tax setup and whether it exposes TaxCode or TaxRate records through the API.")
    return {
        "ok": True,
        "counts": {"account": len(accounts), "supplier": len(suppliers), "customer": len(customers), "tax_code": len(tax_codes)},
        "company_name": company_name,
        "warnings": sync_warnings[:6],
    }


@api.post("/admin/integrations/clients/{client_id}/quickbooks/sync")
async def sync_quickbooks_lists(
    client_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    creds = await get_quickbooks_credentials(session)
    if not creds["enabled"]:
        raise HTTPException(status_code=403, detail="Accounting software integration is disabled")
    return await sync_quickbooks_lists_for_client(session, client_id)


def provider_collection(payload: dict | list, *keys: str) -> list[dict]:
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    if not isinstance(payload, dict):
        return []
    for key in (*keys, "$items", "items"):
        value = payload.get(key)
        if isinstance(value, list):
            return [item for item in value if isinstance(item, dict)]
    return []


async def sage_collection_pages(
    access_token: str,
    company_id: str,
    endpoint: str,
    *,
    items_per_page: int = 200,
) -> list[dict]:
    rows: list[dict] = []
    for page in range(1, 101):
        payload = await provider_get_json(
            "sage",
            access_token,
            f"{SAGE_API_BASE}/{endpoint}",
            company_id,
            {"items_per_page": items_per_page, "page": page},
        )
        batch = provider_collection(payload)
        rows.extend(batch)
        next_page = payload.get("$next") if isinstance(payload, dict) else None
        if not next_page and len(batch) < items_per_page:
            break
    return rows


async def sync_xero_lists_for_client(session: AsyncSession, client_id: str, integration: dict, access_token: str) -> dict:
    tenant_id = str(integration.get("company_id") or "")
    accounts_payload, tax_payload, organisation_payload = await asyncio.gather(
        provider_get_json("xero", access_token, f"{XERO_API_BASE}/Accounts", tenant_id),
        provider_get_json("xero", access_token, f"{XERO_API_BASE}/TaxRates", tenant_id),
        provider_get_json("xero", access_token, f"{XERO_API_BASE}/Organisation", tenant_id),
    )
    contacts = []
    for page in range(1, 101):
        payload = await provider_get_json(
            "xero",
            access_token,
            f"{XERO_API_BASE}/Contacts",
            tenant_id,
            {"page": page, "pageSize": 100},
        )
        batch = provider_collection(payload, "Contacts")
        contacts.extend(batch)
        if len(batch) < 100:
            break
    accounts = [{
        "external_id": item.get("AccountID"),
        "code": item.get("Code") or item.get("AccountID") or "",
        "name": item.get("Name") or "",
        "description": item.get("Description") or item.get("Type") or "",
        "active": item.get("Status") != "ARCHIVED",
        "raw": item,
    } for item in provider_collection(accounts_payload, "Accounts")]
    contact_rows = [{
        "external_id": item.get("ContactID"),
        "code": item.get("ContactNumber") or item.get("AccountNumber") or item.get("ContactID") or "",
        "name": item.get("Name") or " ".join(filter(None, [item.get("FirstName"), item.get("LastName")])),
        "email": item.get("EmailAddress"),
        "description": item.get("CompanyNumber") or "",
        "active": item.get("ContactStatus") != "ARCHIVED",
        "raw": item,
    } for item in contacts]
    suppliers = [row for row, item in zip(contact_rows, contacts) if bool(item.get("IsSupplier"))]
    customers = [row for row, item in zip(contact_rows, contacts) if bool(item.get("IsCustomer"))]
    tax_codes = [{
        "external_id": item.get("TaxType"),
        "code": item.get("TaxType") or item.get("Name") or "",
        "name": item.get("Name") or item.get("TaxType") or "",
        "description": f"{item.get('EffectiveRate', item.get('DisplayTaxRate', 0))}% · {item.get('ReportTaxType') or 'VAT'}",
        "active": item.get("Status") != "DELETED",
        "raw": item,
    } for item in provider_collection(tax_payload, "TaxRates")]
    organisations = provider_collection(organisation_payload, "Organisations")
    company_name = str((organisations[0] if organisations else {}).get("Name") or integration.get("company_name") or "")
    for record_type, rows in (("account", accounts), ("supplier", suppliers), ("customer", customers), ("tax_code", tax_codes)):
        await replace_integration_records(session, client_id, "xero", record_type, rows)
    return {
        "counts": {"account": len(accounts), "supplier": len(suppliers), "customer": len(customers), "tax_code": len(tax_codes)},
        "company_name": company_name,
        "warnings": [],
    }


def sage_contact_is_type(item: dict, expected: str) -> bool:
    expected = expected.upper()
    contact_types = item.get("contact_types") or item.get("types") or []
    values = {
        str(value.get("id") or value.get("key") or value.get("displayed_as") or "").upper()
        for value in contact_types
        if isinstance(value, dict)
    }
    values.add(str(item.get("contact_type_id") or "").upper())
    return expected in values or ("SUPPLIER" in values if expected == "VENDOR" else False)


async def sync_sage_lists_for_client(session: AsyncSession, client_id: str, integration: dict, access_token: str) -> dict:
    business_id = str(integration.get("company_id") or "")
    account_items, contact_items, tax_items, businesses_payload = await asyncio.gather(
        sage_collection_pages(access_token, business_id, "ledger_accounts"),
        sage_collection_pages(access_token, business_id, "contacts"),
        sage_collection_pages(access_token, business_id, "tax_rates"),
        provider_get_json("sage", access_token, f"{SAGE_API_BASE}/businesses"),
    )
    accounts = [{
        "external_id": item.get("id"),
        "code": item.get("nominal_code") or item.get("code") or item.get("id") or "",
        "name": item.get("displayed_as") or item.get("name") or "",
        "description": (item.get("ledger_account_type") or {}).get("displayed_as") if isinstance(item.get("ledger_account_type"), dict) else "",
        "active": not bool(item.get("deleted_at")),
        "raw": item,
    } for item in account_items]
    contact_rows = [{
        "external_id": item.get("id"),
        "code": item.get("reference") or item.get("id") or "",
        "name": item.get("displayed_as") or item.get("name") or "",
        "email": item.get("email"),
        "description": item.get("tax_number") or "",
        "active": not bool(item.get("deleted_at")),
        "raw": item,
    } for item in contact_items]
    suppliers = [row for row, item in zip(contact_rows, contact_items) if sage_contact_is_type(item, "VENDOR")]
    customers = [row for row, item in zip(contact_rows, contact_items) if sage_contact_is_type(item, "CUSTOMER")]
    tax_codes = [{
        "external_id": item.get("id"),
        "code": item.get("id") or item.get("displayed_as") or "",
        "name": item.get("displayed_as") or item.get("name") or "",
        "description": f"{item.get('percentage', 0)}% · {item.get('usage') or 'VAT'}",
        "active": not bool(item.get("deleted_at")),
        "raw": item,
    } for item in tax_items]
    businesses = provider_collection(businesses_payload)
    selected = next((item for item in businesses if str(item.get("id")) == business_id), businesses[0] if businesses else {})
    company_name = str(selected.get("displayed_as") or selected.get("name") or integration.get("company_name") or "")
    warnings = []
    if contact_items and not suppliers and not customers:
        warnings.append("Sage returned contacts without customer/supplier type flags. Check contact permissions in the connected business.")
    for record_type, rows in (("account", accounts), ("supplier", suppliers), ("customer", customers), ("tax_code", tax_codes)):
        await replace_integration_records(session, client_id, "sage", record_type, rows)
    return {
        "counts": {"account": len(accounts), "supplier": len(suppliers), "customer": len(customers), "tax_code": len(tax_codes)},
        "company_name": company_name,
        "warnings": warnings,
    }


async def sync_provider_lists_for_client(session: AsyncSession, client_id: str, provider: Optional[str] = None) -> dict:
    await get_client_or_404(session, client_id)
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    if not integration:
        raise HTTPException(status_code=400, detail="No external accounting software is selected for this client.")
    selected_provider = clean_provider(provider or str(integration.get("provider") or ""))
    if integration.get("provider") != selected_provider or integration.get("status") != "connected" or not integration.get("company_id"):
        raise HTTPException(status_code=400, detail=f"{INTEGRATION_PROVIDER_META[selected_provider]['label']} is not connected for this client.")
    credentials = await get_provider_credentials(selected_provider, session)
    if not credentials["enabled"]:
        raise HTTPException(status_code=403, detail=f"{credentials['label']} integration is disabled.")
    if selected_provider == "quickbooks":
        return await sync_quickbooks_lists_for_client(session, client_id)
    access_token = await get_valid_provider_access_token(session, integration)
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    result = (
        await sync_xero_lists_for_client(session, client_id, integration, access_token)
        if selected_provider == "xero"
        else await sync_sage_lists_for_client(session, client_id, integration, access_token)
    )
    await session.execute(
        update(client_integrations)
        .where(client_integrations.c.client_id == client_id)
        .values(
            status="connected",
            company_name=result.get("company_name") or integration.get("company_name"),
            last_sync_at=utc_now_iso(),
            updated_at=utc_now_iso(),
        )
    )
    await session.commit()
    return {"ok": True, **result}


@api.post("/admin/integrations/clients/{client_id}/{provider}/sync")
async def sync_accounting_provider_lists(
    client_id: str,
    provider: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    return await sync_provider_lists_for_client(session, client_id, clean_provider(provider))


async def get_active_integration_records(session: AsyncSession, client_id: str, record_type: str) -> list[dict]:
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    provider = clean_provider(str((integration or {}).get("provider") or "quickbooks"))
    return await many(
        session,
        select(integration_records)
        .where(integration_records.c.client_id == client_id)
        .where(integration_records.c.provider == provider)
        .where(integration_records.c.record_type == record_type)
        .where(integration_records.c.active == True),  # noqa: E712
    )


def normalize_lookup_value(value: Optional[str]) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).lower()


def record_matches_value(record: dict, value: str) -> bool:
    needle = normalize_lookup_value(value)
    if not needle:
        return False
    raw = parse_json_object(record.get("raw_json")) or {}
    candidates = [
        record.get("external_id"),
        record.get("code"),
        record.get("name"),
        " - ".join([part for part in (record.get("code"), record.get("name")) if part]),
        " - ".join([part for part in (record.get("code"), record.get("name"), record.get("description")) if part]),
        raw.get("DisplayName"),
        raw.get("FullyQualifiedName"),
        raw.get("CompanyName"),
        raw.get("Name"),
    ]
    return any(normalize_lookup_value(candidate) == needle for candidate in candidates if candidate)


def find_integration_record(records: list[dict], value: Optional[str]) -> Optional[dict]:
    if not value:
        return None
    exact = [record for record in records if record_matches_value(record, value)]
    if exact:
        return exact[0]
    needle = normalize_lookup_value(value)
    for record in records:
        if needle and needle in normalize_lookup_value(record.get("name")):
            return record
    return None


def find_supplier_record(records: list[dict], vendor_name: Optional[str], vendor_account: Optional[str]) -> Optional[dict]:
    supplier = find_integration_record(records, vendor_name)
    if supplier:
        return supplier
    account_value = str(vendor_account or "").strip()
    # Bare numeric ids are too easy to confuse with an unrelated supplier. Only
    # trust the account field when it carries a display label from the synced list.
    if " - " in account_value:
        return find_integration_record(records, account_value)
    return None


def quickbooks_date(value: Optional[str]) -> Optional[str]:
    text_value = str(value or "").strip()
    if not text_value:
        return None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%d %b %Y", "%d %B %Y"):
        try:
            return datetime.strptime(text_value, fmt).date().isoformat()
        except ValueError:
            continue
    return None


def quickbooks_amount(value: Optional[str]) -> Optional[float]:
    parsed = parse_money_value(str(value or ""))
    return round(parsed, 2) if parsed is not None else None


def quickbooks_ref(record: dict) -> dict:
    return {"value": str(record["external_id"]), "name": record.get("name") or record.get("code") or str(record["external_id"])}


def require_account_match(accounts: list[dict], value: Optional[str], field_label: str) -> Optional[dict]:
    text_value = str(value or "").strip()
    if not text_value:
        return None
    account = find_integration_record(accounts, text_value)
    if not account or not account.get("external_id"):
        raise HTTPException(status_code=400, detail=f"Select a synced QuickBooks {field_label}. AI suggested '{text_value}', but it is not in the synced Chart of Accounts.")
    return account


def optional_tax_match(tax_codes: list[dict], value: Optional[str]) -> Optional[dict]:
    text_value = str(value or "").strip()
    if not text_value:
        return None
    tax = find_integration_record(tax_codes, text_value)
    if not tax or not tax.get("external_id"):
        raise HTTPException(status_code=400, detail=f"Select a synced QuickBooks VAT code. AI suggested '{text_value}', but it is not in the synced VAT code list.")
    return tax


async def create_quickbooks_supplier(
    session: AsyncSession,
    access_token: str,
    realm_id: str,
    environment: str,
    client_id: str,
    vendor_name: str,
    supplier_code: Optional[str] = None,
    existing_record: Optional[dict] = None,
) -> dict:
    clean_name = re.sub(r"\s+", " ", str(vendor_name or "").strip())
    if not clean_name:
        raise HTTPException(status_code=400, detail="Supplier name is required before publishing.")
    payload = {
        "DisplayName": clean_name[:100],
        "CompanyName": clean_name[:100],
    }
    clean_code = re.sub(r"\s+", " ", str(supplier_code or "").strip())
    if clean_code:
        payload["AcctNum"] = clean_code[:100]
    vendor = await quickbooks_post(access_token, realm_id, environment, "Vendor", payload)
    now = utc_now_iso()
    raw_json = json.dumps(vendor)
    values = {
        "external_id": str(vendor.get("Id") or ""),
        "code": clean_code or str(vendor.get("AcctNum") or vendor.get("Id") or ""),
        "name": vendor.get("DisplayName") or vendor.get("CompanyName") or clean_name,
        "description": vendor.get("CompanyName") or "",
        "active": vendor.get("Active", True),
        "raw_json": raw_json,
        "updated_at": now,
    }
    if existing_record and existing_record.get("id"):
        await session.execute(update(integration_records).where(integration_records.c.id == existing_record["id"]).values(**values))
        return {**existing_record, **values}
    record = {
        "id": new_id(),
        "client_id": client_id,
        "provider": "quickbooks",
        "record_type": "supplier",
        "email": None,
        "created_at": now,
        **values,
    }
    await session.execute(insert(integration_records).values(**record))
    return record


def build_quickbooks_bill_lines(coding_fields: dict, accounts: list[dict], tax_codes: list[dict], header_account: dict, header_tax: Optional[dict]) -> list[dict]:
    source_lines = coding_fields.get("line_items")
    if not isinstance(source_lines, list) or not source_lines:
        source_lines = [{
            "description": coding_fields.get("description") or "",
            "category": coding_fields.get("category") or "",
            "vat_code": coding_fields.get("vat_code") or "",
            "net": coding_fields.get("net") or coding_fields.get("total") or "",
            "total": coding_fields.get("total") or coding_fields.get("net") or "",
        }]

    lines = []
    for line in source_lines:
        if not isinstance(line, dict):
            continue
        amount = quickbooks_amount(line.get("net"))
        if amount is None:
            amount = quickbooks_amount(line.get("total"))
        if amount is None:
            continue
        account = require_account_match(accounts, line.get("category"), "line category/account") or header_account
        tax = optional_tax_match(tax_codes, line.get("vat_code")) or header_tax
        detail = {"AccountRef": quickbooks_ref(account)}
        if tax and tax.get("external_id"):
            detail["TaxCodeRef"] = {"value": str(tax["external_id"]), "name": tax.get("name") or tax.get("code") or str(tax["external_id"])}
        lines.append({
            "DetailType": "AccountBasedExpenseLineDetail",
            "Amount": amount,
            "Description": str(line.get("description") or coding_fields.get("description") or "Purchase")[:4000],
            "AccountBasedExpenseLineDetail": detail,
        })
    return lines


async def attach_submission_file_to_quickbooks(access_token: str, realm_id: str, environment: str, filename: str, entity_type: str, entity_id: str) -> dict:
    safe_name = Path(filename).name
    file_path = UPLOAD_DIR / safe_name
    if not file_path.exists():
        raise HTTPException(status_code=400, detail="The submitted document file could not be found for attachment.")
    content_type = mimetypes.guess_type(safe_name)[0] or "application/octet-stream"
    metadata_payload = {
        "AttachableRef": [{"EntityRef": {"type": entity_type, "value": entity_id}}],
        "FileName": safe_name,
        "ContentType": content_type,
    }
    url = f"{quickbooks_api_base(environment)}/v3/company/{realm_id}/upload"
    with file_path.open("rb") as fh:
        files = {
            "file_metadata_0": ("metadata.json", json.dumps(metadata_payload), "application/json"),
            "file_content_0": (safe_name, fh, content_type),
        }
        async with httpx.AsyncClient(timeout=60) as client:
            resp = await client.post(
                url,
                params={"minorversion": "75"},
                headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},
                files=files,
            )
    if resp.status_code >= 400:
        logger.error("QuickBooks attachment upload failed: %s %s", resp.status_code, resp.text[:1000])
        raise HTTPException(status_code=400, detail=f"QuickBooks created the bill but rejected the attachment: {quickbooks_error_message(resp.text)}")
    data = resp.json()
    attachables = data.get("AttachableResponse") or data.get("Attachable") or []
    if isinstance(attachables, list) and attachables:
        return attachables[0].get("Attachable") or attachables[0]
    return data


async def publish_submission_to_quickbooks(session: AsyncSession, submission: dict, coding_fields: dict) -> dict:
    if submission.get("type") != "purchase":
        raise HTTPException(status_code=400, detail="QuickBooks publishing is ready for purchase bills first. Sales invoices need product/service item mapping before they can be published safely.")

    client_id = str(submission["client_id"])
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    if not integration or integration.get("provider") != "quickbooks" or not integration.get("company_id"):
        raise HTTPException(status_code=400, detail="Connect this client to QuickBooks before publishing.")
    if integration.get("status") != "connected":
        raise HTTPException(status_code=400, detail="QuickBooks is not connected for this client.")

    suppliers = await get_active_integration_records(session, client_id, "supplier")
    accounts = await get_active_integration_records(session, client_id, "account")
    tax_codes = await get_active_integration_records(session, client_id, "tax_code")

    environment = "sandbox" if integration.get("sandbox") else "production"
    realm_id = integration["company_id"]
    access_token = await get_valid_quickbooks_access_token(session, integration)
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))

    supplier = find_supplier_record(suppliers, coding_fields.get("vendor_name"), coding_fields.get("vendor_account"))
    if not supplier or not supplier.get("external_id"):
        raise HTTPException(status_code=400, detail="Select a synced QuickBooks supplier, or click Create missing supplier before publishing.")

    default_account = integration.get("default_purchase_account") or ""
    header_category_value = str(coding_fields.get("category") or "").strip()
    header_account = require_account_match(accounts, header_category_value, "category/account") if header_category_value else None
    if not header_account and default_account:
        header_account = find_integration_record(accounts, default_account)
    if not header_account:
        raise HTTPException(status_code=400, detail="Select a QuickBooks category/account before publishing.")

    header_vat_value = str(coding_fields.get("vat_code") or "").strip()
    header_tax = optional_tax_match(tax_codes, header_vat_value) if header_vat_value else None
    if not header_tax and integration.get("default_vat_code"):
        header_tax = find_integration_record(tax_codes, integration.get("default_vat_code") or "")
    lines = build_quickbooks_bill_lines(coding_fields, accounts, tax_codes, header_account, header_tax)
    if not lines:
        raise HTTPException(status_code=400, detail="Add at least one line with a net or total amount before publishing.")

    payload = {
        "VendorRef": quickbooks_ref(supplier),
        "Line": lines,
        "PrivateNote": str(coding_fields.get("reference") or submission.get("comment") or "")[:4000],
    }
    doc_number = str(coding_fields.get("bill_number") or "").strip()
    if doc_number:
        payload["DocNumber"] = doc_number[:21]
    txn_date = quickbooks_date(coding_fields.get("date") or submission.get("date"))
    if txn_date:
        payload["TxnDate"] = txn_date
    due_date = quickbooks_date(coding_fields.get("due_date"))
    if due_date:
        payload["DueDate"] = due_date
    payload["GlobalTaxCalculation"] = "TaxInclusive" if str(coding_fields.get("price_is") or "").lower() == "tax inclusive" else "TaxExcluded"

    bill = await quickbooks_post(access_token, realm_id, environment, "Bill", payload)
    bill_id = str(bill.get("Id") or "")
    attachable = None
    if bill_id and submission.get("image_filename"):
        attachable = await attach_submission_file_to_quickbooks(access_token, realm_id, environment, submission.get("image_filename"), "Bill", bill_id)
    return {
        "provider": "quickbooks",
        "entity": "Bill",
        "id": bill_id,
        "doc_number": bill.get("DocNumber") or doc_number,
        "attached": bool(attachable),
        "attached_id": (attachable or {}).get("Id"),
        "synced_at": utc_now_iso(),
    }


async def publish_submission_to_native_accounting(
    session: AsyncSession,
    submission: dict,
    coding_fields: dict,
    actor_id: Optional[str] = None,
) -> dict:
    client_id = str(submission["client_id"])
    client = await get_user_by_id(session, client_id)
    if not is_native_accounting_client(client):
        raise HTTPException(status_code=400, detail="Enable EPOS native accounting on this client before publishing internally.")
    await ensure_native_accounting_client(session, client_id)
    route = submission_route(submission, coding_fields)
    if route not in {"purchase", "sales"}:
        raise HTTPException(status_code=400, detail="Classify this document before publishing.")
    is_sales = route == "sales"
    if not is_sales:
        purchase_type = str(coding_fields.get("document_type") or submission.get("document_type") or "purchase_invoice").strip().lower()
        existing_ap_invoice = await one(
            session,
            select(accounting_ap_invoices).where(
                accounting_ap_invoices.c.client_id == client_id,
                accounting_ap_invoices.c.source_submission_id == str(submission["id"]),
                accounting_ap_invoices.c.status != "void",
            ),
        )
        if existing_ap_invoice:
            return {
                "provider": "epos_native",
                "destination": "accounts_payable",
                "entity": "PurchaseInvoice",
                "id": existing_ap_invoice.get("id"),
                "reference": existing_ap_invoice.get("invoice_number"),
                "status": existing_ap_invoice.get("status"),
                "gross_amount": existing_ap_invoice.get("gross_amount"),
                "outstanding_amount": existing_ap_invoice.get("outstanding_amount"),
                "already_posted": True,
            }
        line_items = coding_fields.get("line_items") if isinstance(coding_fields.get("line_items"), list) else []
        line_items = submission_lines_with_single_line_header_fallback(
            coding_fields,
            line_items,
            first_present(coding_fields, "nominal_account_code", "purchase_nominal_account_code", "purchase_account_code", "account_code", "category_code", "category") or "5000",
        )
        supplier_id = str(coding_fields.get("supplier_id") or "").strip()
        supplier_name = str(coding_fields.get("vendor_name") or coding_fields.get("supplier_name") or "").strip()
        if not supplier_id:
            if bool(coding_fields.get("create_new_supplier")):
                supplier = await create_native_ap_supplier_profile(
                    session,
                    client_id,
                    {
                        "supplier_name": supplier_name,
                        "supplier_code": coding_fields.get("supplier_code") or coding_fields.get("vendor_account"),
                        "supplier_email": coding_fields.get("supplier_email"),
                        "supplier_vat_number": coding_fields.get("supplier_vat_number"),
                        "supplier_address": coding_fields.get("supplier_address"),
                        "currency": coding_fields.get("currency") or "GBP",
                        "category": coding_fields.get("category"),
                        "vat_code": coding_fields.get("vat_code"),
                    },
                    actor_id,
                )
                supplier_id = str(supplier.get("id") or "")
                coding_fields["supplier_id"] = supplier_id
                coding_fields["supplier_name"] = supplier.get("name") or supplier_name
                coding_fields["vendor_name"] = supplier.get("name") or supplier_name
                coding_fields["supplier_code"] = supplier.get("supplier_code") or supplier.get("account_code") or coding_fields.get("supplier_code") or ""
                coding_fields["create_new_supplier"] = False
                coding_fields["supplier_created_from_review"] = True
            else:
                match = await native_ap_supplier_match_suggestions(
                    session,
                    client_id,
                    {
                        "supplier_name": supplier_name,
                        "supplier_code": coding_fields.get("supplier_code") or coding_fields.get("vendor_account"),
                        "supplier_email": coding_fields.get("supplier_email"),
                        "supplier_vat_number": coding_fields.get("supplier_vat_number"),
                    },
                    limit=1,
                )
                suggestion = (match.get("suggestions") or [None])[0] if match.get("matched") else None
                if suggestion:
                    supplier_id = str(suggestion.get("id") or suggestion.get("supplier_id") or "")
                    coding_fields["supplier_id"] = supplier_id
                    coding_fields["supplier_name"] = suggestion.get("name") or supplier_name
                    coding_fields["vendor_name"] = suggestion.get("name") or supplier_name
                    coding_fields["supplier_code"] = suggestion.get("supplier_code") or coding_fields.get("supplier_code") or ""
                else:
                    raise HTTPException(status_code=400, detail="Select or create a supplier before publishing to Accounts Payable.")
        invoice_number = str(coding_fields.get("bill_number") or coding_fields.get("invoice_number") or coding_fields.get("reference") or "").strip()
        if not invoice_number:
            raise HTTPException(status_code=400, detail="Invoice number or reference is required before publishing to Accounts Payable.")
        if money(coding_fields.get("total") or coding_fields.get("gross") or coding_fields.get("net") or submission.get("amount")) == Decimal("0.00"):
            raise HTTPException(status_code=400, detail="Invoice amount is required before publishing to Accounts Payable.")
        ap_payload = {
                "supplier_name": supplier_name,
                "supplier_id": supplier_id,
                "invoice_number": invoice_number,
                "reference": coding_fields.get("reference") or "",
                "invoice_date": coding_fields.get("date") or submission.get("date"),
                "due_date": coding_fields.get("due_date") or coding_fields.get("date") or submission.get("date"),
                "currency": coding_fields.get("currency") or "GBP",
                "net_amount": coding_fields.get("net"),
                "vat_amount": coding_fields.get("vat"),
                "gross_amount": coding_fields.get("total") or coding_fields.get("gross") or submission.get("amount"),
                "vat_code": coding_fields.get("vat_code"),
                "description": coding_fields.get("description") or submission.get("description"),
                "default_location_id": coding_fields.get("default_location_id") or coding_fields.get("location_id"),
                "default_dimension_id": coding_fields.get("default_dimension_id") or coding_fields.get("dimension_id"),
                "lines": [
                    {
                        "description": line.get("description") or coding_fields.get("description") or submission.get("description"),
                        "nominal_account_code": first_present(line, "nominal_account_code", "purchase_nominal_account_code", "purchase_account_code", "account_code", "category_code", "category") or first_present(coding_fields, "nominal_account_code", "purchase_nominal_account_code", "purchase_account_code", "account_code", "category_code", "category"),
                        "quantity": line.get("units") or line.get("quantity") or "1",
                        "unit_price": line.get("price") or line.get("unit_price"),
                        "net_amount": line.get("net") or line.get("net_amount") or line.get("total"),
                        "vat_amount": line.get("vat") or line.get("vat_amount"),
                        "gross_amount": line.get("gross") or line.get("gross_amount") or line.get("total"),
                        "vat_code": first_present(line, "vat_code", "tax_code", "tax_rate_code") or first_present(coding_fields, "vat_code", "tax_code", "tax_rate_code"),
                        "location_id": line.get("location_id"),
                        "dimension_id": line.get("dimension_id"),
                    }
                    for line in line_items
                ],
                "source_submission_id": str(submission["id"]),
                "attachment_path": submission.get("image_filename") or "",
                "original_filename": submission.get("original_filename") or submission.get("image_filename") or "",
                "extracted_json": coding_fields,
                "allow_duplicate": bool(coding_fields.get("allow_duplicate")),
            }
        if purchase_type in {"supplier_credit_note", "credit_note"}:
            ap_payload = {
                **ap_payload,
                "credit_note_number": invoice_number,
                "credit_note_date": ap_payload.get("invoice_date"),
                "net_amount": money_str(abs(money(ap_payload.get("net_amount")))),
                "vat_amount": money_str(abs(money(ap_payload.get("vat_amount")))),
                "gross_amount": money_str(abs(money(ap_payload.get("gross_amount")))),
                "lines": [{**line, "net_amount": money_str(abs(money(line.get("net_amount")))), "vat_amount": money_str(abs(money(line.get("vat_amount")))), "gross_amount": money_str(abs(money(line.get("gross_amount"))))} for line in ap_payload.get("lines", [])],
            }
            credit_response = await create_ap_credit_note(client_id, ap_payload, {"id": actor_id}, session)
            ap_invoice = credit_response.get("credit_note") or credit_response.get("invoice_or_transaction") or credit_response.get("detail", {}).get("credit_note") or {}
            entity = "SupplierCreditNote"
        else:
            ap_invoice = await create_ap_invoice_record(session, client_id, ap_payload, actor_id)
            ap_settings = await ensure_ap_settings(session, client_id)
            if not bool(ap_settings.get("approval_required", True)):
                await session.flush()
                posted = await post_ap_invoice(client_id, str(ap_invoice["id"]), ap_payload, {"id": actor_id}, session)
                ap_invoice = posted.get("invoice") or posted.get("invoice_or_transaction") or ap_invoice
            entity = "PurchaseInvoice"
        return {
            "provider": "epos_native",
            "destination": "accounts_payable",
            "entity": entity,
            "id": ap_invoice.get("id"),
            "reference": ap_invoice.get("invoice_number") or ap_invoice.get("credit_note_number"),
            "status": ap_invoice.get("status"),
            "gross_amount": ap_invoice.get("gross_amount"),
            "outstanding_amount": ap_invoice.get("outstanding_amount"),
            "created_at": ap_invoice.get("created_at"),
            "lines": ap_invoice.get("lines") or ap_payload.get("lines") or [],
        }
    existing_ar_invoice = await one(
        session,
        select(accounting_ar_invoices).where(
            accounting_ar_invoices.c.client_id == client_id,
            accounting_ar_invoices.c.source_submission_id == str(submission["id"]),
            accounting_ar_invoices.c.status != "void",
        ),
    )
    if existing_ar_invoice:
        return {
            "provider": "epos_native",
            "destination": "accounts_receivable",
            "entity": "SalesInvoice",
            "id": existing_ar_invoice.get("id"),
            "reference": existing_ar_invoice.get("invoice_number"),
            "status": existing_ar_invoice.get("status"),
            "gross_amount": existing_ar_invoice.get("gross_amount"),
            "outstanding_amount": existing_ar_invoice.get("outstanding_amount"),
            "already_posted": True,
        }
    sales_fields = sales_submission_fields(submission, coding_fields)
    if not sales_fields.get("customer_id"):
        match = await sales_customer_match_suggestions(session, client_id, sales_fields, limit=1)
        suggestion = (match.get("suggestions") or [None])[0] if match.get("matched") else None
        if suggestion:
            sales_fields["customer_id"] = str(suggestion.get("id") or suggestion.get("customer_id") or "")
            coding_fields["customer_id"] = sales_fields["customer_id"]
            coding_fields["customer_name"] = suggestion.get("name") or sales_fields.get("customer_name")
            coding_fields["customer_code"] = suggestion.get("customer_code") or coding_fields.get("customer_code") or ""
        else:
            raise HTTPException(status_code=400, detail="Select or create a customer before publishing to Accounts Receivable.")
    if not sales_fields.get("invoice_number"):
        raise HTTPException(status_code=400, detail="Sales invoice number is required before publishing to Accounts Receivable.")
    if money(sales_fields.get("gross_amount")) == Decimal("0.00") and money(sales_fields.get("net_amount")) == Decimal("0.00"):
        raise HTTPException(status_code=400, detail="Add a net/gross value before publishing to Accounts Receivable.")
    native_accounts = await ensure_native_accounting_client(session, client_id)
    native_accounts_by_code = {str(account.get("code") or "").strip(): account for account in native_accounts}
    sales_codes = [str(sales_fields.get("sales_account_code") or sales_fields.get("sales_nominal_code") or "").strip(), *[str(line.get("nominal_account_code") or line.get("sales_account_code") or line.get("sales_nominal_code") or "").strip() for line in sales_fields.get("lines", [])]]
    if not sales_codes[0]:
        raise HTTPException(status_code=400, detail="Sales nominal account is required before publishing to Accounts Receivable.")
    for code in [value for value in sales_codes if value]:
        account = native_accounts_by_code.get(code)
        if not account or not bool(account.get("active", True)):
            raise HTTPException(status_code=400, detail=f"Sales nominal account '{code}' is not an active native Chart of Accounts code.")
        classification = f"{account.get('category') or ''} {account.get('account_type') or ''} {account.get('purpose') or ''}".lower()
        if not any(term in classification for term in ("income", "revenue", "sales")):
            raise HTTPException(status_code=400, detail=f"Nominal account '{code}' is not a sales/income account.")
    ar_payload = sales_submission_payload_for_ar(submission, sales_fields, bool(coding_fields.get("allow_duplicate")))
    if sales_fields.get("document_type") == "customer_credit_note":
        ar_payload = {**ar_payload, "credit_note_number": sales_fields.get("invoice_number"), "credit_note_date": sales_fields.get("invoice_date") or submission.get("date"), "net_amount": money_str(abs(money(ar_payload.get("net_amount")))), "vat_amount": money_str(abs(money(ar_payload.get("vat_amount")))), "gross_amount": money_str(abs(money(ar_payload.get("gross_amount")))), "lines": [{**line, "net_amount": money_str(abs(money(line.get("net_amount")))), "vat_amount": money_str(abs(money(line.get("vat_amount")))), "gross_amount": money_str(abs(money(line.get("gross_amount"))))} for line in ar_payload.get("lines", [])]}
        credit_response = await create_ar_credit_note(client_id, ar_payload, {"id": actor_id}, session)
        ar_invoice = credit_response.get("credit_note") or credit_response.get("invoice_or_transaction") or {}
        entity = "CustomerCreditNote"
    else:
        ar_invoice = await create_ar_invoice_record(session, client_id, ar_payload, actor_id)
        ar_settings = await ensure_ar_settings(session, client_id)
        if not bool(ar_settings.get("approval_required", True)):
            await session.flush()
            posted = await post_ar_invoice(client_id, str(ar_invoice["id"]), ar_payload, {"id": actor_id}, session)
            ar_invoice = posted.get("invoice") or posted.get("invoice_or_transaction") or ar_invoice
        entity = "SalesInvoice"
    return {
        "provider": "epos_native",
        "destination": "accounts_receivable",
        "entity": entity,
        "id": ar_invoice.get("id"),
        "reference": ar_invoice.get("invoice_number") or ar_invoice.get("credit_note_number"),
        "status": ar_invoice.get("status"),
        "gross_amount": ar_invoice.get("gross_amount"),
        "outstanding_amount": ar_invoice.get("outstanding_amount"),
        "created_at": ar_invoice.get("created_at"),
        "lines": ar_invoice.get("lines") or ar_payload.get("lines") or [],
    }


async def publish_submission_to_accounting_destination(
    session: AsyncSession,
    submission: dict,
    coding_fields: dict,
    actor_id: Optional[str] = None,
) -> dict:
    client = await get_user_by_id(session, str(submission["client_id"]))
    if is_native_accounting_client(client):
        return await publish_submission_to_native_accounting(session, submission, coding_fields, actor_id)
    return await publish_submission_to_quickbooks(session, submission, coding_fields)


@api.post("/admin/integrations/clients/{client_id}/records")
async def create_integration_record(
    client_id: str,
    payload: IntegrationRecordIn,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    await get_client_or_404(session, client_id)
    record_type = clean_record_type(payload.record_type)
    if record_type != "supplier":
        raise HTTPException(status_code=400, detail="Only missing suppliers can be created from invoice review")
    integration = await one(session, select(client_integrations).where(client_integrations.c.client_id == client_id))
    provider = clean_provider(integration.get("provider") if integration else "quickbooks")
    now = utc_now_iso()
    if (
        provider == "quickbooks"
        and integration
        and integration.get("status") == "connected"
        and integration.get("company_id")
    ):
        environment = "sandbox" if integration.get("sandbox") else "production"
        access_token = await get_valid_quickbooks_access_token(session, integration)
        record = await create_quickbooks_supplier(
            session,
            access_token,
            integration["company_id"],
            environment,
            client_id,
            payload.name,
            payload.code,
        )
        await session.commit()
        return serialize_integration_record(record)

    doc = {
        "id": new_id(),
        "client_id": client_id,
        "provider": provider,
        "record_type": record_type,
        "external_id": (payload.external_id or "").strip(),
        "code": (payload.code or "").strip(),
        "name": payload.name.strip(),
        "email": payload.email.lower().strip() if payload.email else None,
        "description": (payload.description or "").strip(),
        "active": bool(payload.active),
        "raw_json": None,
        "created_at": now,
        "updated_at": now,
    }
    if not doc["name"]:
        raise HTTPException(status_code=400, detail="Name is required")
    await session.execute(insert(integration_records).values(**doc))
    await session.commit()
    return serialize_integration_record(doc)


@api.delete("/admin/integrations/records/{record_id}")
async def delete_integration_record(
    record_id: str,
    user: dict = Depends(require_admin),
    session: AsyncSession = Depends(get_db),
):
    result = await session.execute(delete(integration_records).where(integration_records.c.id == record_id))
    if result.rowcount == 0:
        await session.rollback()
        raise HTTPException(status_code=404, detail="Integration record not found")
    await session.commit()
    return {"ok": True}


