def practice_hmrc_settings_response(row: Optional[dict]) -> dict:
    source = row or {}
    return {
        "gateway_user_id": source.get("gateway_user_id") or "",
        "gateway_password_saved": bool(source.get("gateway_password_enc")),
        "agent_services_account_id": source.get("agent_services_account_id") or "",
        "self_assessment_agent_code": source.get("self_assessment_agent_code") or "",
        "corporation_tax_agent_code": source.get("corporation_tax_agent_code") or "",
        "paye_cis_agent_reference": source.get("paye_cis_agent_reference") or "",
        "environment": source.get("environment") if source.get("environment") in {"test", "production"} else "test",
        "self_assessment_enabled": bool(source.get("self_assessment_enabled")),
        "corporation_tax_enabled": bool(source.get("corporation_tax_enabled")),
        "paye_cis_enabled": bool(source.get("paye_cis_enabled")),
        "updated_at": source.get("updated_at"),
    }


def validate_practice_hmrc_settings(payload: PracticeHmrcSettingsIn) -> None:
    if payload.environment not in {"test", "production"}:
        raise HTTPException(status_code=400, detail="HMRC environment must be test or production.")
    common_ready = bool(str(payload.gateway_user_id or "").strip())
    requirements = (
        (payload.self_assessment_enabled, payload.self_assessment_agent_code, "Self Assessment agent code"),
        (payload.corporation_tax_enabled, payload.corporation_tax_agent_code, "Corporation Tax agent code"),
        (payload.paye_cis_enabled, payload.paye_cis_agent_reference, "PAYE/CIS agent reference"),
    )
    for enabled, reference, label in requirements:
        if enabled and not common_ready:
            raise HTTPException(status_code=400, detail="Government Gateway user ID is required before enabling an HMRC service.")
        if enabled and not str(reference or "").strip():
            raise HTTPException(status_code=400, detail=f"{label} is required before enabling this service.")


