def stamp_image(image_bytes: bytes, comment: str, submitted_at: datetime) -> bytes:
    img = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    max_w = 1600
    if img.width > max_w:
        ratio = max_w / img.width
        img = img.resize((max_w, int(img.height * ratio)))

    W, H = img.size
    overlay = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)

    timestamp = submitted_at.strftime("%d %b %Y - %H:%M UTC")
    title_size = max(48, W // 18)
    body_size = max(40, W // 24)
    font_title = load_font(True, title_size)
    font_body = load_font(True, body_size)

    def wrap(text: str, font, max_width: int) -> List[str]:
        words = text.split()
        lines = []
        cur = ""
        for w in words:
            test = (cur + " " + w).strip()
            if draw.textlength(test, font=font) <= max_width:
                cur = test
            else:
                if cur:
                    lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return lines or [""]

    pad = max(28, W // 40)
    inner_w = W - 2 * pad
    comment_lines = wrap(comment or "", font_body, inner_w)
    title_h = int(title_size * 1.2)
    body_h = int(body_size * 1.35)
    gap = max(12, body_size // 2)
    block_h = pad + title_h + gap + len(comment_lines) * body_h + pad

    draw.rectangle([(0, H - block_h), (W, H)], fill=(0, 0, 0, 180))
    draw.rectangle([(pad, H - block_h + pad - 10), (pad + 90, H - block_h + pad - 4)], fill=(192, 94, 68, 235))

    y = H - block_h + pad
    draw.text((pad, y), timestamp, font=font_title, fill=(255, 255, 255, 255))
    y += title_h + gap
    for line in comment_lines:
        draw.text((pad, y), line, font=font_body, fill=(245, 245, 245, 245))
        y += body_h

    composed = Image.alpha_composite(img.convert("RGBA"), overlay).convert("RGB")
    out = io.BytesIO()
    composed.save(out, format="JPEG", quality=88)
    return out.getvalue()


def stamp_pdf(pdf_bytes: bytes, comment: str, submitted_at: datetime) -> bytes:
    from pypdf import PdfReader, PdfWriter
    from reportlab.lib.colors import Color, black
    from reportlab.pdfgen import canvas

    reader = PdfReader(io.BytesIO(pdf_bytes))
    writer = PdfWriter()
    stamp_lines = [
        "CLIENT SUBMISSION",
        f"Submitted: {submitted_at.strftime('%d %b %Y %H:%M UTC')}",
    ]
    for line in (comment or "").splitlines():
        text = line.strip()
        if text:
            stamp_lines.append(text[:120])
    stamp_lines = stamp_lines[:7]

    for page in reader.pages:
        width = float(page.mediabox.width)
        height = float(page.mediabox.height)
        packet = io.BytesIO()
        c = canvas.Canvas(packet, pagesize=(width, height))
        margin = 24
        box_height = 18 + (len(stamp_lines) * 13)
        y = margin

        c.setFillColor(Color(1, 0.97, 0.84, alpha=0.92))
        c.setStrokeColor(Color(0.84, 0.45, 0.04, alpha=0.95))
        c.roundRect(margin, y, width - (margin * 2), box_height, 6, fill=1, stroke=1)
        c.setFillColor(black)
        c.setFont("Helvetica-Bold", 9)
        line_y = y + box_height - 16
        c.drawString(margin + 10, line_y, stamp_lines[0])
        c.setFont("Helvetica", 8)
        for text in stamp_lines[1:]:
            line_y -= 13
            c.drawString(margin + 10, line_y, text)
        c.save()

        packet.seek(0)
        overlay = PdfReader(packet)
        page.merge_page(overlay.pages[0])
        writer.add_page(page)

    out = io.BytesIO()
    writer.write(out)
    return out.getvalue()


def render_submission_note_pdf(comment: str, submitted_at: datetime) -> bytes:
    from reportlab.lib.colors import HexColor
    from reportlab.lib.pagesizes import A4
    from reportlab.pdfgen import canvas

    packet = io.BytesIO()
    width, height = A4
    c = canvas.Canvas(packet, pagesize=A4)
    margin = 56
    y = height - 72

    c.setFillColor(HexColor("#172b26"))
    c.setFont("Helvetica-Bold", 22)
    c.drawString(margin, y, "Client submission note")

    y -= 34
    c.setFillColor(HexColor("#5f5a52"))
    c.setFont("Helvetica", 11)
    c.drawString(margin, y, f"Submitted: {submitted_at.strftime('%d %b %Y - %H:%M UTC')}")

    y -= 34
    c.setStrokeColor(HexColor("#c05e44"))
    c.setLineWidth(3)
    c.line(margin, y, margin + 110, y)

    y -= 42
    c.setFillColor(HexColor("#2f2b26"))
    c.setFont("Helvetica-Bold", 13)
    c.drawString(margin, y, "Comment / approval note")

    y -= 26
    c.setFont("Helvetica", 11)
    note = (comment or "(no comment provided)").strip()
    for raw_line in note.splitlines() or [note]:
        lines = textwrap.wrap(raw_line.strip(), width=88) or [""]
        for line in lines:
            if y < 70:
                c.showPage()
                y = height - 72
                c.setFillColor(HexColor("#2f2b26"))
                c.setFont("Helvetica", 11)
            c.drawString(margin, y, line)
            y -= 17
        y -= 6

    c.save()
    packet.seek(0)
    return packet.getvalue()


def append_submission_note_page(pdf_bytes: bytes, comment: str, submitted_at: datetime) -> bytes:
    from pypdf import PdfReader, PdfWriter

    writer = PdfWriter()
    original = PdfReader(io.BytesIO(pdf_bytes))
    for page in original.pages:
        writer.add_page(page)

    note_pdf = PdfReader(io.BytesIO(render_submission_note_pdf(comment, submitted_at)))
    for page in note_pdf.pages:
        writer.add_page(page)

    out = io.BytesIO()
    writer.write(out)
    return out.getvalue()


def render_image_with_note_pdf(image_bytes: bytes, comment: str, submitted_at: datetime) -> bytes:
    from reportlab.lib.colors import HexColor
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfgen import canvas

    image = ImageOps.exif_transpose(Image.open(io.BytesIO(image_bytes))).convert("RGB")
    image.thumbnail((1800, 1800))
    image_buffer = io.BytesIO()
    image.save(image_buffer, format="JPEG", quality=82, optimize=True)
    image_buffer.seek(0)

    packet = io.BytesIO()
    page_w, page_h = A4
    margin = 36
    max_w = page_w - (margin * 2)
    max_h = page_h - (margin * 2)
    scale = min(max_w / image.width, max_h / image.height)
    draw_w = image.width * scale
    draw_h = image.height * scale
    x = (page_w - draw_w) / 2
    y = (page_h - draw_h) / 2

    c = canvas.Canvas(packet, pagesize=A4)
    c.setFillColor(HexColor("#ffffff"))
    c.rect(0, 0, page_w, page_h, fill=1, stroke=0)
    c.drawImage(ImageReader(image_buffer), x, y, width=draw_w, height=draw_h)
    c.save()
    packet.seek(0)

    return append_submission_note_page(packet.getvalue(), comment, submitted_at)


def render_document_page(title: str, comment: str, submitted_at: datetime) -> bytes:
    """Render a clean white A4-style page containing the invoice description,
    the submission timestamp and the client's comment. Used when the client
    submits without a photo so an image attachment is always produced."""
    W, H = 1240, 1754  # ~A4 at 150dpi
    img = Image.new("RGB", (W, H), (255, 255, 255))
    draw = ImageDraw.Draw(img)

    try:
        font_h1 = load_font(True, 64)
        font_label = load_font(True, 30)
        font_body = load_font(False, 40)
        font_meta = load_font(False, 34)
    except Exception:
        font_h1 = font_label = font_body = font_meta = ImageFont.load_default()

    def wrap(text: str, font, max_width: int) -> List[str]:
        lines, cur = [], ""
        for w in (text or "").split():
            test = (cur + " " + w).strip()
            if draw.textlength(test, font=font) <= max_width:
                cur = test
            else:
                if cur:
                    lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
        return lines or [""]

    margin = 90
    inner_w = W - 2 * margin

    # Brand accent bar at top
    draw.rectangle([(0, 0), (W, 18)], fill=(23, 43, 38))
    draw.rectangle([(margin, 90), (margin + 120, 100)], fill=(192, 94, 68))

    y = 130
    for line in wrap(title or "Additional invoice", font_h1, inner_w):
        draw.text((margin, y), line, font=font_h1, fill=(23, 43, 38))
        y += 78

    y += 30
    draw.line([(margin, y), (W - margin, y)], fill=(220, 216, 208), width=2)
    y += 40

    draw.text((margin, y), "SUBMITTED", font=font_label, fill=(150, 145, 135))
    y += 42
    draw.text((margin, y), submitted_at.strftime("%d %b %Y · %H:%M UTC"), font=font_meta, fill=(60, 60, 60))
    y += 80

    draw.text((margin, y), "COMMENT", font=font_label, fill=(150, 145, 135))
    y += 50
    for line in wrap(comment or "(no comment provided)", font_body, inner_w):
        draw.text((margin, y), line, font=font_body, fill=(40, 40, 40))
        y += 56

    # Footer note
    draw.text((margin, H - 90), "No photo was provided — this page was generated automatically.",
              font=font_meta, fill=(170, 165, 158))

    out = io.BytesIO()
    img.save(out, format="JPEG", quality=90)
    return out.getvalue()


def upload_content_type(file: UploadFile) -> str:
    guessed, _ = mimetypes.guess_type(file.filename or "")
    return (file.content_type or guessed or "application/octet-stream").split(";")[0].lower()


def is_supported_document(file: UploadFile) -> bool:
    content_type = upload_content_type(file)
    if content_type in SUPPORTED_DOCUMENT_TYPES:
        return True
    suffix = Path(file.filename or "").suffix.lower()
    return suffix in SUPPORTED_DOCUMENT_SUFFIXES


def is_unsupported_heic_document(file: UploadFile) -> bool:
    content_type = upload_content_type(file)
    suffix = Path(file.filename or "").suffix.lower()
    return content_type in UNSUPPORTED_HEIC_TYPES or suffix in UNSUPPORTED_HEIC_SUFFIXES


def validate_supported_upload(file: UploadFile) -> None:
    if is_unsupported_heic_document(file):
        raise HTTPException(
            status_code=400,
            detail="HEIC/HEIF photos are not supported yet. Please choose Most Compatible/JPEG on your phone, or upload a JPG, PNG, WEBP or PDF.",
        )
    if not is_supported_document(file):
        raise HTTPException(status_code=400, detail="Unsupported file type. Please upload a JPG, PNG, WEBP or PDF.")


def validate_upload_size(raw: bytes) -> None:
    if not raw:
        raise HTTPException(status_code=400, detail="Empty file")
    if len(raw) > MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=400, detail="File is too large. Maximum upload size is 25 MB. Please use a smaller scan or compress the photo before uploading.")


def is_image_document(file: UploadFile) -> bool:
    content_type = upload_content_type(file)
    suffix = Path(file.filename or "").suffix.lower()
    if suffix == ".pdf" or content_type == "application/pdf":
        return False
    return content_type in SUPPORTED_IMAGE_TYPES or suffix in SUPPORTED_IMAGE_SUFFIXES


def is_pdf_document(file: UploadFile) -> bool:
    content_type = upload_content_type(file)
    suffix = Path(file.filename or "").suffix.lower()
    return content_type == "application/pdf" or suffix == ".pdf"


def upload_extension(file: UploadFile, fallback: str = ".bin") -> str:
    content_type = upload_content_type(file)
    suffix = Path(file.filename or "").suffix.lower()
    if suffix in SUPPORTED_DOCUMENT_SUFFIXES:
        return ".jpg" if suffix == ".jpeg" else suffix
    return SUPPORTED_DOCUMENT_TYPES.get(content_type, fallback)


def attachment_mime(path: str) -> tuple[str, str]:
    mime_type, _ = mimetypes.guess_type(path)
    maintype, subtype = (mime_type or "application/octet-stream").split("/", 1)
    return maintype, subtype


def write_submission_upload(raw: bytes, file: UploadFile, fpath: Path, watermark_comment: str, submitted_at: datetime) -> None:
    image_upload = is_image_document(file)
    try:
        if image_upload:
            if watermark_comment:
                with open(fpath, "wb") as f:
                    f.write(render_image_with_note_pdf(raw, watermark_comment, submitted_at))
            else:
                write_original_upload(raw, fpath)
        else:
            with open(fpath, "wb") as f:
                f.write(append_submission_note_page(raw, watermark_comment, submitted_at) if watermark_comment else raw)
    except Exception as exc:
        logger.warning("Unsupported or unreadable upload %s (%s): %s", file.filename, upload_content_type(file), exc)
        raise HTTPException(status_code=400, detail="The uploaded file could not be read. Please upload a JPG, PNG, WEBP or PDF. iPhone HEIC/HEIF photos must be converted to JPEG first.")


def write_original_upload(raw: bytes, fpath: Path) -> None:
    with open(fpath, "wb") as f:
        f.write(raw)


def bounded_text(value: Optional[str], limit: int) -> str:
    return str(value or "")[:limit]


def verified_ai_warning_review(user: dict, raw: Optional[bytes], ai_review_token: Optional[str], client_approved_ai_warning: bool) -> Optional[dict]:
    if not client_approved_ai_warning or not ai_review_token or not raw:
        return None
    try:
        review = verify_ai_review_token(ai_review_token, str(user["id"]), hashlib.sha256(raw).hexdigest())
        if not review:
            logger.warning("Client-approved AI warning token did not verify for user %s", user.get("id"))
        return review
    except Exception:
        logger.exception("Failed to verify client-approved AI warning token")
        return None


def client_approved_warning_note(comment: str, accepted_ai_review: Optional[dict], approved: bool) -> str:
    lines = []
    if comment and comment.strip():
        lines.append(comment.strip())
    if approved:
        message = str((accepted_ai_review or {}).get("message") or "AI warning accepted by client.").strip()
        lines.append(f"Client approved AI warning: {message}")
    return "\n".join(lines)


async def run_pre_submission_ai_review(
    session: AsyncSession,
    user: dict,
    item: dict,
    raw: bytes,
    file: UploadFile,
    correlation_id: str = "",
) -> dict:
    try:
        ai_settings = await get_openai_runtime_settings(session)
        coding_history = await get_coding_history(session, str(user["id"]), item["type"])
        coding_choices = await get_submitted_items_coding_context(session, str(user["id"]), item["type"], item.get("date"))
        return await review_document_with_openai(
            raw,
            upload_content_type(file),
            item,
            user,
            ai_settings["api_key"],
            ai_settings["model"],
            file.filename,
            coding_history,
            coding_choices,
        )
    except HTTPException:
        raise
    except Exception:
        logger.exception("Pre-submission AI review failed correlation_id=%s upload=%s", correlation_id, upload_log_context(file, raw))
        raise HTTPException(status_code=400, detail="The uploaded document could not be reviewed. Please try a PDF/JPG scan or contact the practice.")


def save_submission_upload_with_stamp_fallback(
    raw: bytes,
    file: UploadFile,
    base_name: str,
    watermark_comment: str,
    submitted_at: datetime,
    correlation_id: str,
) -> tuple[Path, bool, Optional[str]]:
    image_upload = is_image_document(file)
    if not watermark_comment:
        fpath = UPLOAD_DIR / f"{base_name}{upload_extension(file, '.bin')}"
        write_original_upload(raw, fpath)
        return fpath, False, None

    stamped_path = UPLOAD_DIR / f"{base_name}.pdf"
    try:
        if image_upload:
            with open(stamped_path, "wb") as f:
                f.write(render_image_with_note_pdf(raw, watermark_comment, submitted_at))
        else:
            with open(stamped_path, "wb") as f:
                f.write(append_submission_note_page(raw, watermark_comment, submitted_at))
        return stamped_path, True, None
    except Exception:
        logger.exception(
            "Client-approved upload stamping failed correlation_id=%s upload=%s",
            correlation_id,
            upload_log_context(file, raw),
        )
        fallback_path = UPLOAD_DIR / f"{base_name}{upload_extension(file, '.bin')}"
        write_original_upload(raw, fallback_path)
        return fallback_path, False, "Client-approved warning was recorded, but document stamping failed; the original upload was saved."


def upload_log_context(file: Optional[UploadFile], raw: Optional[bytes] = None) -> dict:
    if not file:
        return {"filename": "", "content_type": "", "suffix": "", "size": 0}
    return {
        "filename": file.filename or "",
        "content_type": upload_content_type(file),
        "suffix": Path(file.filename or "").suffix.lower(),
        "size": len(raw) if raw is not None else 0,
    }


def pending_upload_log_context(row: Optional[dict]) -> dict:
    if not row:
        return {"pending_upload_id": "", "filename": "", "content_type": "", "suffix": "", "size": 0}
    return {
        "pending_upload_id": row.get("id") or "",
        "filename": row.get("original_filename") or "",
        "content_type": row.get("content_type") or "",
        "suffix": row.get("suffix") or "",
        "size": int(row.get("size_bytes") or 0),
    }


async def create_pending_client_upload(
    session: AsyncSession,
    user: dict,
    endpoint: str,
    item: dict,
    raw: bytes,
    file: UploadFile,
    comment: str,
    ai_review: Optional[dict] = None,
    correlation_id: str = "",
) -> dict:
    pending_id = new_id()
    suffix = upload_extension(file, ".bin")
    stored_filename = f"pending_{pending_id}{suffix}"
    try:
        write_original_upload(raw, UPLOAD_DIR / stored_filename)
    except Exception:
        logger.exception("Pending upload file write failed correlation_id=%s endpoint=%s upload=%s", correlation_id, endpoint, upload_log_context(file, raw))
        raise HTTPException(status_code=400, detail="The uploaded file could not be saved. Please try again.")
    now = datetime.now(timezone.utc)
    row = {
        "id": pending_id,
        "client_id": bounded_text(str(user["id"]), 36),
        "endpoint": bounded_text(endpoint, 32),
        "item_id": bounded_text(item.get("id"), 36) if endpoint == "item" else None,
        "type": bounded_text(item.get("type") or "purchase", 32),
        "description": item.get("description") or "",
        "date": item.get("date") or "",
        "amount": item.get("amount") or "",
        "comment": comment,
        "original_filename": bounded_text(Path(file.filename or "").name or file.filename or "", 255),
        "stored_filename": bounded_text(stored_filename, 255),
        "content_type": bounded_text(upload_content_type(file), 255),
        "suffix": bounded_text(Path(file.filename or "").suffix.lower(), 32),
        "size_bytes": len(raw),
        "file_sha256": hashlib.sha256(raw).hexdigest(),
        "ai_review_json": json.dumps(ai_review or {}) if ai_review else None,
        "status": "pending",
        "created_at": now.isoformat(),
        "expires_at": (now + timedelta(hours=4)).isoformat(),
        "final_submission_id": None,
    }
    try:
        async with engine.begin() as conn:
            await conn.run_sync(lambda sync_conn: pending_client_uploads.create(sync_conn, checkfirst=True))
            await ensure_table_columns(conn, (pending_client_uploads,))
        await session.execute(insert(pending_client_uploads).values(**row))
        await session.commit()
    except SQLAlchemyError:
        await session.rollback()
        logger.exception(
            "Pending upload persistence failed correlation_id=%s endpoint=%s pending_upload_id=%s upload=%s filename_len=%s content_type_len=%s",
            correlation_id,
            endpoint,
            pending_id,
            upload_log_context(file, raw),
            len(row["original_filename"] or ""),
            len(row["content_type"] or ""),
        )
        raise HTTPException(status_code=500, detail=f"Upload could not be prepared for AI review. Reference {correlation_id}.")
    return row


async def get_pending_upload_or_400(session: AsyncSession, user: dict, pending_upload_id: str, endpoint: str, item_id: Optional[str] = None) -> dict:
    pending_id = str(pending_upload_id or "").strip()
    if not pending_id:
        raise HTTPException(status_code=400, detail="Pending upload id is required to submit after approving an AI warning.")
    try:
        async with engine.begin() as conn:
            await conn.run_sync(lambda sync_conn: pending_client_uploads.create(sync_conn, checkfirst=True))
            await ensure_table_columns(conn, (pending_client_uploads,))
        row = await one(
            session,
            select(pending_client_uploads).where(
                pending_client_uploads.c.id == pending_id,
                pending_client_uploads.c.client_id == str(user["id"]),
                pending_client_uploads.c.endpoint == endpoint,
            ),
        )
    except SQLAlchemyError:
        logger.exception("Pending upload lookup failed endpoint=%s pending_upload_id=%s", endpoint, pending_id)
        raise HTTPException(status_code=500, detail="Pending upload could not be loaded. Please upload the document again.")
    if not row or row.get("status") != "pending":
        raise HTTPException(status_code=400, detail="This pending upload is no longer available. Please upload the document again.")
    if item_id and str(row.get("item_id") or "") != str(item_id):
        raise HTTPException(status_code=400, detail="This pending upload does not match the selected item. Please upload the document again.")
    if not (UPLOAD_DIR / Path(row.get("stored_filename") or "").name).exists():
        raise HTTPException(status_code=400, detail="The pending upload file could not be found. Please upload the document again.")
    return row


def upload_proxy_from_pending(row: dict) -> Any:
    class PendingUploadFile:
        filename = row.get("original_filename") or row.get("stored_filename") or "upload.bin"
        content_type = row.get("content_type") or "application/octet-stream"

    return PendingUploadFile()


def pending_ai_review(row: dict) -> Optional[dict]:
    review = parse_json_object(row.get("ai_review_json"))
    return review if review else None


